-- Category routing is local to REDLINE; executor globals and unrelated files are untouched.
local function redlineFiles(http)
 local r,w,d,m,f,i,l=readfile,writefile,delfile,makefolder,isfolder,isfile,listfiles
 local enabled=type(m)=='function'
 local function route(path)
  if not enabled or type(path)~='string'then return path end
  path=path:gsub('\\','/')
  local user,place=path:match('^REDLINE_AuthRemember_(%d+)_(%d+)%.json$')
  if user then return 'REDLINE/Account/Remember_'..user..'_'..place..'.json'end
  local p,kind=path:match('^REDLINE_Device_(%d+)_(%w+)%.json$')
  if p then local category=kind=='Settings'and 'Settings'or kind=='Loader'and 'Settings'or kind=='Farms'and 'Presets'or 'Combat';return 'REDLINE/'..category..'/'..kind..'_'..p..'.json'end
  if path=='REDLINE/Shared'or path:match('^REDLINE/Shared/%d+$')or path=='REDLINE/Accounts'or path:match('^REDLINE/Accounts/%d+$')then return 'REDLINE/Presets'end
  local shared=path:match('^REDLINE/Shared/(%d+)/GunSwitch/Preferences%.json$');if shared then return 'REDLINE/Combat/GunSwitch_'..shared..'.json'end
  if path:match('^REDLINE/Shared/%d+/GunSwitch')then return(path:gsub('^REDLINE/Shared/(%d+)/GunSwitch','REDLINE/Presets/GunSwitch_%1'))end
  if path:match('^REDLINE/Accounts/%d+/GunSwitch')then return(path:gsub('^REDLINE/Accounts/(%d+)/GunSwitch','REDLINE/Presets/Legacy_Account_%1_GunSwitch'))end
  if path:match('^REDLINE/Combat/GunSwitch')then return(path:gsub('^REDLINE/Combat/GunSwitch','REDLINE/Presets/Legacy_GunSwitch'))end
  if path=='REDLINE/Data'then return 'REDLINE/Farms'end
  if path:match('^REDLINE/Data/')then return(path:gsub('^REDLINE/Data/','REDLINE/Farms/'))end
  if path:match('^REDLINE_Account_')then return 'REDLINE/Settings/Legacy_'..path:sub(9)end
  local short=path:match('^REDLINE_(.+)$')
  if short then
   local lower=short:lower()
   local category=(lower:find('checkpoint',1,true)or lower:find('route',1,true)or lower:find('speaker',1,true)or lower:find('guncasecooldowns',1,true))and 'Farms'or
    (lower:find('journal',1,true)or lower:find('log',1,true)or lower:find('crash',1,true))and 'Logs'or
    lower:find('autofarm',1,true)and 'Presets'or lower:match('%.png$')and 'Assets'or 'Settings'
   return 'REDLINE/'..category..'/'..short
  end
  return path
 end
 local function directories(path)
  if not enabled then return end
  local parent=path:match('^(.*)/[^/]+$');if not parent then return end
  local current=''
  for part in parent:gmatch('[^/]+')do current=current==''and part or current..'/'..part
   local exists=false;if type(f)=='function'then local ok,value=pcall(f,current);exists=ok and value end
   if not exists then pcall(m,current)end
  end
 end
 if enabled then for _,folder in ipairs({'Farms','Combat','Account','Presets','Logs','Settings','Assets'})do directories('REDLINE/'..folder..'/file')end end
 local groups={
  Combat={combatWhitelist=true,combatBindings=true,combatKeyMode=true,combatOptions=true},
  Farms={farmPlans=true,bankVaults=true,bankUnknownPolicy=true,bankCollectSmall=true,bankATMEnabled=true,bankATMOrder=true,jewelryOptions=true,quickRobberies=true,airdropMode=true,airdropSelected=true,globalLootMode=true,globalLootSelected=true,globalRarity=true,globalOverrides=true,collectNearbyCash=true,earlyMinutes=true,autoSellEnabled=true,fastCash=true,cashInteractionVersion=true},
  Presets={combatProfiles307=true,combatPresets=true},
 }
 local function rawRead(path)
  if type(r)~='function'then return nil end
  local ok,value=pcall(r,path);return ok and type(value)=='string'and value or nil
 end
 local function rawWrite(path,value)
  assert(type(w)=='function','Write file API unavailable');directories(path);w(path,value)
 end
 local function settingsPlace(path)return path:match('^REDLINE/Settings/Settings_(%d+)%.json$')end
 local function decode(raw)local ok,data=pcall(http.JSONDecode,http,raw or '');return ok and type(data)=='table'and data or nil end
 local read,write
 read=function(path)
  local target=route(path);local raw=rawRead(target)
  if not raw and target~=path then
   raw=rawRead(path)
   if raw and type(w)=='function'then
    -- Never delete an imported source. A failed migration leaves it readable.
    local copied=pcall(write,path,raw) -- split combined settings during migration, too
   end
  end
  local place=settingsPlace(target)
  if place and not decode(raw)then raw=rawRead('REDLINE/Settings/Recovery_'..place..'.json')or raw end
  assert(raw~=nil,'File unavailable')
  if place then
   local data=decode(raw)
   if data then
    if data._redline_split~='full'then for category in pairs(groups)do
     local extra=decode(rawRead('REDLINE/'..category..'/Settings_'..place..'.json'))
     if extra and extra._redline_generation==data._redline_generation then for key,value in pairs(extra)do if groups[category][key]then data[key]=value end end
     elseif data._redline_generation then local recovery=decode(rawRead('REDLINE/Settings/Recovery_'..place..'.json'));if recovery then data=recovery;break end end
    end end
    raw=http:JSONEncode(data)
   end
  end
  return raw
 end
 write=function(path,raw)
  local target=route(path);local place=settingsPlace(target);local data=place and decode(raw)
  if data then
   local generation=tostring(os.time())..':'..tostring(os.clock())..':'..tostring({})
   data._redline_generation=generation;data._redline_split='full'
   local backup=http:JSONEncode(data)
   rawWrite('REDLINE/Settings/Recovery_'..place..'.json',backup)
   assert(rawRead('REDLINE/Settings/Recovery_'..place..'.json')==backup,'Settings recovery verification failed')
   rawWrite(target,backup)
   local rest=table.clone(data)
   for category,keys in pairs(groups)do
    local values={_redline_generation=generation};for key in pairs(keys)do if data[key]~=nil then values[key]=data[key];rest[key]=nil end end
    -- Empty documents deliberately clear previous category values.
    rawWrite('REDLINE/'..category..'/Settings_'..place..'.json',http:JSONEncode(values))
   end
   rest._redline_split='split';rawWrite(target,http:JSONEncode(rest))
  else rawWrite(target,raw)end
 end
 local remove=function(path)
  local target=route(path);local first
  if type(d)=='function'then
   local ok,why=pcall(d,target);if not ok then first=why end
   if target~=path then pcall(d,path)end
   if first and rawRead(target)~=nil then error(first)end
  elseif type(w)=='function'and path:match('REDLINE_AuthRemember_')then write(path,'{}')
  else error('Delete file API unavailable')end
 end
 local mkdir=function(path)
  local target=route(path)
  if type(m)~='function'then error('Folder API unavailable')end
  directories(target..'/file');return true
 end
 local isdir=type(f)=='function'and function(path)return f(route(path))end or nil
 local exists=type(i)=='function'and function(path)local target=route(path);return i(target)or target~=path and i(path)end or nil
 local listing=type(l)=='function'and function(path)
  local result,seen={},{};local target=route(path)
  for _,folder in ipairs(target==path and {target}or {target,path})do local ok,items=pcall(l,folder)
   if ok and type(items)=='table'then for _,item in ipairs(items)do if not seen[item]then seen[item]=true;result[#result+1]=item end end
   elseif type(f)=='function'then local checked,present=pcall(f,folder);if checked and present then error('Existing preset folder could not be read')end end
  end
  return result
 end or nil
 return type(r)=='function'and read or nil,type(w)=='function'and write or nil,remove,mkdir,isdir,listing,route
end

