-- Passwords live in a private buffer; a hidden native TextBox contains only masks.
local function redlineSecret(box,limit)
 local raw,display,visible,writing='', '', false, false
 local cursor,selection,erase=1,-1,nil
 limit=limit or 128
 local function chars(s)
  local out={};local ok=pcall(function()for _,cp in utf8.codes(s)do out[#out+1]=utf8.char(cp)end end)
  return ok and out or {}
 end
 local function slice(list,a,b)return table.concat(list,'',a,math.max(a-1,b))end
 local function render(at)
  writing=true;local n=#chars(raw);display=visible and raw or string.rep('*',n)
  box.TextTransparency=0;box.TextStrokeTransparency=1;box.RichText=false;box.MultiLine=false
  box.Text=display
  cursor=math.clamp(at or cursor,1,(visible and #display or n)+1);selection=-1
  pcall(function()if box:IsFocused()then box.CursorPosition=cursor;box.SelectionStart=-1 end end)
  writing=false
 end
 box:GetPropertyChangedSignal('CursorPosition'):Connect(function()if not writing and box.CursorPosition>0 then cursor=box.CursorPosition end end)
 box:GetPropertyChangedSignal('SelectionStart'):Connect(function()if not writing then selection=box.SelectionStart end end)
 box.InputBegan:Connect(function(key)
  local name=key.KeyCode and key.KeyCode.Name
  erase=name=='Delete'and 'delete'or name=='Backspace'and 'backspace'or nil
 end)
 box.Focused:Connect(function()if box.CursorPosition>0 then cursor=box.CursorPosition else cursor=#display+1 end end)
 box:GetPropertyChangedSignal('Text'):Connect(function()
  if writing then return end
  local incoming=box.Text
  if visible then local list=chars(incoming);raw=slice(list,1,math.min(limit,#list));render(box.CursorPosition>0 and box.CursorPosition or #raw+1);return end
  local old=chars(raw);local now=chars(incoming);local count=#old
  local pos=math.clamp(cursor,1,count+1);local first,last=pos-1,pos-1
  local inserted
  if selection and selection>0 and selection~=cursor then
   first=math.min(selection,pos)-1;last=math.max(selection,pos)-1
  elseif #now<count and incoming==string.rep('*',#now)then
   local removed=count-#now
   first=erase=='delete'and math.min(pos-1,#now)or math.max(0,pos-1-removed);last=first+removed
  elseif #now>=count then
   first=pos-1;last=first
  else first,last=0,count end
  local prefix=string.rep('*',first);local suffix=string.rep('*',count-last)
  if incoming:sub(1,#prefix)==prefix and (#suffix==0 or incoming:sub(-#suffix)==suffix)and #incoming>=#prefix+#suffix then
   inserted=incoming:sub(#prefix+1,#incoming-#suffix)
  else
   -- Native paste/IME replacement with a changed selection: retain only matching mask edges.
   first=0;while first<math.min(count,#now)and now[first+1]=='*'do first+=1 end
   local tail=0;while tail<math.min(count-first,#now-first)and now[#now-tail]=='*'do tail+=1 end
   last=count-tail;inserted=slice(now,first+1,#now-tail)
  end
  local add=chars(inserted);local nextRaw=slice(old,1,first)..table.concat(add)..slice(old,last+1,count)
  local list=chars(nextRaw);raw=slice(list,1,math.min(limit,#list));erase=nil
  render(math.min(limit,first+#add)+1)
 end)
 box.Destroying:Connect(function()raw='';display=''end)
 local proxy={}
 setmetatable(proxy,{
  __index=function(_,key)
   if key=='Text'then return raw end
   if key=='SetSecretVisible'then return function(_,value)if visible~=(value==true)then visible=value==true;render(#(visible and raw or display)+1)end end end
   local value=box[key]
   if type(value)=='function'then return function(_,...)return value(box,...)end end
   return value
  end,
  __newindex=function(_,key,value)
   if key=='Text'then local list=chars(tostring(value or ''));raw=slice(list,1,math.min(limit,#list));render(#(visible and raw or string.rep('*',#chars(raw)))+1)
   else box[key]=value end
  end,
 })
