end

-- One token format for public bootstrap and full client; the backend always revalidates it.
local function redlineRememberStore(http,origin,player,file,env)
 local bucket=env.REDLINE_RememberedSessions
 if type(bucket)~='table'then bucket={};env.REDLINE_RememberedSessions=bucket end
 local id=origin..':'..tostring(player.UserId)..':'..tostring(game.PlaceId)
 local store={}
 local function valid(data)
  if type(data)~='table'or data.schema~=1 then return false end
  local now=os.time();local created,expires=tonumber(data.created_at),tonumber(data.expires_at)
  return data.origin==origin and data.roblox_user_id==player.UserId and data.place_id==game.PlaceId and
   type(data.token)=='string'and #data.token>=12 and #data.token<=2048 and created~=nil and expires~=nil and
   created==created and expires==expires and created<=now+120 and expires>now and expires<=created+604800
 end
 function store.clear()
  bucket[id]=nil
  if type(delfile)=='function'then pcall(delfile,file)end
  if type(writefile)=='function'then pcall(writefile,file,'{}')end
 end
 function store.read()
  if valid(bucket[id])then return table.clone(bucket[id])end
  bucket[id]=nil
  if type(readfile)~='function'then return end
  local ok,raw=pcall(readfile,file)
  if not ok or type(raw)~='string'or #raw>4096 then return end
  local decoded,data=pcall(http.JSONDecode,http,raw)
  if not decoded or not valid(data)then store.clear();return end
  bucket[id]=table.clone(data);return table.clone(data)
 end
 function store.save(token,accountId,deadline)
  if type(token)~='string'or #token<12 or #token>2048 then return false,false end
  local old=store.read();local now=os.time()
  local created=old and old.token==token and old.created_at or now
  local expires=math.min(tonumber(deadline)or now,created+604800)
  if old and old.token==token then expires=math.min(expires,old.expires_at)end
  local record={schema=1,token=token,account_id=accountId,created_at=created,expires_at=expires,
   origin=origin,roblox_user_id=player.UserId,place_id=game.PlaceId}
  if not valid(record)then return false,false end
  bucket[id]=record
  local persistent=false
  if type(readfile)=='function'and type(writefile)=='function'then
   local ok,encoded=pcall(http.JSONEncode,http,record)
   if ok then persistent=pcall(writefile,file,encoded)end
  end
  return true,persistent
 end
 return store
end

