  local license=user.license
  if type(license)~='table'then
   if required then return false,'License details missing; reconnect to REDLINE'end
   l.ready=true;l.legacy=true;l.tier='normal';l.features={};l.accountId=user.id;l.expiry=nil;l.accessExpiry=l.timestamp(user.access_expires_at);l.nextChange=nil
   return true
  end
  if license.status~='active'or not({normal=true,free=true,basic=true,premium=true,legacy=true})[license.tier]or
   type(license.features)~='table'or type(license.feature_version)~='string'then return false,'License is unavailable'end
  local features={}
  for _,feature in ipairs(license.features)do if type(feature)~='string'or #feature>100 then return false,'Invalid license feature response'end;features[feature]=true end
