  if user.access_expires_at~=nil and not accessExpiry then return false,'Invalid account expiration'end
  if unified and(type(license.lifetime)~='boolean'or license.lifetime and(expiry~=nil or accessExpiry~=nil)or not license.lifetime and(not accessExpiry or expiry~=accessExpiry))then return false,'License expiration is inconsistent'end
