  end
  if not l.allowed('combat.gun_modifiers')then for _,key in ipairs({'noRecoil','noSpread','instantBullets'})do off('experimental',key)end end
  if not l.allowed('combat.tracers')then for _,key in ipairs({'tracers','impacts','material'})do off('projectile',key)end end
  if not l.allowed('combat.hbe')then off('hbe','enabled');off('hbe','preview');off('hbe','shotAssist')end
