 function l.enforce()
  local auth=state.auth
  local held=l.accessHold==true
  l.accessHold=l.ready and (l.accessExpiry and os.time()>=l.accessExpiry or auth and auth.sessionDeadline and os.time()>=auth.sessionDeadline)and true or false
  if l.accessHold then state.accessGranted=false
  elseif held then state.accessGranted=auth and auth.verified==true and not auth.stopped and not(state.commands and state.commands.blocked)or false end
  local v=state.combat and state.combat.v30
  if v and l.accessHold and not held then if v.uninstall then v.uninstall()end;if v.clearRender then v.clearRender()end end
  if v and held and not l.accessHold and v.changed then v.changed()end
  if v and v.picker and v.pickerAnchor and not l.uiAllowed(v.pickerAnchor)then v.picker:Destroy();v.picker=nil;v.pickerAnchor=nil end
  if v and l.sanitizeCombat(v.settings)and v.changed then v.changed()end
  local config=state.autoFarmConfig
  if config then
   for owner,feature in pairs(l.owners)do
    local def=config.farmDefs and config.farmDefs[owner]
    if def and not l.allowed(feature)then config[def.selection]=false end
   end
  end
  if state.misc and not l.allowed('misc.incognito')then state.misc.auto=false end
  if state.market and state.market.panel and not l.allowed('shop.custom_market')then state.market.close()end
  if state.gui then
   for name,feature in pairs({ActivityOverlay='hud.activity',VitalsOverlay='hud.vitals'})do
    local panel=state.gui:FindFirstChild(name,true);if panel and not l.allowed(feature)then panel.Visible=false end
   end
  end
  if state.themes and state.hubTheme~='REDLINE'and(not l.allowed('settings.themes')or state.hubTheme=='Femboy'and not l.allowed('theme.femboy'))then state.themes.apply('REDLINE',true)end
  local lease=state.work and state.work.lease
  if lease and (not l.ownerAllowed(lease.owner)or lease.owner=='misc'and state.misc and state.misc.label=='Incognito'and not l.allowed('misc.incognito'))then
   lease.cancelRequested=true;lease.noRecovery=true
  end
 end
 function l.badge()
  local role=state.auth and state.auth.user and state.auth.user.role
  if role=='owner'then return 'Owner',true end
  if role=='admin'then return 'Admin',true end
  return l.ready and(l.tier=='free'and 'Free · 24h'or 'Normal')or 'Checking',false
 end
 function l.timeLabel(user)
  local license=user and user.license
  if type(license)~='table'then return user and user.access_expires_at and('Access expires '..tostring(user.access_expires_at):sub(1,10))or 'Lifetime access'end
  if license.lifetime then return 'Lifetime'end
  local expiry=l.timestamp(license.expires_at)
  if not expiry then return 'Expiration unavailable'end
  local left=math.max(0,expiry-os.time());local days=math.floor(left/86400)
  return (days>0 and(days..'d ')or '')..string.format('%02d:%02d:%02d remaining',math.floor(left/3600)%24,math.floor(left/60)%60,left%60)
 end
end
