local function note(level,message)
  local entry=('[%s] %s | %s'):format(os.date('!%H:%M:%S'),level,tostring(message))
  table.insert(state.history,entry)
  while #state.history>512 do table.remove(state.history,1) end
  if level=='ERROR' or level=='WARN' then
    table.insert(state.errors,entry)
    while #state.errors>200 do table.remove(state.errors,1) end
  end
  print('[REDLINE] '..entry)
end
local function log(s)
  s=tostring(s)
  state.status=s
  if ui.status and not(ui.status.GetAttribute and ui.status:GetAttribute('TaskFooter'))then ui.status.Text=s end
  note('INFO',s)
end
local function warning(s) note('WARN',s);state.status=s;if ui.status then ui.status.Text=s end;if state.notify and state.accessGranted then state.notify('WARNING',tostring(s))end end
local function copyDiagnostics()
  local lines={'REDLINE v'..REDLINE_VERSION..' | '..REDLINE_CREATOR,'Account: '..player.Name,'UserId: '..tostring(player.UserId),
    'PlaceId: '..tostring(game.PlaceId),'Quest phase: '..tostring(state.phase),
    'Confirmed ghosts: '..tostring(state.confirmedGhost),'Attempted ghosts: '..tostring(state.attemptedGhost),
    'Mission verified: '..tostring(state.missionVerified),'Amulet equipped: '..tostring(state.amuletHeld),
    'Key in inventory: '..tostring(state.keyInInventory)..' / quest complete: '..tostring(state.serverQuestComplete),
    'Jewelry: '..tostring(state.jewelry and state.jewelry.routeStatus or 'Idle'),
    'Jewelry timer: '..tostring(state.jewelry and state.jewelry.timerSummary and state.jewelry.timerSummary() or 'Not observed'),
    '--- LOG ---'}
  for _,entry in ipairs(state.history) do table.insert(lines,entry) end
  local output=table.concat(lines,'\n')..(state.diagnostics and state.diagnostics.copyText()or '')
  if state.combatDiagnostics then output=output..'\n--- COMBAT SUMMARY ---\n'..state.combatDiagnostics.status()end
  output=output..'\n--- ERRORS AND WARNINGS ---\n'..table.concat(state.errors,'\n')
  local clip=setclipboard or toclipboard
  if type(clip)=='function' then
    local ok=pcall(clip,output)
    if ok then log('REDLINE log copied');return true,output end
  end
  warning('Clipboard unavailable. Use the selectable log box in Settings.')
  return false,output
end
