local function readFile(path)
  if type(readfile)~='function' then return nil end
  local ok,txt=pcall(readfile,path)
  if not ok or type(txt)~='string' then return nil end
  local valid,obj=pcall(HttpService.JSONDecode,HttpService,txt)
  return valid and type(obj)=='table' and obj or nil
end
local function saveFile(path,data)
  if type(writefile)=='function' then
    pcall(writefile,path,HttpService:JSONEncode(data))
  end
end
do
 local storage=state.storage
 function storage.copy(value)
  if type(value)~='table'then return value end
  local out={};for k,v in pairs(value)do out[k]=storage.copy(v)end;return out
 end
 function storage.equal(a,b)
  if type(a)~=type(b)then return false end
  if type(a)~='table'then return a==b end
  for k,v in pairs(a)do if not storage.equal(v,b[k])then return false end end
  for k in pairs(b)do if a[k]==nil then return false end end
  return true
 end
 function storage.mergeProfiles(target,source,origin)
  for id,p in pairs(type(source)=='table'and source or {})do
   if type(p)=='table'and type(p.name)=='string'and type(p.settings)=='table'then
    local duplicate=false;local names={}
    for _,q in pairs(target)do
     if type(q)=='table'and type(q.name)=='string'then names[q.name:lower()]=true;if p.name==q.name and storage.equal(p.settings,q.settings)and storage.equal(p.whitelist or {},q.whitelist or {})and(not(type(p.settings.weaponSwitch)=='table'and p.settings.weaponSwitch.useCustom)or q.localSource==origin)then duplicate=true end end
    end
