     local key=type(id)=='string'and id or 'shared-'..HttpService:GenerateGUID(false)
     if target[key]then key='shared-'..HttpService:GenerateGUID(false)end
     local item=storage.copy(p);item.localSource=origin;local base=item.name:sub(1,32);local serial=2
     while names[item.name:lower()]do item.name=base..' ('..serial..')';serial+=1 end
     target[key]=item
    end
   end
  end
 end
 function storage.readShared(kind)
