    points={Vector3.new(part.Position.X,height,part.Position.Z),Vector3.new(destination.X,height,destination.Z),destination}}
   lease.rubberbandRecovery={kind='ascent',deadline=os.clock()+math.max(12,10/math.max(1,state.speed)*3+8)}
   state.navigationStatus='Pullback '..count..'/17 · Near-target +10 recovery'
