   if validTime and prior and prior.rawSeconds==remaining and prior.drilling==drill and prior.jammed==jam and prior.opened==opened then
    observation=prior.observedAt
   end
   local record={seconds=validTime and remaining or nil,rawSeconds=validTime and remaining or nil,observedAt=observation,
    drilling=drill,jammed=jam,opened=opened,model=model,
    confirmed=validTime,position=pos}
   if not validTime and prior and prior.drilling and not prior.jammed and not prior.opened then
    record.seconds=prior.seconds and math.max(0,prior.seconds-(stamp-prior.observedAt)) or nil
