      local props=type(gizmo.properties)=='table' and gizmo.properties or {}
      local currency=kind=='Cash' or kind=='CashBundle' or kind=='Currency' or gizmo.ClassName=='Cash' or gizmo.ClassName=='CashBundle' or gizmo.name=='Cash' or gizmo.name=='CashBundle' or gizmo.name=='Currency'
      currency=currency or model.Name=='Cash'or model.Name=='CashBundle'or model.Name=='Currency'
      local name=currency and (gizmo.name or model.Name or 'Cash')or props.toolName or props.itemName or gizmo.name
