       result.loot[#result.loot+1]={id=id,name=name,currency=currency,value=value,weight=weight,ratio=ratio,eligible=allowed,model=model,gizmo=gizmo,position=model.PrimaryPart.Position}
      else result.unidentifiedLoot=result.unidentifiedLoot+1 end
     else result.unidentifiedLoot=result.unidentifiedLoot+1 end
    end
   end
  end
  table.sort(result.loot,function(a,b)
   if a.eligible~=b.eligible then return a.eligible end
   local ap,bp=state.globalLoot.priority(a.name),state.globalLoot.priority(b.name)
   if ap~=bp then return ap<bp end
