-- Shared native operations; callers supply verified targets and their own task gate.
state.operations={}
function state.operations.wait(active,seconds,predicate)
 local untilAt=os.clock()+seconds
 repeat
  if not active()then return false,'Canceled'end
  local ok,value=pcall(predicate);if ok and value then return true,value end;task.wait(.1)
 until os.clock()>=untilAt
 return false,'Native state not confirmed'
end
function state.operations.c4(spec)
 local lease=state.work.lease
 if not lease or type(spec)~='table'or type(spec.active)~='function'or type(spec.status)~='function'then return false,'C4 context unavailable'end
 local function active()return state.work.lease==lease and state.work.owns(lease.owner,lease.token)and spec.active()end
 if not active()then return false,'Canceled'end
 local target=spec.target;local point=spec.point or target and objectWorldPosition(target)
 if typeof(target)~='Instance'or typeof(point)~='Vector3'or typeof(spec.retreat)~='Vector3'then return false,'Verified C4 target/retreat unavailable'end
 if(spec.retreat-point).Magnitude<65 then return false,'C4 retreat is too close'end
 local status=spec.status();if status=='OPEN'then return true end
 if status~='CLOSED'then return false,'C4 target state unknown; explosive withheld'end
 local function planted()
  local p=bank.planted
  return p and p.door==target and p.model.Parent and p.model.PrimaryPart and
   (p.model.PrimaryPart.Position-point).Magnitude<=25 and bank.ownedStickies()[p.model]==true
 end
 if not bank.c4Ready()and not planted()then
  if type(spec.supply)~='function'then return false,'C4 supply unavailable'end
  local bought,why=spec.supply();if not bought then return false,why end
 end
 if not active()then return false,'Canceled'end
 if spec.approach then local reached,why=state.work.travel(spec.approach,3);if not reached then return false,why end end
 local prior=bank.breaching;bank.breaching=true
 local ok,result,why=xpcall(function()
  local threw,reason=bank.throwC4(lease.token,target,{active=active,state=spec.status,point=point,hasPlanted=planted})
  if not threw then return false,reason end
  if spec.status()=='OPEN'then return true end
  if not planted()then return false,'Owned planted C4 not confirmed'end
  local reached,reason=state.work.travel(spec.retreat,3);if not reached then return false,reason end
  if not active()then return false,'Canceled'end
  local r=root();local bomb=bank.planted.model
  if not r or not bomb.PrimaryPart or(r.Position-bomb.PrimaryPart.Position).Magnitude<60 then return false,'Safe C4 retreat not reached'end
  if spec.status()=='OPEN'then return true end
  local api=liveModule('ClientPlayers');local client=api and api.Get and api.Get()
  if not client or type(client.Detonate)~='function'then return false,'Native detonation unavailable'end
  local sent,reason=state.work.nativeCall(6,bomb,client.Detonate,client);if not sent then return false,reason end
  return state.operations.wait(active,12,function()return spec.status()=='OPEN'end)
 end,function(err)return tostring(err)end)
 bank.breaching=prior
 if not ok then return false,tostring(result)end;return result,why
end
function state.operations.drainMain(candidate,spec)
 local lease=state.work.lease
 if not lease or not candidate or not spec or type(spec.active)~='function'then return false,'Cash context unavailable'end
 local function active()return state.work.lease==lease and state.work.owns(lease.owner,lease.token)and spec.active()end
 local g=candidate.gizmo
 if not bank.cashKind(g)or type(g.AttemptCollect)~='function'then return false,'Verified cash pile required'end
 if player:GetAttribute('currentTeam')=='police'then return false,'Police cannot collect this cash'end
 local last=bank.cashAmount(g);local progress=os.clock();local deadline=progress+240
 while active()and os.clock()<deadline do
  local amount=bank.cashAmount(g)
  if amount==nil then return false,'Cash balance unavailable; zero not assumed'end
  if amount==0 then return true,'empty'end
  if last and amount>last then return false,'Cash pile reset; rescan required'end
  if last and amount<last then progress=os.clock()end;last=amount
  if os.clock()-progress>12 then return false,'Main cash made no progress'end
  local api=liveModule('ClientGizmos');local id=candidate.objectId or g.objectId
  local identified,current=pcall(function()return api and api.Get and id~=nil and api.Get(id)end)
  if not identified or current~=g then return false,'Cash identity changed or unstreamed'end
  local model=g.model or candidate.model;local position=model and bank.interactionPosition(g,model)
  if not model or not model.Parent or not position then return false,'Cash target unstreamed'end
  if not root()then return false,'Character unavailable'end
  if(root().Position-position).Magnitude>10 then local began=os.clock();local reached,why=state.work.travel(position+Vector3.new(0,1,0),4);progress+=os.clock()-began;if not reached then return false,why end end
  if not active()then return false,'Canceled'end
  local standing,why=state.standingForInteraction();if not standing then return false,why end
  local lease=state.work.lease;lease.interactionCritical=true
  local collected,reason
  if bank.fastCash and not bank.fastCashFallback[g]then collected,reason=bank.fastMainCash(candidate,lease.token,{active=active})end
  if collected==nil then collected,reason=state.work.nativeCall(10,g,g.AttemptCollect,g,player)end
  lease.interactionCritical=false
  if not collected then return false,reason end
  task.wait(.25)
 end
 return false,active()and 'Main cash time limit'or 'Canceled'
end

-- availability assertions. Unstreamed and used cases never become fake "Ready".
state.freeGuns={selected='Light Carbine',token=0,running=false,status='Choose a free weapon',observed={},cache={},lastScan=0}
state.freeGuns.catalog={
  {'RPG-7',43200,'Large','RPG-7'},
  {'AWM',43200,'Large','AWM'},
  {'M4A1',14400,'Medium','M4A1'},
  {'ARX-160',7200,'Medium','ARX-160'},
  {'AUG A1',7200,'Medium','AUG A1'},
  {'AK-47',7200,'Medium','AK-47'},
  {'Benelli M1014',7200,'Medium','Benelli M1014'},
  {'Glock 18c',7200,'Small','Glock 18c'},
  {'UMP 45',3600,'Medium','UMP 45'},
