end
-- Shared paid-request loop. Acknowledged or ambiguous requests are never repeated.
state.purchases={interval=.2,unknown=reloadState and reloadState.purchaseUnknown or {},receipts=reloadState and reloadState.purchaseReceipts or {},busy=false}
function state.purchases.passiveCall(timeout,key,callback,...)
 local p=state.purchases;local lease=p.passiveLease
 if not lease or state.closed or not state.accessGranted then return false,'Purchase canceled'end
 state.work.nativeOutcomes=state.work.nativeOutcomes or setmetatable({},{__mode='k'})
 local prior=state.work.nativeOutcomes[key]
 if state.work.nativeUnknown[key]or prior and prior.started and not prior.result then return false,'Previous native request still needs confirmation'end
 local args=table.pack(...);local ticket={started=false};state.work.nativeOutcomes[key]=ticket
 local worker=task.spawn(function()
  if state.closed or p.passiveLease~=lease or lease.cancelRequested then return end
  ticket.started=true;ticket.result=table.pack(pcall(callback,table.unpack(args,1,args.n)))
 end)
 local untilAt=os.clock()+timeout
 while not ticket.result and not state.closed and not lease.cancelRequested and p.passiveLease==lease and os.clock()<untilAt do task.wait(.05)end
 if not ticket.result then
  if not ticket.started then pcall(task.cancel,worker);state.work.nativeOutcomes[key]=nil;return false,'Canceled before native request'end
  state.work.nativeUnknown[key]=true;return false,'Purchase sent; checking inventory update'
 end
 if not ticket.result[1]then state.work.nativeUnknown[key]=true end
 return table.unpack(ticket.result,1,ticket.result.n)
end
function state.purchases.run(spec)
 local p=state.purchases;local lease=state.work.lease;if spec.passive then lease=p.passiveLease end
 if p.busy and not spec.passive and p.passiveLease then
  p.passiveLease.cancelRequested=true
  local untilAt=os.clock()+11
  while p.busy and p.passiveLease and not state.closed and os.clock()<untilAt do task.wait(.05)end
 end
 if not lease or p.busy then return false,'Another purchase is active' end
 local function active()
  if spec.passive then return p.passiveLease==lease and not state.closed and state.accessGranted and not lease.cancelRequested and spec.active()end
  return state.work.lease==lease and state.recovery.active(lease) and spec.active()
 end
 if not active() then return false,'Purchase canceled' end
 if spec.complete() then p.unknown[spec.key]=nil;p.receipts[spec.key]=nil;state.work.nativeUnknown[spec.key]=nil;return true end
 local pending=state.work.nativeOutcomes and state.work.nativeOutcomes[spec.key]
 if pending and pending.started and not pending.result then
  spec.status('Checking inventory update · '..spec.label)
  return false,'Inventory update pending; other tasks can continue'
 end
 if p.unknown[spec.key]or state.work.nativeUnknown[spec.key]then
  local receipt=p.receipts[spec.key]
  local outcome=state.work.nativeOutcomes and state.work.nativeOutcomes[spec.key]
  local settled=not outcome or outcome.result~=nil
  local progress=receipt and spec.progress and spec.progress(receipt.before)
  local refused=outcome and outcome.result and outcome.result[1]==true and outcome.result[2]==false
  local unchanged=false
  if receipt and refused then
   local data=liveModule('ClientData')
   local ok,cash=pcall(function()return data and data.Get('cash')end)
   unchanged=ok and cash==receipt.balance and not spec.changed(receipt.before)
  end
  if settled and (progress or unchanged or refused and not receipt)then
   p.unknown[spec.key]=nil;p.receipts[spec.key]=nil;state.work.nativeUnknown[spec.key]=nil
   if state.work.nativeOutcomes then state.work.nativeOutcomes[spec.key]=nil end
  else
   spec.status('Checking inventory update · '..spec.label)
   return false,'Inventory update pending; other tasks can continue'
  end
 end
 local net=liveModule('Network');local data=liveModule('ClientData')
 if not net or type(net.InvokeServer)~='function' or not data or type(data.Get)~='function' then return false,'Purchase API unavailable' end
 p.busy=true
 if spec.travelFirst then
  local function route()
   -- Check affordability before committing to a shop trip; recheck before every payment.
   local verb,_,cost,why=spec.prepare()
   if not verb then return false,why or 'Purchase details unavailable'end
   local got,balance=pcall(data.Get,'cash')
   if not got or type(balance)~='number'or type(cost)~='number'or cost<0 then return false,'Cash or price unavailable'end
   if balance<cost then return false,('Not enough cash ($%d needed)'):format(cost)end
   for leg=1,3 do
    if not active()or lease.preemptRequested then return false,'Paused before purchase'end
    local point=spec.destination();local r=root()
    if not point or not r then return false,'Shop location unavailable'end
    if spec.instantNearby and (r.Position-point).Magnitude<=12 then return true end
    spec.status('Traveling to shop · '..spec.label)
    local priorSupply=lease.supplyTravel;lease.supplyTravel=true
    local moved,why=state.work.travel(point,4,function()return not active()or lease.preemptRequested end)
    lease.supplyTravel=priorSupply
    if not active()or lease.preemptRequested then return false,'Paused before purchase'end
    if not moved then return false,why or 'Could not reach shop'end
    -- Map fallback arrival must resolve again before submitting a paid request.
    local untilAt=os.clock()+2
    repeat
     local resolved=spec.destination();local here=root()
     if resolved and here and (here.Position-resolved).Magnitude<=4 then
      if spec.onApproach and not spec.instantNearby then return spec.onApproach()end
      return true
     end
     if not active()or lease.preemptRequested then return false,'Paused before purchase'end
     task.wait(.1)
    until os.clock()>=untilAt
   end
   return false,'Shop approach not confirmed'
  end
  local safe,reached,why=pcall(route)
  if not safe or not reached then p.busy=false;if spec.finish then pcall(spec.finish)end;return false,safe and why or tostring(reached)end
 end
 local job={done=false,rejected=false,stopped=false};local deadline=os.clock()+180
 local function stop(ok,why)job.done=true;job.ok=ok;job.why=why end
 local worker=task.spawn(function()
  if not spec.passive then motion.callers[coroutine.running()]=lease end
  local ok,err=xpcall(function()
   while active() and not job.stopped and os.clock()<deadline do
    while (job.opening or job.approachNeeded)and active()and not job.stopped do task.wait(.02)end
