 local ok,tagged=pcall(function()return game:GetService('CollectionService'):GetTagged('GameShop')end)
 if ok then for _,part in ipairs(tagged)do if part.Name=='GunShop'and part:IsA('BasePart')and part:IsDescendantOf(workspace)then add(part.Position+Vector3.new(0,2,0))end end end
