 function jewelry.remaining(record)
  record=record or jewelry.lastVault
  if not record or not record.drilling or record.opened or type(record.seconds)~='number' then return nil end
  return math.max(0,record.seconds-(record.jammed and 0 or math.max(0,os.clock()-record.observedAt)))
 end
 function jewelry.returnETA()
  local r=root();local v=jewelry.lastVault
  if not r then return math.huge end
  local eta=state.recovery.cost(r.Position,v and v.position or jewelry.center)
  return type(eta)=='number' and math.max(0,eta)+8 or math.huge
 end
 function jewelry.returnDue()
  if jewelry.phase~='waiting' then return false end
  local v=jewelry.lastVault
  if not v then return true end
  if v.opened or v.jammed then return true end
  local remaining=jewelry.remaining(v)
  return remaining==nil or remaining<=jewelry.returnETA()+5
 end
 function jewelry.timerSummary()
  local v=jewelry.lastVault
  if not v then return 'Vault Timer · Not observed' end
  if v.opened then return 'Vault · Open' end
  if v.jammed then return 'Vault · Jammed' end
  local remaining=jewelry.remaining(v)
  if remaining then
   local depart=math.max(0,remaining-jewelry.returnETA()-5)
   remaining=math.ceil(remaining)
   return ('Vault Timer · %02d:%02d · return in %ds'):format(math.floor(remaining/60),remaining%60,math.floor(depart))
  end
  return v.drilling and 'Vault Timer · Awaiting reading' or 'Vault · No active cracker'
 end
 function jewelry.lootAvailable(g,model)
