  if type(s.collectedPlayers)=='table' and table.find(s.collectedPlayers,player.UserId) then return false end
  local p=type(g.properties)=='table' and g.properties or {};local now=workspace:GetServerTimeNow()
  if type(p.timestamp)=='number' and type(p.collectDelay)=='number' and now<p.timestamp+p.collectDelay then return false end
  if s.priorityPlayerId and s.priorityPlayerId~=player.UserId and type(s.lastEnabled)=='number' and now<s.lastEnabled+6 then return false end
