 function jewelry.behindClosedVault(entry,scan)
  for _,v in ipairs((scan or {}).targets or {}) do
   if v.kind=='JewelryVaultDoor'and v.model and v.model.Parent and v.model:GetAttribute('isOpen')~=true then
    if entry.model and entry.model:IsDescendantOf(v.model) then return true end
    local parent=entry.model and entry.model.Parent
    while parent and parent~=workspace do
     local key=parent.Name:lower():gsub('[%s_%-]','')
     if key=='vaultroom' or key=='jewelryvault' or key=='jewelryvaultroom' then return true end
     parent=parent.Parent
    end
    local origin=jewelry.interiorAnchor or jewelry.center
    local target=entry.position
    if target and (target-origin).Magnitude>.01 then
     local params=RaycastParams.new();params.FilterType=Enum.RaycastFilterType.Include
     local door=v.model:FindFirstChild('InteriorDoor')
     params.FilterDescendantsInstances={door or v.model};params.RespectCanCollide=false
     local hit=workspace:Raycast(origin,target-origin,params)
     if hit then return true end
    end
   end
  end
  return false
 end
