 jewelry.vaultCasePositions={
  Vector3.new(-623.501,42.933,-2806.665),Vector3.new(-623.079,42.4,-2823.107),
  Vector3.new(-611.343,42.4,-2821.667),Vector3.new(-626.253,42.4,-2823.498),
