 function jewelry.interiorCase(entry,scan)
  if not entry then return false end
  local model=entry.model
  local function replay(hits)
   for index in pairs(hits or {})do jewelry.vaultLandmarksSeen[index]=true end
  end
  if model and jewelry.caseZones[model]~=nil then
   replay(jewelry.caseAnchorHits[model]);return jewelry.caseZones[model]=='vault'
  end
  local parent=model;local inside=false
  while parent and parent~=workspace do
   local name=(parent.Name or ''):lower():gsub('[%s_%-]','')
   if name=='vaultroom'or name=='jewelryvault'or name=='jewelryvaultroom'then inside=true;break end
   parent=parent.Parent
  end
  for _,v in ipairs((scan or jewelry.observed or {}).targets or {})do
   if v.kind=='JewelryVaultDoor'and model and model:IsDescendantOf(v.model)then inside=true;break end
  end
  local glass=model and type(model.FindFirstChild)=='function'and model:FindFirstChild('Glass',true)
  local cf,size
  if model and type(model.GetBoundingBox)=='function'then
   local ok,a,b=pcall(model.GetBoundingBox,model);if ok then cf,size=a,b end
  end
  local hits={}
  for index,point in ipairs(jewelry.vaultCasePositions)do
   local match=glass and glass:IsA('BasePart')and (glass.Position-point).Magnitude<=.75
   if not match and cf and size then
    local p=cf:PointToObjectSpace(point)
    match=math.abs(p.X)<=size.X*.5+.5 and math.abs(p.Y)<=size.Y*.5+.5 and math.abs(p.Z)<=size.Z*.5+.5
   end
   if not match and entry.position then match=(entry.position-point).Magnitude<=2 end
   if match then inside=true;hits[index]=true end
  end
  replay(hits)
  if model and (inside or glass or cf)then
   jewelry.caseZones[model]=inside and 'vault'or 'outside';jewelry.caseAnchorHits[model]=hits
  end
  return inside
 end
 function jewelry.vaultWorkPending()
  local observed=0
  for _ in pairs(jewelry.vaultLandmarksSeen)do observed=observed+1 end
  if observed<#jewelry.vaultCasePositions then return true,observed end
  for key,entry in pairs(jewelry.vaultCaseStates)do
   if not entry.shattered and (jewelry.caseCounts[key]or 0)<1 then return true,observed end
  end
  return false,observed
 end
 function jewelry.caseAccess(entry,scan)
  if not entry or entry.kind~='JewelSpawn' or entry.shattered or entry.id==nil then return false end
  if not entry.model or not entry.model:IsDescendantOf(workspace) then return false end
  if (jewelry.caseCounts[jewelry.caseKey(entry)]or 0)>=jewelry.caseLimit(entry)then return false end
  if entry.reinforced and not jewelry.options.reinforcedCases or not entry.reinforced and not jewelry.options.displayCases then return false end
  if jewelry.interiorCase(entry,scan)and not jewelry.vaultFullyOpen(jewelry.vault(scan))then return false end
  if jewelry.behindClosedVault(entry,scan) then return false end
  return true
 end
 function jewelry.getEquipment(name)
  local data=liveModule('ClientData');local read,items=pcall(function()return data and data.Get('gameItems')end)
  local bestId,bestState,bestAmmo
  if read and type(items)=='table'and type(items.Tool)=='table'then
   for id,item in pairs(items.Tool)do if type(item)=='table'and item.name==name then
    local ammo=tonumber(item.ammo or item.toolState and item.toolState.ammo)or -1
    if not bestId or ammo>bestAmmo then bestId=id;bestState=item;bestAmmo=ammo end
   end end
