 function jewelry.catalog(name)
  local shops=liveModule('GameShops')
  if type(shops)~='table' then return nil end
  for shopName,categories in pairs(shops) do
   if type(shopName)=='string' and type(categories)=='table' then
    if type(categories[name])=='table' and type(categories[name].cost)=='number' then
     return {shopName=shopName,categoryName=shopName,itemType='Tool',itemName=name},categories[name]
    end
    for category,items in pairs(categories) do
     if type(items)=='table' and type(items[name])=='table' and type(items[name].cost)=='number' then
      return {shopName=shopName,categoryName=category,itemType='Tool',itemName=name},items[name]
     end
    end
   end
