 function jewelry.shopPosition(packet,name)
  if name=='Vault Cracker'then
   local point=Vector3.new(-4592.258789062,43.281566620,-6615.555175781)
   local npc=state.resolveNPC and state.resolveNPC('Rod',{x=point.X,y=point.Y,z=point.Z},400)
