 function jewelry.openSupplyShop(name,token,context)
  local function active()return context and context.active()or not context and jewelry.active(token)end
  local lease=state.work.lease
  if not active()or not lease then return false,'Shop canceled'end
  if lease.jewelryShop then return true end
  local packet=jewelry.catalog(name);if not packet then return false,'Shop catalog unavailable'end
  local point=jewelry.shopPosition(packet,name)
  if not point then return false,'Shop location unavailable'end
  local npc;local untilAt=os.clock()+6
  repeat
   npc=state.resolveNPC(name=='Vault Cracker'and 'Rod'or 'Justin',{x=point.X,y=point.Y,z=point.Z},400)
   if npc then break end
   if not active()or lease.preemptRequested then return false,'Shop canceled'end
   task.wait(.1)
  until os.clock()>=untilAt
  if not npc then return false,'Shopkeeper has not streamed in'end
  if context and context.noTravel then
   local here=root();if not here or(here.Position-npc.position).Magnitude>8 then return false,'Move closer to the shopkeeper'end
  else
   local moved,why=state.work.travel(npc.position,4);if not moved then return false,why end
