  local opened,why=state.shopInteraction.open(npc)
  if not opened then jewelry.closeSupplyShop(lease);return false,why end
  local option=state.shopInteraction.findOption(state.shopInteraction.options(npc),'browse')
  if not option then jewelry.closeSupplyShop(lease);return false,'Browse option unavailable'end
  local called,reply=state.work.nativeCall(8,npc.gizmo,option.callback,npc.gizmo)
  if not called then jewelry.closeSupplyShop(lease);return false,tostring(reply)end
  local shops=liveModule('ClientGameShops');local untilAt=os.clock()+6
  repeat
   if not active()then jewelry.closeSupplyShop(lease);return false,'Shop canceled'end
   if shops and type(shops.InShop)=='function'and shops.InShop()then return true end
