  elseif jewelry.options.vault and(not jewelry.ammo('Vault Cracker')or jewelry.ammo('Vault Cracker')<(jewelry.options.crackerCount or 1))then name='Vault Cracker';target=jewelry.options.crackerCount or 1 end
