 function jewelry.prepareSupplies(token,includeCracker)
  local pending={}
  if includeCracker then pending[#pending+1]={name='Vault Cracker',target=jewelry.options.crackerCount or 1}end
  if jewelry.options.reinforcedCases then pending[#pending+1]={name='Buzzsaw',target=jewelry.options.sawCharges or 8}end
  while #pending>0 do
   if not jewelry.active(token)then return false,'Canceled'end
   local nearest,index=math.huge,1;local r=root()
   for i,entry in ipairs(pending)do
    local ready=jewelry.getEquipment(entry.name)~=nil and (jewelry.ammo(entry.name)or -1)>=entry.target
    if ready and (jewelry.options.instantPurchase or jewelry.inInventory(entry.name))then
     index=i;break
    end
    local packet=jewelry.catalog(entry.name)
    local point=packet and jewelry.shopPosition(packet,entry.name)
    local distance=r and point and (r.Position-point).Magnitude or math.huge
    if distance<nearest then nearest=distance;index=i end
   end
   local entry=table.remove(pending,index)
   local ok,why=jewelry.ensureSupply(entry.name,entry.target,token)
   if not ok then return false,why end
  end
  return true
 end
 function jewelry.buySupplies()
