 function jewelry.returnCheckpoint(scan)
  scan=scan or jewelry.observed
  local v=jewelry.vault(scan)
  if not v then
   local saved=jewelry.vaultCheckpoint;local last=jewelry.lastVault
   return saved and last and last.opened and last.model==saved.model and saved.point or nil
  end
  if not v.model or v.model:GetAttribute('isOpen')~=true then jewelry.vaultCheckpoint=nil;return nil end
  if jewelry.vaultCheckpoint and jewelry.vaultCheckpoint.model==v.model then return jewelry.vaultCheckpoint.point end
  local first,distance
  for _,entry in ipairs(scan.targets or {})do
   if entry.kind=='JewelSpawn'and entry.position and jewelry.interiorCase(entry,scan)then
    local d=(entry.position-v.position).Magnitude
    if not first or d<distance then first=entry;distance=d end
   end
  end
  if first then
   local delta=v.position-first.position;delta=Vector3.new(delta.X,0,delta.Z)
   if delta.Magnitude<.1 then delta=Vector3.new(0,0,1)end
   local point=first.position+delta.Unit*2+Vector3.new(0,2,0)
   jewelry.vaultCheckpoint={model=v.model,point=point};return point
  end
 end
 function jewelry.waitForVaultEntry(token)
  local v=jewelry.vault(jewelry.scan())
  while v and v.opened and not jewelry.vaultFullyOpen(v)do
   if not jewelry.active(token)then return false,'Canceled'end
   jewelry.setStage('Vault opening · entering shortly');task.wait(.05)
   v=jewelry.vault(jewelry.scan())
  end
