 end
 function jewelry.enter(token)
  jewelry.setStage('Traveling to Jewelry')
  pcall(jewelry.scan)
  local allowed,delayWhy=jewelry.waitForVaultEntry(token);if not allowed then return false,delayWhy or 'Canceled'end
  local point=jewelry.returnCheckpoint()or jewelry.interiorAnchor or jewelry.center+Vector3.new(0,8,0)
  local reached,why=state.work.travel(point,4)
  if not reached or not jewelry.active(token) then return false,why or 'Canceled' end
  if type(player.RequestStreamAroundAsync)=='function' then task.spawn(function()pcall(player.RequestStreamAroundAsync,player,jewelry.center,5)end) end
  local limit=os.clock()+8
  repeat
   if not jewelry.active(token) then return false,'Canceled' end
   local scan=jewelry.scan()
   if scan.streamed then
    -- Land inside at an actual regular display rather than a roof/map marker.
    local checkpoint=jewelry.returnCheckpoint(scan)
    if checkpoint then return jewelry.localTravel(checkpoint,2)end
    if not jewelry.interiorAnchor then
     for _,entry in ipairs(scan.targets) do
      if entry.kind=='JewelSpawn' and not entry.reinforced and not jewelry.behindClosedVault(entry,scan) then
       local destination=entry.position+Vector3.new(0,2,3)
       reached,why=jewelry.localTravel(destination,1.5)
       if reached and jewelry.active(token) then jewelry.interiorAnchor=destination;return true end
       return false,why or 'Canceled'
      end
     end
    end
    return true
   end
   task.wait(.35)
  until os.clock()>=limit
  return false,'Jewelry props not streamed'
 end
 function jewelry.localTravel(point,tolerance)
  local lease=state.work.lease;local r=root()
  if not lease or not r then return false,'Movement unavailable'end
  local previous=lease.localRouteTravel
  if (r.Position-point).Magnitude<=25 or (r.Position-jewelry.center).Magnitude<=(jewelry.radius or 350) and (point-jewelry.center).Magnitude<=(jewelry.radius or 350)then lease.localRouteTravel=true end
  local called,ok,why=pcall(state.work.travel,point,tolerance)
  lease.localRouteTravel=previous
  if not called then return false,tostring(ok)end
  return ok,why
 end
 function jewelry.vaultAction(v,token)
  if not v or not v.model or not v.model.Parent then return false,'Vault not streamed' end
  if v.id==nil then return false,'Vault object ID unavailable' end
  if v.opened then return true end
  if v.drilling and not v.jammed then return true end
  local point=jewelry.drillPoint(v);if not point then return false,'Drill placement unavailable' end
  local r=root();if not r then return false,'Character unavailable' end
  local delta=r.Position-point;delta=Vector3.new(delta.X,0,delta.Z)
  if delta.Magnitude<.1 then delta=Vector3.new(0,0,1) end
  local reached,why=jewelry.localTravel(point+delta.Unit*3,2)
  if not reached or not jewelry.active(token) then return false,why or 'Canceled' end
  -- Read attributes again after travel: another player may have placed/opened it.
  if v.model:GetAttribute('isOpen') then jewelry.scan();return true end
  local installed=v.model:GetAttribute('drillPlaced')==true
  local jammed=v.model:GetAttribute('isJammed')==true
  if installed and not jammed then jewelry.scan();return true end
  if jammed and not jewelry.options.repairJammedDrill then return false,'Drill jammed; repair disabled' end
  local net=liveModule('Network');if not net or type(net.FireServer)~='function' then return false,'Vault interaction API unavailable' end
  local function perform()
   if not jewelry.active(token) or (root().Position-point).Magnitude>9.5 then return false,'Outside drill range' end
   if jammed then return state.work.nativeCall(5,v.model,net.FireServer,'propInteraction',v.id,'unjam') end
   if not state.tryEquipTool('Vault Cracker',function()return jewelry.active(token)end) then return false,'Vault Cracker equip failed' end
   local tools=itemClient();local equipped=tools and tools.GetLocalEquippedTool and tools.GetLocalEquippedTool()
   if not equipped or equipped.name~='Vault Cracker' or type(equipped.GetId)~='function' then return false,'Equipped cracker ID unavailable' end
   local id=equipped:GetId();local clients=liveModule('ClientPlayers');local client=clients and clients.Get and clients.Get()
   if client and type(client.PlayAnimToward)=='function'then client:PlayAnimToward('reach',point)end
   if client and type(client.Unequip)=='function'then client:Unequip()end
   return state.work.nativeCall(5,v.model,net.FireServer,'propInteraction',v.id,'placeDrill',id)
  end
  jewelry.setStage(jammed and 'Fixing Vault Cracker' or 'Installing Vault Cracker')
  if jammed then
   local hold=os.clock()+3.5
   while jewelry.active(token) and os.clock()<hold do task.wait(.1) end
  end
  if not jewelry.active(token) then return false,'Canceled' end
  local sent,err=perform();if not sent then return false,tostring(err) end
  local deadline=os.clock()+5
  while jewelry.active(token) and os.clock()<deadline and v.model.Parent do
   if v.model:GetAttribute('isOpen') or v.model:GetAttribute('drillPlaced')==true and v.model:GetAttribute('isJammed')~=true then jewelry.scan();return true end
   task.wait(.15)
  end
  return false,'Vault interaction sent; server state not confirmed'
 end
 function jewelry.collectLoot(token,waitForReveal)
  local settle=os.clock()+(waitForReveal and .75 or 0);local count=0
  while jewelry.active(token) and count<60 do
   if state.work.lease.preemptRequested then return false,'Paused for queued action'end
   local scan=jewelry.scan();local best
   for _,entry in ipairs(scan.loot) do
    if entry.eligible and (jewelry.lootRetries[tostring(entry.id)] or 0)<=os.clock() and not jewelry.behindClosedVault(entry,scan) then best=entry;break end
   end
   if not best then
    if os.clock()>=settle then return true end
    task.wait(.18)
   else
    local read,why=bag.read();if not read then return false,why end
    if best.weight and best.weight>bag.capacity then
     jewelry.lootRetries[tostring(best.id)]=os.clock()+120
    elseif best.weight and best.weight>bag.freeWeight+.001 or not best.weight and bag.realFull then
     if not jewelry.requestSale(false) then return false,'Bag full; no sellable contents' end
     return false,'sale'
    else
     local reached,err=jewelry.localTravel(best.position+Vector3.new(0,1.5,0),5)
     if not reached or not jewelry.active(token) then return false,err or 'Canceled' end
     if jewelry.lootAvailable(best.gizmo,best.model) and (best.currency and state.globalLoot.collectCash~=false or not best.currency and filterMatches(best.name)) then
      local method=best.gizmo.AttemptCollect or best.gizmo.Interact
      if type(method)~='function' then return false,'Loot interaction unavailable' end
      local nextPickup=(jewelry.lastLootRequest or -math.huge)+.2
      while jewelry.active(token) and os.clock()<nextPickup do task.wait(.02)end
      if not jewelry.active(token)then return false,'Canceled' end
      jewelry.lastLootRequest=os.clock()
      local before=bag.contentsFingerprint;local pickupLease=state.work.lease;pickupLease.interactionCritical=true
      local originalProperties=best.gizmo.properties
      local cashBundle=best.currency and(best.name=='Cash'or best.name=='CashBundle'or best.gizmo.name=='Cash'or best.gizmo.name=='CashBundle')
      if cashBundle and type(originalProperties)=='table'and originalProperties.currencyName==nil then
       local properties=table.clone(originalProperties);properties.currencyName='cash';best.gizmo.properties=properties
      end
      local sent,reply=state.work.nativeCall(8,best.gizmo,method,best.gizmo,player)
      if not jewelry.active(token) then pickupLease.interactionCritical=false;return false,'Canceled' end
      local verified=false;local untilAt=os.clock()+1.5
      while jewelry.active(token) and os.clock()<untilAt do
       bag.read()
       local s=best.gizmo.gizmoState or {}
       verified=best.gizmo.isCollected==true or s.isCollected==true or s.isDestroyed==true or best.model:GetAttribute('isDestroyed')==true or
        type(s.collectedPlayers)=='table' and table.find(s.collectedPlayers,player.UserId)~=nil or
        bag.contentsFingerprint~=before
       if verified then break end
       task.wait(.05)
      end
      pickupLease.interactionCritical=false
      if verified then jewelry.collected=jewelry.collected+1;settle=math.max(settle,os.clock()+.15)
      else
       jewelry.lootRetries[tostring(best.id)]=os.clock()+10
       if not sent then note('WARN','Jewelry pickup: '..tostring(reply)) end
      end
     end
     count=count+1
    end
   end
  end
  return jewelry.active(token),jewelry.active(token) and nil or 'Canceled'
 end
 function jewelry.breakCase(entry,token,context)
  local function active()return context and context.active()or not context and jewelry.active(token)end
  local function access()return context and context.access()or not context and jewelry.caseAccess(entry,jewelry.scan())end
  local travel=context and context.travel or jewelry.localTravel
  if not access()then return false,'Case inaccessible' end
  local model=entry.model;local target=context and context.cutTarget or entry.position;local r=root()
  if not r then return false,'Character unavailable' end
  local pivot=model:GetPivot();local half=model:GetExtentsSize()*.5
  local localRoot=pivot:PointToObjectSpace(r.Position)
  local normalLocal
  if math.abs(localRoot.X/(half.X+.01))>math.abs(localRoot.Z/(half.Z+.01)) then
   normalLocal=Vector3.new(localRoot.X>=0 and 1 or -1,0,0)
  else normalLocal=Vector3.new(0,0,localRoot.Z>=0 and 1 or -1) end
  local normal=pivot:VectorToWorldSpace(normalLocal);normal=Vector3.new(normal.X,0,normal.Z)
  if normal.Magnitude<.1 then normal=Vector3.new(0,0,1) end
  normal=normal.Unit
  local face=math.abs(normalLocal.X)>.5 and half.X or half.Z
  local stand=target+normal*(context and context.cutTarget and 3 or face+2.5)+Vector3.new(0,entry.reinforced and .6 or 1.5,0)
  local reached,why=travel(stand,1.2)
  if not reached or not active() then return false,why or 'Canceled' end
  if not model:IsDescendantOf(workspace) or model:GetAttribute('objectId')~=entry.id then return false,'Case changed' end
  if model:GetAttribute('isShattered') then return true end
  local localPos=pivot:PointToObjectSpace(root().Position)
  local nearest=pivot:PointToWorldSpace(Vector3.new(math.clamp(localPos.X,-half.X,half.X),math.clamp(localPos.Y,-half.Y,half.Y),math.clamp(localPos.Z,-half.Z,half.Z)))
  if (root().Position-nearest).Magnitude>6.5 then return false,'Outside case range' end
  if not access() then return false,'Case inaccessible' end
  if not entry.reinforced then
   local net=liveModule('Network');if not net or type(net.FireServer)~='function' then return false,'Smash API unavailable' end
   state.work.lease.interactionCritical=true
   local sent,err=state.work.nativeCall(5,model,net.FireServer,'breakJewelCase',entry.id)
   if not sent then state.work.lease.interactionCritical=false;return false,tostring(err) end
  else
   if not state.tryEquipTool('Buzzsaw',function()return active()end) then return false,'Buzzsaw equip failed' end
   if (jewelry.ammo('Buzzsaw') or 0)<=0 then return false,'battery' end
   local tools=itemClient();local tool=tools and tools.GetLocalEquippedTool and tools.GetLocalEquippedTool()
   if not tool or tool.name~='Buzzsaw' then return false,'Buzzsaw not equipped' end
   local lease=state.work.lease;r=root();local hum=r.Parent:FindFirstChildOfClass('Humanoid');local cam=workspace.CurrentCamera
   local cut={tool=tool,root=r,anchored=r.Anchored,hum=hum,autoRotate=hum and hum.AutoRotate,
    camera=cam,cameraType=cam and cam.CameraType,cameraCF=cam and cam.CFrame}
   lease.jewelryCut=cut
   -- Stop the hold tween before turning; it must not fight the cutting pose.
   motion.cancelTween()
   r.CFrame=CFrame.lookAt(r.Position,Vector3.new(target.X,r.Position.Y,target.Z));r.Anchored=true
   if hum then hum.AutoRotate=false end
   if cam then cam.CameraType=Enum.CameraType.Scriptable;cam.CFrame=CFrame.lookAt(target+normal*3.4+Vector3.new(0,2,0),target) end
   if type(tool._inputPrimary)=='function' then
    cut.input=tool._inputPrimary
    local ok=pcall(cut.input,tool,Enum.UserInputState.Begin)
    if not ok then jewelry.cleanup(lease);return false,'Native Buzzsaw input failed' end
   else
    local clients=liveModule('ClientPlayers');cut.client=clients and clients.Get and clients.Get()
    if cut.client and type(cut.client.SetPlayerProperty)=='function' then
     tool.using=true;cut.client:SetPlayerProperty('using',true,true)
    elseif type(mouse1press)=='function' and type(mouse1release)=='function' then cut.mouse=true;mouse1press()
    elseif VirtualInputManager then
     local loc=UserInputService:GetMouseLocation();cut.mouse=true;cut.x=math.floor(loc.X);cut.y=math.floor(loc.Y)
     VirtualInputManager:SendMouseButtonEvent(cut.x,cut.y,0,true,game,0)
    else jewelry.cleanup(lease);return false,'Held Buzzsaw input unavailable' end
   end
  end
  if entry.reinforced then
   local cut=state.work.lease.jewelryCut;local clients=liveModule('ClientPlayers')
   cut.client=cut.client or(clients and clients.Get and clients.Get())
   if not cut.client or type(cut.client.SetPlayerProperty)~='function'then jewelry.cleanup(state.work.lease);return false,'Native saw control unavailable'end
   cut.client:SetPlayerProperty('using',true,true)
  end
  local deadline=os.clock()+(entry.reinforced and 10 or 3)
  while active() and model.Parent and os.clock()<deadline do
   if model:GetAttribute('isShattered')==true then
    state.work.lease.interactionCritical=false
    jewelry.cleanup(state.work.lease);if context and context.complete then context.complete();return true end
    jewelry.broken=jewelry.broken+1
    jewelry.completedCases[tostring(entry.id)]=true
    local key=jewelry.caseKey(entry);jewelry.caseCounts[key]=(jewelry.caseCounts[key]or 0)+1;jewelry.caseTimes[key]=os.clock()
    if jewelry.nextCycleAt<=os.clock() then jewelry.nextCycleAt=os.clock()+jewelry.resetDelay() end
    return true
   end
   task.wait(.1)
  end
  if state.work.lease then state.work.lease.interactionCritical=false end
  jewelry.cleanup(state.work.lease)
  return false,active() and 'Case shatter not confirmed' or 'Canceled'
 end
 function jewelry.observeDrill()
