 local resume={accountId=state.accountId,miscHistory=state.misc and state.misc.history,miscReceipts=state.misc and state.misc.receipts,settings=state.lastSettings,nativeUnknown=state.work.nativeUnknown,nativeOutcomes=state.work.nativeOutcomes,
  purchaseUnknown=state.purchases.unknown,purchaseReceipts=state.purchases.receipts,jewelry={},farm=farmConfig.refreshState(),
  selectedPage=state.selectedPage,farmView=state.farmView,uiScroll=state.uiScroll,windowPosition=state.windowPosition,miniPosition=state.miniPosition,
  history=state.history,errors=state.errors,bankProgress=bankFarm and {resume=bankFarm.resume,availabilityRecords=bankFarm.availabilityRecords,cycleBase=bankFarm.cycleBase,cycleSerial=bankFarm.cycleSerial,wasOpen=bankFarm.wasOpen,lastAttemptedCycle=bankFarm.lastAttemptedCycle},stores=state.storeJobs and state.storeJobs.checkpoint(),military={reveals=militaryScan.reveals,timers=militaryScan.timers,states=militaryScan.states,coverage=militaryScan.coverage,cycles=militaryScan.cycles,collected=militaryScan.collected,needsSell=militaryScan.needsSell},pear={phase=pearStore.phase,needsSell=pearStore.needsSell,finalSale=pearStore.finalSale,cycles=pearStore.cycles,collected=pearStore.collected,lastEntrance=pearStore.lastEntrance,nativeBomb=bank.planted and pearStore.lastEntrance and bank.planted.door==pearStore.lastEntrance.model and bank.planted or nil}}
