-- Idle farm dispatch: preserve an active cycle, then prefer nearby work and age waiting farms.
state.farmDispatch={waiting={},lastStarted={}}
function state.farmDispatch.choose()
 local r=root();if not r then return nil end
 local now=os.clock();local candidates={}
 local function add(owner,ready,point,urgent)
  if not ready or not point then state.farmDispatch.waiting[owner]=nil;return end
  local since=state.farmDispatch.waiting[owner]or now;state.farmDispatch.waiting[owner]=since
  local eta=state.recovery.cost(r.Position,point)
  candidates[#candidates+1]={owner=owner,urgent=urgent==true,score=eta-math.min(90,(now-since)*.2)}
 end
 add('bank',farmConfig.bankRunnable(),bankFarm.snapshot and bankFarm.snapshot.position or state.bankATMs.anchor('oasis'))
 local j=jewelry.ready(false);add('jewelry',j,jewelry.returnCheckpoint()or jewelry.center,j and jewelry.ready(true))
 add('pear',pearStore.ready(),pearStore.center)
 for id,job in pairs(state.storeJobs.jobs)do if id~='quick'then add(id,state.storeJobs.ready(job),job.anchor)end end
 local ready,target=militaryScan.ready(false);local point=target and target.position
 if not point then
  for _,label in ipairs(state.routes.groups.military)do local p=state.locations[label];if p and(not point or(p-r.Position).Magnitude<(point-r.Position).Magnitude)then point=p end end
 end
 local urgent=militaryScan.ready(true);add('military',ready,point,urgent)
 local locked=state.work.farmLock
 for _,entry in ipairs(candidates)do if entry.owner==locked then return locked end end
