end


function state.farmDispatch.jewelryUrgent()
 local v=jewelry.lastVault
 if not v or not jewelry.ready(true)or v.jammed or not(v.drilling or v.opened)then return false end
 local remaining=jewelry.remaining(v)
 if v.opened then remaining=0 end
 local point=v.position or jewelry.center;local r=root()
 if remaining==nil or not point or not r then return false end
 local eta=state.recovery.cost(r.Position,point)
