end
function state.farmDispatch.urgent()
 local military,target=militaryScan.ready(true)
 local j,point,remaining,eta=state.farmDispatch.jewelryUrgent()
 if military then
  -- Crate drops are exposed immediately; prefer them when both timers are close.
  local r=root();local mEta=r and target and target.position and state.recovery.cost(r.Position,target.position)or math.huge
  if not j or mEta<=math.max(eta,remaining)+20 then return 'military' end
