    if lease.owner=='military'and(not farmConfig.militarySelected or player:GetAttribute('currentTeam')=='police')then militaryScan.pause('Military unavailable');return end
    if lease.owner=='pear'and(not farmConfig.pearSelected or player:GetAttribute('currentTeam')=='police')then pearStore.pause('Pear Store unavailable');return end
    if lease.owner=='jewelry' and not jewelry.supplyOnly and (not farmConfig.jewelrySelected or player:GetAttribute('currentTeam')=='police') then jewelry.pause('Jewelry unavailable');return end
