end
function militaryScan.active(token)
 return not state.closed and farmConfig.masterEnabled and farmConfig.militarySelected and characterAlive()and
  player:GetAttribute('currentTeam')~='police'and militaryScan.routeToken==token and state.work.owns('military',token)
end
function militaryScan.pause(reason)
 militaryScan.routeToken=militaryScan.routeToken+1;militaryScan.running=false;militaryScan.setStage(reason or 'Paused')
