  if chest.used==false and militaryScan.states[chest.model]==true then militaryScan.reveals[chest.model]=nil end
  militaryScan.states[chest.model]=chest.used
 end
 for _,crate in ipairs(scan.crates)do
  if crate.position then
   if not crate.opened and militaryScan.states[crate.model]==true then militaryScan.reveals[crate.model]=nil end
   militaryScan.states[crate.model]=crate.opened
   local prior=militaryScan.timers[crate.model]or {};prior.position=crate.position;prior.id=crate.id
   if crate.opened then militaryScan.timers[crate.model]=nil
