function militaryScan.inZone(position)
 if typeof(position)~='Vector3'then return false end
 local labels=state.routes.groups.military
 for i,label in ipairs(labels)do
  local a=state.locations[label];local b=state.locations[labels[i+1]]or a
  if a and b then
   local dx,dz=b.X-a.X,b.Z-a.Z;local length=dx*dx+dz*dz
   local t=length>0 and math.clamp(((position.X-a.X)*dx+(position.Z-a.Z)*dz)/length,0,1)or 0
