function militaryScan.choice(urgent)
 local scan=militaryScan.observed;local now=os.clock();local chosen,bestRank,bestDistance
 if scan and now-(scan.observedAt or 0)<=6 then
  for _,crate in ipairs(scan.crates)do
   if crate.position and crate.model:IsDescendantOf(workspace)then
    local due=crate.unlocked or crate.secondsRemaining~=nil and crate.secondsRemaining<=militaryScan.eta(crate.position)+5
    local reveal=militaryScan.reveals[crate.model]
    local rank=not crate.opened and(crate.unlocked and 0 or due and 1 or not urgent and not crate.hacking and 2)or
     not urgent and crate.opened and not(reveal and reveal.done)and 3
    local distance=root()and(crate.position-root().Position).Magnitude or math.huge
    if rank and(not bestRank or rank<bestRank or rank==bestRank and distance<(bestDistance or math.huge))then chosen=crate;bestRank=rank;bestDistance=distance end
   end
  end
  if chosen then return chosen,'crate'end
  if not urgent then
   local closest,distance
   for _,chest in ipairs(scan.chests)do if chest.used==false and chest.position and chest.model:IsDescendantOf(workspace)then
    local d=root()and(chest.position-root().Position).Magnitude or math.huge
