   end end
   if closest then return closest,'chest'end
  end
 end
 for model,timer in pairs(militaryScan.timers)do
  if model.Parent and type(model.GetAttribute)=='function'and(model:GetAttribute('isOpen')==true or model:GetAttribute('isHacking')==false and model:GetAttribute('unlocked')~=true)then timer.deadline=nil end
  if timer.deadline and now-timer.deadline>180 then timer.deadline=nil end
  if timer.deadline and now>=(timer.nextProbe or 0)and timer.deadline-now<=militaryScan.eta(timer.position)+5 then
   return {model=model,id=timer.id,position=timer.position,cached=true},'timer'
  end
