  if scan and now-(scan.observedAt or 0)<=2 then
   for _,item in ipairs(scan.loot or {})do if item.eligible and item.model and item.position and militaryScan.inZone(item.position)then
    local reveal=militaryScan.reveal(item);reveal.baseline={};reveal.known[item.id]=item.gizmo;reveal.shelf=true;return reveal,'loot'
