function militaryScan.ready(urgent)
 if state.license and not state.license.ownerAllowed('military')then return false end
 if state.closed or not farmConfig.masterEnabled or not farmConfig.militarySelected or militaryScan.running or
  not characterAlive()or player:GetAttribute('currentTeam')=='police'or os.clock()<militaryScan.nextAttempt then return false end
 if militaryScan.needsSell then
  if bag.selling or state.sellRequested then return false end
  if not bag.read()then return false end
  if bag.value>0 then
   if os.clock()-bag.lastFail>=60 then militaryScan.requestSale()end;return false
  end
  militaryScan.needsSell=false
 end
 local entry,kind=militaryScan.choice(urgent)
 if entry then return true,entry,kind end
 if not urgent and os.clock()>=militaryScan.nextScout then return true,nil,'scout'end
