 local reveal=militaryScan.reveals[entry.model]
 if not reveal then
  reveal={model=entry.model,position=entry.position,baseline=entry.opened and {}or af.groundModels(entry.position,65),known={},created=os.clock()}
  militaryScan.reveals[entry.model]=reveal
