end
function militaryScan.drops(reveal)
 local list={};local now=os.clock()
 for id,model in pairs(af.groundModels(reveal.position,65))do
  local name,gizmo=af.readLoot(model)
  if name and gizmo then
   local props=gizmo.properties or {};local source=tostring(props.source or props.locationName or ''):lower()
   local pos=objectWorldPosition(model);local nativeSource=source:find('military',1,true)~=nil or reveal.shelf and pos and militaryScan.inZone(pos)
   local fresh=not reveal.baseline[id]and now-reveal.created<=15 and pos and(pos-reveal.position).Magnitude<=30
   if (nativeSource or fresh or reveal.known[id]==gizmo)and source~='itemdrop'then
    reveal.known[id]=gizmo
    local data=gizmo.gizmoState or {};local currency=name=='Cash'or name=='CashBundle'
    local collected=gizmo.isCollected or data.disabled or data.isDestroyed or model:GetAttribute('isDestroyed')or
     type(data.collectedPlayers)=='table'and table.find(data.collectedPlayers,player.UserId)~=nil
    local allowed=currency and state.globalLoot.collectCash~=false or not currency and filterMatches(name)
    local nativeReady=true;if type(gizmo.CanCollect)=='function'then local ok,value=pcall(gizmo.CanCollect,gizmo);nativeReady=ok and value==true end
    local serverNow=workspace:GetServerTimeNow()
    local reserved=data.priorityPlayerId and data.priorityPlayerId~=player.UserId and type(data.lastEnabled)=='number'and serverNow<data.lastEnabled+6
    if allowed and not collected then list[#list+1]={id=id,model=model,gizmo=gizmo,name=name,currency=currency,position=pos,
     pending=gizmo.collecting==true or not nativeReady or reserved}end
   end
  end
 end
 table.sort(list,function(a,b)
  local pa,pb=a.currency and -1 or state.globalLoot.priority(a.name),b.currency and -1 or state.globalLoot.priority(b.name)
  if pa~=pb then return pa<pb end;return tostring(a.id)<tostring(b.id)
 end)
