end
function militaryScan.sweep(reveal,token)
 militaryScan.setStage('Collecting Military loot');local quiet=0;local deadline=os.clock()+90
 while militaryScan.active(token)and os.clock()<deadline do
  local allowed,why=state.manual.safeBoundary(state.work.lease);if not allowed then return false,why end
  local localFolder=workspace:FindFirstChild('Local');local gizmos=localFolder and localFolder:FindFirstChild('Gizmos')
  if not liveModule('ClientGizmos')or not gizmos then return false,'Military loot not replicated'end
  local list=militaryScan.drops(reveal);local best=list[1]
  if not best then
   for _,g in pairs(reveal.known)do
    local m=g.model;local data=g.gizmoState or {}
    local confirmed=g.isCollected==true or data.disabled==true or data.isDestroyed==true or
     type(data.collectedPlayers)=='table'and table.find(data.collectedPlayers,player.UserId)~=nil or m and m:GetAttribute('isDestroyed')==true
    if not confirmed and(not m or not m.Parent)then return false,'Military loot unstreamed; checking again'end
   end
