   local objects=liveModule('Objects');local weight
   if not best.currency and objects and objects.GetDataProperty then
    local ok,value=pcall(objects.GetDataProperty,best.name,'weight');if ok then weight=tonumber(value)end
   end
   if not best.currency then
    if not bag.read()then return false,'Bag unavailable'end
