   if not militaryScan.active(token)then return false,'Canceled'end
   local standing,why=state.standingForInteraction();if not standing then return false,why end
   local name,gizmo=af.readLoot(best.model)
   if gizmo~=best.gizmo or name~=best.name then return false,'Military loot changed; rescanning'end
   if best.currency and state.globalLoot.collectCash~=false or not best.currency and filterMatches(name)then
    local method=gizmo.AttemptCollect or gizmo.Interact;if type(method)~='function'then return false,'Military pickup unavailable'end
    local lease=state.work.lease;lease.interactionCritical=true;local props=gizmo.properties
    if best.currency and name=='CashBundle'and type(props)=='table'and props.currencyName==nil then local copy=table.clone(props);copy.currencyName='cash';gizmo.properties=copy end
    local sent,why=state.work.nativeCall(8,gizmo,method,gizmo,player)
    local verified=sent and militaryScan.waitFor(token,2,function()
     local data=gizmo.gizmoState or {};return gizmo.isCollected==true or best.model:GetAttribute('isDestroyed')==true or
      data.isDestroyed==true or type(data.collectedPlayers)=='table'and table.find(data.collectedPlayers,player.UserId)~=nil
    end)
    lease.interactionCritical=false
