function militaryScan.interact(entry,kind,token)
 if not militaryScan.active(token)then return false,'Canceled'end
 local reveal
 local reached,why=state.work.travel((entry.interactionPosition or entry.position)+Vector3.new(0,2,0),kind=='crate'and 5 or 8)
 if not reached then return false,why end
 local standing,why=state.standingForInteraction();if not standing then return false,why end
 local lease=state.work.lease;local sent,why
 if kind=='crate'then
  local scan=militaryScan.scan();local current
  for _,crate in ipairs(scan.crates)do if crate.model==entry.model and crate.id==entry.id then current=crate;break end end
  if not current then return false,'Military crate not replicated'end
  if current.opened then reveal=militaryScan.reveal(current);reveal.created=os.clock();return militaryScan.sweep(reveal,token)end
  if current.hacking and not current.unlocked then return true,'Hack running'end
  local net=liveModule('Network');if not net or type(net.FireServer)~='function'or current.id==nil or not current.laptop then return false,'Military laptop unavailable'end
  if current.unlocked then reveal=militaryScan.reveal(current)end
  lease.interactionCritical=true
  sent,why=state.work.nativeCall(5,current.model,net.FireServer,'propInteraction',current.id,'hack')
  if sent then sent,why=militaryScan.waitFor(token,5,function()
   return entry.model:GetAttribute('isOpen')==true or not current.unlocked and(entry.model:GetAttribute('isHacking')==true or entry.model:GetAttribute('unlocked')==true)
  end)end
  lease.interactionCritical=false
