  local api=liveModule('ClientGizmos');local g=api and api.Get and api.Get(entry.id)
  if not g or g.model~=entry.model or g.ClassName~='MilitaryChest'or type(g.Interact)~='function'then return false,'Military chest changed; rescanning'end
  if g.used or g.gizmoState and g.gizmoState.used then return true end
  reveal=militaryScan.reveal(entry)
  local interval=1-(os.clock()-(militaryScan.lastChestAt or -math.huge));if interval>0 then task.wait(interval)end
  militaryScan.lastChestAt=os.clock();lease.interactionCritical=true
  sent,why=state.work.nativeCall(5,g,g.Interact,g)
  if sent then sent,why=militaryScan.waitFor(token,5,function()return g.used==true or g.gizmoState and g.gizmoState.used==true end)end
  lease.interactionCritical=false;if not sent then return false,why end
