function militaryScan.sweepChests(token)
 militaryScan.setStage('Sweeping Military chests')
 local visited={}
 for _=1,64 do
  if not militaryScan.active(token)then return false,'Canceled'end
  local allowed,why=state.manual.safeBoundary(state.work.lease);if not allowed then return false,why end
  local scan=militaryScan.scan()
  for _,crate in ipairs(scan.crates)do
   if crate.unlocked and not crate.opened then return true,'Timed crate ready'end
  end
  local chosen
  for _,chest in ipairs(scan.chests)do
   if chest.used==false and chest.position and not visited[chest.model]then
    if not chosen or root()and(chest.position-root().Position).Magnitude<(chosen.position-root().Position).Magnitude then chosen=chest end
   end
  end
  if not chosen then return true end
  visited[chosen.model]=true
