function militaryScan.discover(token)
 if not militaryScan.coverage or militaryScan.coverage.complete then militaryScan.coverage=state.routes.new('military')end
 for _,timer in pairs(militaryScan.timers)do if timer.deadline and timer.deadline-os.clock()<=militaryScan.eta(timer.position)+15 then timer.nextProbe=os.clock()+20 end end
 return state.routes.find(militaryScan.coverage,function()
  local scan=militaryScan.scan();local entry,kind=militaryScan.choice(false)
  local targets={}
  if entry and kind~='timer'then entry.routeKind=kind;targets[1]=entry end
  local localFolder=workspace:FindFirstChild('Local')
  return {available=scan.truncated~=true and localFolder~=nil and liveModule('ClientGizmos')~=nil,targets=targets}
