function militaryScan.run(urgentOnly)
 local ready,target,kind=militaryScan.ready(urgentOnly==true);if not ready or state.work.lease then return false end
 militaryScan.routeToken=militaryScan.routeToken+1;local token=militaryScan.routeToken;militaryScan.running=true
 local launched=state.work.launch('military',token,function()
  local ok,result,why=xpcall(function()
   if urgentOnly and not militaryScan.choice(true)then militaryScan.setStage('Timed crate no longer due');return true end
   militaryScan.nextScout=os.clock()+120
   militaryScan.setStage('Scanning Military route')
   if not militaryScan.coverage or militaryScan.coverage.complete then militaryScan.coverage=state.routes.new('military')end
   if kind=='timer'and target and target.position then state.routes.focus(militaryScan.coverage,target.id or target.model,target.position)end
   -- Refresh selection at every step so a newly ready timed crate wins over chests.
   for _=1,24 do
    if not militaryScan.active(token)then return false,'Canceled'end
    local allowed,why=state.manual.safeBoundary(state.work.lease);if not allowed then return false,why end
    militaryScan.scan();local entry,entryKind=militaryScan.choice(false)
    if not entry or entryKind=='timer'then
     local found,target=militaryScan.discover(token)
     if not found then return false,target end
