     local unlocked=militaryScan.waitFor(token,math.min(8,math.max(3,(entry.secondsRemaining or 0)+3)),function()
      return entry.model:GetAttribute('unlocked')==true or entry.model:GetAttribute('isOpen')==true
     end)
     if not unlocked then
      local swept,why=militaryScan.sweepChests(token);if not swept or militaryScan.needsSell then return swept,why end
