     end
    else
     militaryScan.setStage(entryKind=='crate'and 'Using Military laptop'or 'Opening Military chest')
     local interacted,why=militaryScan.interact(entry,entryKind,token);if not interacted or militaryScan.needsSell then return interacted,why end
     if entryKind=='crate'then
      local swept,why=militaryScan.sweepChests(token);if not swept or militaryScan.needsSell then return swept,why end
     end
