  end,function(err)return tostring(err)end)
  local lease=state.work.lease;if lease and lease.owner=='military'then lease.interactionCritical=false end
  militaryScan.running=false;militaryScan.nextAttempt=math.max(militaryScan.nextAttempt,os.clock()+(ok and result and 1 or 10))
  if state.work.farmLock=='military'then state.work.farmLock=nil end
  if not ok or not result then militaryScan.setStage(tostring(ok and why or result));if militaryScan.active(token)then note('WARN','Military: '..militaryScan.routeStatus)end end
