end

-- Store workers share native inventory, movement, C4, saw input, and seller receipts.
state.storeJobs={jobs={}}
function state.storeJobs.isOwner(owner)return state.storeJobs.jobs[owner]~=nil end
function state.storeJobs.register(id,definition)
 local job={id=id,label=definition.label,selection=id..'Selected',anchor=state.locations[definition.location],radius=definition.radius,
  mode=definition.mode,doorRequired=definition.doorRequired,expectedCash=definition.expectedCash or 0,
  aliases=definition.aliases,token=0,running=false,nextAttempt=0,nextProbe=0,status='Not selected',
  cycles=0,collected=0,seenCash={},caseCounts={},caseStates={},phase='idle'}
 state.storeJobs.jobs[id]=job;return job
end
function state.storeJobs.active(job,token)
 return not state.closed and farmConfig.masterEnabled and farmConfig[job.selection]and characterAlive()and
  player:GetAttribute('currentTeam')~='police'and job.token==token and state.work.owns(job.id,token)
end
function state.storeJobs.stage(job,text)
 if job.status~=text then note('INFO',job.label..' · '..text)end;job.status=text
 if state.activityRefresh then state.activityRefresh()end
end
function state.storeJobs.pause(job,reason)
 job.token=job.token+1;job.running=false;state.storeJobs.stage(job,reason or 'Paused')
 local lease=state.work.lease;if lease and lease.owner==job.id then lease.cancelRequested=true;lease.noRecovery=true;jewelry.cleanup(lease);if state.quickFarm then state.quickFarm.cleanup(lease)end end
 if state.work.farmLock==job.id then state.work.farmLock=nil end
end
function state.storeJobs.reset(job)
 job.caseRetry={};job.seenCash={};job.caseCounts={};job.deviceDone={};job.atmsDone=false;job.atmState=nil;job.finished=false;job.didWork=false;job.finalSale=false;job.waitFingerprint=nil;job.phase='idle'
end
function state.storeJobs.belongs(job,model,properties,position)
