  local active=function()return state.storeJobs.active(job,token)end
  local ok,result,why=xpcall(function()
   job.phase='working';state.storeJobs.stage(job,'Traveling to '..job.label)
   local streamed=workspace.StreamingEnabled==false
   if type(player.RequestStreamAroundAsync)=='function'then task.spawn(function()local ok=pcall(player.RequestStreamAroundAsync,player,job.anchor,5);if active()then streamed=ok end end)end
   local reached,why=state.work.travel(job.anchor+Vector3.new(0,2,0),5);if not reached then return false,why end
   local confirmed=state.operations.wait(active,8,function()return streamed and state.storeJobs.scan(job).sourceAvailable end)
   if not confirmed then return false,'Waiting for the store to load'end
