    if direction.Magnitude<.1 then direction=Vector3.new(0,0,1)end;direction=direction.Unit
    state.storeJobs.stage(job,'Opening '..job.label)
    local opened,why=state.operations.c4({target=door.model,active=active,status=function()return door.prop and door.prop.broken==true and 'OPEN'or bank.vaultState(door.model)end,
     approach=door.position+direction*14+Vector3.new(0,2,0),retreat=door.position+direction*90+Vector3.new(0,5,0),supply=function()return state.storeJobs.supply(job,token,'C4')end})
