    if pile then
     state.storeJobs.stage(job,'Collecting main cash')
     local drained,why=state.operations.drainMain(pile,{active=active});if not drained then return false,why end
     job.seenCash[pile.id]={gizmo=pile.gizmo,amount=0};job.didWork=true;quiet=0
