     if job.id=='badlands'and not job.atmsDone then
      local cleared,why=state.bankATMs.run(job,token,job,'badlands',active);if not cleared then return false,why end
      scan=state.storeJobs.scan(job)
      local freshCash=false;for _,entry in ipairs(scan.cash)do if entry.amount and entry.amount>0 then freshCash=true;break end end
      if freshCash then continue end
     end
     if job.id=='badlands'then
      local observed=0;for _ in pairs(job.seenCash)do observed+=1 end
      if observed<job.expectedCash then job.phase='waiting';job.waitFingerprint=state.storeJobs.fingerprint(scan);state.storeJobs.stage(job,'Both cash piles not yet observed');return true end
     end
     local best;for _,item in ipairs(scan.items)do if item.eligible and not item.pending then best=item;break end end
     if best then
      state.storeJobs.stage(job,'Collecting '..best.name);local picked,why=state.storeJobs.pickup(job,best,token)
