       if(job.caseCounts[case.key]or 0)<limit then if not case.shattered then
        if not job.caseRetry or os.clock()>=(job.caseRetry[case.key]or 0)then chosen=case;break else pendingCase=true end
       else pendingCase=true end end
      end
      if chosen then
       if chosen.reinforced then local supplied,why=state.storeJobs.supply(job,token,'Buzzsaw');if not supplied then return false,why end end
       state.storeJobs.stage(job,chosen.reinforced and 'Cutting reinforced case'or 'Breaking display case')
       local glass=chosen.model.FindFirstChild and chosen.model:FindFirstChild('Glass',true)
       local cutTarget=glass and glass:IsA('BasePart')and glass.Position or chosen.position
       local broke,why=jewelry.breakCase(chosen,token,{active=active,cutTarget=cutTarget,access=function()return active()and chosen.model:IsDescendantOf(workspace)end,travel=state.work.travel,
        complete=function()job.caseCounts[chosen.key]=(job.caseCounts[chosen.key]or 0)+1;job.caseStates[chosen.key]=true;job.didWork=true end})
       if not broke then
        if not active()or why=='battery'then return false,why end
        job.caseRetry=job.caseRetry or {};job.caseRetry[chosen.key]=os.clock()+10
        state.storeJobs.stage(job,'Case retry queued');task.wait(.1)
       end;quiet=0
      elseif scan.pending or pendingCase then job.phase='waiting';job.waitFingerprint=state.storeJobs.fingerprint(scan);state.storeJobs.stage(job,'Waiting for selected loot or cases');return true
      elseif scan.unidentified>0 then return false,'Store has unidentified loot; checking again'
      else
       if job.id=='badlands'and not job.atmsDone then
        local cleared,why=state.bankATMs.run(job,token,job,'badlands',active);if not cleared then return false,why end
       end
       local seen=0;for _,record in pairs(job.seenCash)do seen+=1;if bank.cashAmount(record.gizmo)~=0 then return false,'Cash depletion not confirmed'end end
       if seen<job.expectedCash then job.phase='waiting';job.waitFingerprint=state.storeJobs.fingerprint(scan);state.storeJobs.stage(job,'Both cash piles not yet observed');return true end
       quiet+=1;if quiet>=3 then
        if job.id=='evidence'and not job.didWork then job.phase='waiting';job.nextProbe=os.clock()+5;state.storeJobs.stage(job,'Waiting for evidence loot');return true end
        if not bag.read()then return false,'Bag unavailable'end
