      end
     end
    end
   end
   return false,active()and 'Store sweep time limit'or 'Canceled'
  end,function(err)return tostring(err)end)
  jewelry.cleanup(state.work.lease);job.running=false
  local lease=state.work.lease;if lease and lease.owner==job.id then lease.interactionCritical=false end
  if not ok or not result then job.nextAttempt=math.max(job.nextAttempt or 0,os.clock()+15);state.storeJobs.stage(job,tostring(ok and why or result));if active()then note('WARN',job.label..': '..job.status)end end
