function state.storeJobs.fingerprint(scan)
 local rows={}
 for _,pile in ipairs(scan.cash)do rows[#rows+1]='cash:'..tostring(pile.id)..':'..tostring(pile.amount)end
 for _,item in ipairs(scan.items)do rows[#rows+1]='item:'..tostring(item.id)..':'..tostring(item.collected)..':'..tostring(item.pending)end
 for _,case in ipairs(scan.cases)do rows[#rows+1]='case:'..case.key..':'..tostring(case.shattered)end
