 local chosen,distance;local r=root()
 for _,job in pairs(state.storeJobs.jobs)do if job.id~='quick'and state.storeJobs.ready(job)then
  local d=r and(job.anchor-r.Position).Magnitude or math.huge
  if not chosen or d<distance then chosen=job;distance=d end
 end end
