end
function state.storeJobs.checkpoint()
 local saved={}
 for id,job in pairs(state.storeJobs.jobs)do
  local row={};saved[id]=row
  for _,key in ipairs({'phase','seenCash','caseCounts','caseStates','finished','wasOpen','lastDoor','needsSell','finalSale','cycles','collected','didWork','waitFingerprint','quickRoute','nextVisit','dropZones','dropBaseline','retryTargets','blastRetryAt','opened','deviceDone','atmsDone','atmState','resumeStop','cashConfirmed','lootUntil','resumeUntil','portRoute','portDone','reveal','manifest','manifestAt','manifestUsed','manifestReceipt','lastCrateAt','cargoCycle'})do row[key]=job[key]end
  if bank.planted and(job.lastDoor and bank.planted.door==job.lastDoor.model or job.atmState and job.atmState.lastDoor and bank.planted.door==job.atmState.lastDoor.model)then row.planted=bank.planted end
