 local ticket=job.cashPending[id]and job.cashPending[id].key and state.work.nativeOutcomes and state.work.nativeOutcomes[job.cashPending[id].key]
 local reply=ticket and ticket.result
 local accepted=reply and reply[1]==true and type(reply[2])=='table'and table.find(reply[2],id)~=nil
 if reply and reply[1]==true and state.work.nativeUnknown then state.work.nativeUnknown[job.cashPending[id].key]=nil end
 local data=g.gizmoState or {}
 local observed=accepted or g.isCollected==true or type(data.collectingPlayerId)=='number'and data.collectingPlayerId==player.UserId or
  type(data.collectedPlayers)=='table'and table.find(data.collectedPlayers,player.UserId)~=nil
