  job.cashConfirmed[id]=g;job.cashSeen[g]=true;job.collected=(job.collected or 0)+1;job.didWork=true
  if accepted and not g.isCollected and type(g.Collect)=='function'then
   if type(g.properties)=='table'and g.properties.currencyName==nil then local p=table.clone(g.properties);p.currencyName='cash';g.properties=p end
