 local floorKinds={WorldItem=true,Lootable=true,Cash=true,CashBundle=true,CashPallet=true}
 local sources={ATM='atm',Register='register',WorldSafe='worldSafe',GasStationSafe='gasSafe',PCBlock='pc'}
 for _,model in ipairs(folder:GetDescendants())do if model:IsA('Model')and model.PrimaryPart then
  local id=model:GetAttribute('objectId');local position=model.PrimaryPart.Position
  if id~=nil and not seen[id]then
   seen[id]=true;local ok,g=pcall(api.Get,id)
   if ok and type(g)=='table'then
    local kind=model:GetAttribute('gizmoType')or g.ClassName;local p=g.properties or {}
    if(kind=='Cash'or kind=='CashBundle')and p.currencyName==nil then p=table.clone(p);p.currencyName='cash';g.properties=p end
    local key=kind=='Register'and 'register'or kind=='ATM'and 'atm'or kind=='WorldSafe'and 'worldSafe'or kind=='GasStationSafe'and 'gasSafe'or kind=='PCBlock'and 'pc'
    if key and(settings[key]or key=='pc')then
     local stop=state.quickFarm.scope(position,kind)
     if stop then
      local e={id=id,objectId=id,gizmo=g,model=model,position=position,kind=kind,stop=stop,priority=1}
      if kind=='ATM'or kind=='Register'then
       local cash=state.quickFarm.value(g,'cashLeft');local broken=state.quickFarm.value(g,'broken')
       e.amount=cash;e.broken=broken;e.known=type(cash)=='number'and type(broken)=='boolean'
       e.ready=e.known and cash>0 and not broken and state.globalLoot.collectCash~=false
      elseif kind=='PCBlock'then
       e.hasFlashDrive=state.quickFarm.value(g,'hasFlashDrive');e.searched=state.quickFarm.value(g,'searched')
       e.known=type(e.hasFlashDrive)=='boolean'and type(e.searched)=='boolean'
