      if e.ready then
       if os.clock()>=(job.retryTargets and job.retryTargets[id]or 0)then result.targets[#result.targets+1]=e else result.deferred=true;result.deferredStops[stop]=true end
      end
     end
    elseif floorKinds[kind]then
     local source=p.source;local sourceKey=sources[source];local allowed=sourceKey~=nil and(settings[sourceKey]or sourceKey=='pc')or job.cashPending and job.cashPending[id]and job.cashPending[id].gizmo==g
     if source~='ItemDrop'and(source==nil or source==''or source=='Safe'or allowed)then
      if not allowed then
       for _,zone in ipairs(job.dropZones or {})do local zoneKey=sources[zone.kind];local safe=zone.kind=='WorldSafe'or zone.kind=='GasStationSafe';local fresh=not(job.dropBaseline and job.dropBaseline[id]);if (zoneKey==nil or zoneKey=='pc'or settings[zoneKey])and os.clock()-zone.at<=45 and(position-zone.position).Magnitude<=(safe and 10 or 24)and(fresh or safe and bank.cashKind(g))then allowed=true;break end end
      end
      if allowed then
       local currency=kind=='Cash'or kind=='CashBundle'or kind=='CashPallet'
       local name=currency and kind or p.toolName or p.itemName or g.name
       local within=false
       for _,label in ipairs(state.routes.groups.quickRun)do if(position-state.locations[label]).Magnitude<=(label:sub(1,3)=='pc 'and 24 or 65)then within=true;break end end
       if within then
        if type(name)~='string'or name=='WorldItem'or name=='Lootable'then result.unknown+=1
        else
         local confirmed,receiptPending=false,false
         if kind=='Cash'or kind=='CashBundle'then confirmed,receiptPending=state.quickFarm.cashState(job,id,g)end
         local data=g.gizmoState or {};local taken=confirmed or job.cashConfirmed and job.cashConfirmed[id]==g or bank.cashKind(g)and bank.cashAmount(g)==0 or g.isCollected or data.disabled or data.isDestroyed or model:GetAttribute('isDestroyed')or
          type(data.collectedPlayers)=='table'and table.find(data.collectedPlayers,player.UserId)
