  local pivot=entry.gizmo and entry.gizmo.cframe or entry.model.PrimaryPart.CFrame;local front=pivot and pivot.LookVector
  if front then front=Vector3.new(front.X,0,front.Z);if front.Magnitude>.1 then delta=front end end
