 if not job.quickRoute or job.quickRoute.complete and not job.resumeStop then state.quickFarm.reset(job)end
 job.token+=1;local token=job.token;job.running=true;job.activeStop=job.resumeStop;job.resumeStop=nil
 local launched=state.work.launch('quick',token,function()
  local active=function()return state.storeJobs.active(job,token)end
  local continuing=function()return active()and(job.activeStop~=nil or not state.quickFarm.mainReady())end
  local ok,result,why=xpcall(function()
   job.phase='working';local deadline=os.clock()+180
