 local folder=workspace:FindFirstChild('Local');folder=folder and folder:FindFirstChild('Gizmos')
 local api=liveModule('ClientGizmos');if not folder or not api or type(api.Get)~='function'then return result end
 result.available=true;local seen={};local radius=mode=='badlands'and 30 or 160
