  if id~=nil and not seen[id]and inside and math.abs(delta.Y)<=(mode=='badlands'and 18 or 28)then
   seen[id]=true;local ok,g=pcall(api.Get,id)
   if ok and type(g)=='table'then
    local kind=model:GetAttribute('gizmoType')or g.ClassName;local p=g.properties or {}
