     local location=tostring(p.locationName or model:GetAttribute('locationName')or ''):lower()
     local admitted=location==''or mode=='badlands'and(location=='badlands bank'or location=='badlands')or mode=='oasis'and(location=='bank'or location=='bank of oasis'or location=='oasis city bank')
     if admitted then
      local amount=state.quickFarm.value(g,'cashLeft');local broken=state.quickFarm.value(g,'broken')
      if type(amount)~='number'or type(broken)~='boolean'then result.unknown+=1
      else result.devices[#result.devices+1]={id=id,objectId=id,gizmo=g,model=model,position=position,kind='ATM',amount=amount,broken=broken,known=true,ready=amount>0 and not broken}end
     end
