     if(source==nil or source=='')and not(actor.baseline and actor.baseline[id])then
      for _,zone in ipairs(actor.dropZones or {})do if os.clock()-zone.at<=45 and(position-zone.position).Magnitude<=24 then attributed=true;break end end
     end
     local data=g.gizmoState or {};local taken=actor.cashConfirmed and actor.cashConfirmed[id]==g or bank.cashKind(g)and bank.cashAmount(g)==0 or g.isCollected or data.disabled or data.isDestroyed or model:GetAttribute('isDestroyed')or type(data.collectedPlayers)=='table'and table.find(data.collectedPlayers,player.UserId)
     if attributed and not taken and state.globalLoot.collectCash~=false then
      local now=workspace:GetServerTimeNow();local pending=g.collecting==true or type(p.timestamp)=='number'and type(p.collectDelay)=='number'and now<p.timestamp+p.collectDelay or
       data.priorityPlayerId and data.priorityPlayerId~=player.UserId and type(data.lastEnabled)=='number'and now<data.lastEnabled+6
