function state.bankATMs.survey(active,actor)
 local scan=state.bankATMs.scan('oasis',actor)
 if #scan.devices>=4 and #scan.missing==0 and scan.available and scan.unknown==0 then actor.oasisSurveyed=true;return true end
 if actor.oasisSurveyed then return #scan.devices>=4 end
 local anchor=state.bankATMs.anchor('oasis');local map=workspace:FindFirstChild('Map');local locations=map and map:FindFirstChild('Locations');local building=locations and locations:FindFirstChild('Bank')
 if not building then return false end
 local points={}
 for _,object in ipairs(building:GetDescendants())do
  local name=object.Name:lower();if name:find('atm',1,true)or name:find('elevator',1,true)then
   local position=objectWorldPosition(object)
   if position and math.abs(position.Y-anchor.Y)<=28 and(position-anchor).Magnitude<=350 then points[#points+1]=position end
  end
 end
 if building:IsA('Model')then
  local ok,cf,size=pcall(building.GetBoundingBox,building)
  if ok and cf and size and size.X<=700 and size.Z<=700 then
   for _,dx in ipairs({-.4,0,.4})do for _,dz in ipairs({-.4,0,.4})do
    local point=cf:PointToWorldSpace(Vector3.new(size.X*dx,0,size.Z*dz));points[#points+1]=Vector3.new(point.X,anchor.Y,point.Z)
   end end
  end
