   covered[key]=true
   local reached=state.work.travel(point+Vector3.new(0,4,0),5);if not reached then return false end
   if type(player.RequestStreamAroundAsync)=='function'then pcall(player.RequestStreamAroundAsync,player,point,3)end
   if not active()then return false end
   scan=state.bankATMs.scan('oasis',actor)
  end
