 local ready=active()and #state.bankATMs.scan('oasis',actor).devices>=4;actor.oasisSurveyed=ready;return ready
end
function state.bankATMs.runLocal(owner,token,checkpoint,mode,active)
 if state.globalLoot.collectCash==false then checkpoint.atmsDone=true;return true end
 if checkpoint.atmsDone then return true end
 local actor=checkpoint.atmState
 if not actor then
  actor={id=mode=='badlands'and 'badlands'or 'bank',selection=mode=='badlands'and 'badlandsSelected'or 'bankSelected',label=mode=='badlands'and 'Badlands Bank'or 'Oasis City Bank',collected=0,opened=0,baseline={}}
  checkpoint.atmState=actor
  local folder=workspace:FindFirstChild('Local');folder=folder and folder:FindFirstChild('Gizmos')
  if folder then for _,model in ipairs(folder:GetDescendants())do local id=model:GetAttribute('objectId');if id~=nil then actor.baseline[id]=true end end end
