 stage(mode=='badlands'and 'Clearing Badlands ATMs'or 'Clearing ground-floor ATMs')
 local streamed=workspace.StreamingEnabled==false
 if type(player.RequestStreamAroundAsync)=='function'then task.spawn(function()local ok=pcall(player.RequestStreamAroundAsync,player,anchor,5);if active()then streamed=ok end end)end
 local moved,why=state.work.travel(anchor+Vector3.new(0,2,0),5);if not moved then return false,why end
