 if mode=='oasis'then state.bankATMs.survey(active,actor)end
 local confirmed=state.operations.wait(active,8,function()
  local scan=state.bankATMs.scan(mode,actor)
  return streamed and scan.available and scan.unknown==0 and #scan.devices+#scan.missing>=4
 end)
 if not confirmed then return false,mode=='badlands'and 'Four Badlands ATMs not yet observed'or 'Waiting for all four ground-floor ATMs'end
 local deadline=os.clock()+120;local quiet=0;local lootUntil=0
 while active()and os.clock()<deadline do
  local boundary,why=state.manual.safeBoundary(state.work.lease);if not boundary then return false,why end
  local scan=state.bankATMs.scan(mode,actor)
  if not scan.available or scan.unknown>0 or #scan.devices+#scan.missing<4 then return false,'Bank ATM replication changed'end
  local cash;for _,entry in ipairs(scan.cash)do if not entry.pending then cash=entry;break end end
  local device;for _,entry in ipairs(scan.devices)do if entry.ready then device=entry;break end end
  if cash then
   local beforeCount=actor.collected or 0
   stage('Collecting ATM cash');local picked,why=state.quickFarm.collectCash(actor,scan.cash,token,active)
   if picked==nil then picked,why=state.storeJobs.pickup(actor,cash,token,{active=active})end
   if not picked then return false,why end
   if mode=='badlands'then owner.collected=(owner.collected or 0)+(actor.collected-beforeCount);owner.didWork=true else bankFarm.looted=(bankFarm.looted or 0)+(actor.collected-beforeCount) end
