 end
 function m.wait(active,seconds,predicate)
  local deadline=os.clock()+seconds
  repeat
   if not active()then return false end
   if predicate and predicate()then return true end
   if os.clock()>=deadline then return predicate==nil end
   task.wait(.05)
  until false
