 function m.clearReceipt(key)
  m.receipts[key]=nil;state.work.nativeUnknown[key]=nil
  if state.work.nativeOutcomes then state.work.nativeOutcomes[key]=nil end
 end
 -- Persist the delivered request until its late reply or actual state resolves it.
 -- A second click reconciles that request; it never submits an uncertain payment twice.
 function m.transact(key,verb,args,active,observe,accept,fire)
  local record=m.receipts[key]
  local function resolved()
   local observed=observe and observe()
   local outcome=state.work.nativeOutcomes and state.work.nativeOutcomes[key]
   local reply=outcome and outcome.result
   if reply and reply[1]==true then
    if reply[2]==false then return true,false,reply[3]end
    if accept and accept(table.unpack(reply,2,reply.n))then return true,true,reply end
   end
   if observed then return true,true end
   return false
  end
  if record then
   local done,ok,detail=resolved()
   if done then m.clearReceipt(key);return ok,detail or (ok and 'Confirmed'or 'Server declined request')end
   return false,'Previous request is still syncing; try again after the update'
  end
  if not active()then return false,'Canceled'end
  local net=liveModule('Network');local fn=net and (fire and net.FireServer or net.InvokeServer)
  if type(fn)~='function'then return false,'Game service unavailable'end
  local purchases=state.purchases
  if purchases and purchases.busy then
   if purchases.passiveLease then purchases.passiveLease.cancelRequested=true end
   if not m.wait(active,11,function()return not purchases.busy end)then return false,'Another purchase is finishing; try again shortly'end
  end
  if not active()then return false,'Canceled'end
  local lease=state.work.lease;local wasCritical=lease.purchaseCritical
  if purchases then purchases.busy=true end;lease.purchaseCritical=true
  m.receipts[key]={verb=verb,args=args,at=os.clock(),serverTime=os.time()}
  local result=table.pack(pcall(state.work.nativeCall,15,key,fn,verb,table.unpack(args,1,args.n)))
  if purchases then purchases.busy=false end;lease.purchaseCritical=wasCritical
  if not result[1]then return false,tostring(result[2])end
  local called,reply,detail,extra=table.unpack(result,2,result.n)
  if not called then
   local outcome=state.work.nativeOutcomes and state.work.nativeOutcomes[key]
   if not outcome or not outcome.started then m.clearReceipt(key)end
   return false,tostring(reply)
  end
  if reply==false then m.clearReceipt(key);return false,type(detail)=='string'and detail or 'Server declined request'end
  if accept and accept(reply,detail,extra)then m.clearReceipt(key);return true,table.pack(true,reply,detail,extra)end
  if observe and m.wait(active,10,observe)then m.clearReceipt(key);return true,'Confirmed'end
  return false,'Request sent; inventory is still syncing'
 end
 function m.queue(label,callback,automatic)
  if label=='Incognito'and state.license and not state.license.allowed('misc.incognito')then return false end
  if m.busy or state.closed or not state.accessGranted then return false end
  m.busy=true;m.label=label;m.automatic=automatic==true;m.status='Queued · '..label
  local queued=state.work.request(label,function()
   m.token=m.token+1;local token=m.token
   local launched=state.work.launch('misc',token,function()
    local ok,success,why=xpcall(function()return callback(function()return m.active(token)end)end,function(e)return tostring(e)end)
    m.busy=false;m.nextTry=os.clock()+15
    m.status=not ok and ('Could not complete · '..tostring(success))or success and (why or 'Completed')or (why or 'Canceled')
   end)
   if not launched then m.busy=false;m.status='Could not start · try again'end
  end,automatic)
  if not queued then m.busy=false;m.status='Action already queued'end
  return queued
 end
 function m.goIncognito(automatic)
  if state.license and not state.license.allowed('misc.incognito')then return false,'Access unavailable'end
  return m.queue('Incognito',function(active)
   if automatic and not m.auto then return false,'Incognito renewal canceled'end
   if player:GetAttribute('currentTeam')~='syndicate'then return false,'Incognito requires the Syndicate team'end
   local effect=m.incognito()
   if effect.infinite then return true,'Incognito · unlimited'end
   if automatic and effect.active and (not effect.left or effect.left>15)then return true,'Incognito is active'end
   if effect.active then m.clearReceipt('miscIncognito');if not automatic then return true,'Incognito is already active'end end
   local candidate=m.nearestNPC();if not candidate then return false,'No Incognito contact found'end
   if not effect.cost then return false,'Incognito price unavailable'end
   local balance=m.data('cash');if type(balance)~='number'or balance<effect.cost then return false,'Not enough cash for Incognito'end
   m.status='Traveling to '..candidate.name
   local reached,why=state.work.travel(candidate.position,5,function()return not active()or automatic and not m.auto end)
   if not reached then return false,why end
   local npc;local streamed=m.wait(active,4,function()
    npc=state.resolveNPC(candidate.name,{x=candidate.position.X,y=candidate.position.Y,z=candidate.position.Z},30)
    return npc~=nil
   end)
   if not streamed or not npc then return false,'Contact has not loaded; try again nearby'end
   -- Reapproach the actual live prompt, not an export staging point.
   local p=npc.position;local r=root()
   if not r then return false,'Character unavailable'end
   if (r.Position-p).Magnitude>10 then
    reached,why=state.work.travel(p,5,function()return not active()or automatic and not m.auto end)
    if not reached then return false,why end
   end
   local expires=os.clock()+math.max(0,effect.left or 0)+20
   while m.incognito().active do
    if not active()or automatic and not m.auto then return false,'Incognito renewal canceled'end
    local current=m.incognito()
    if current.infinite then return true,'Incognito · unlimited'end
    if current.left==nil or os.clock()>expires then return false,'Waiting for the current effect to clear'end
    m.status='Renewing in '..math.ceil(current.left)..'s';task.wait(.1)
   end
   if not active()or automatic and not m.auto then return false,'Incognito renewal canceled'end
   effect=m.incognito();balance=m.data('cash');r=root()
   if effect.active then return true,'Incognito is active'end
   if player:GetAttribute('currentTeam')~='syndicate'then return false,'Incognito requires the Syndicate team'end
   if not npc.model.Parent or not npc.model.PrimaryPart or not r or (r.Position-npc.model.PrimaryPart.Position).Magnitude>15 then return false,'Move closer to the Incognito contact'end
   if not effect.cost or type(balance)~='number'or balance<effect.cost then return false,'Not enough cash for Incognito'end
   m.status='Purchasing Incognito'
   local ok,reason=m.transact('miscIncognito','setIncognito',table.pack(true),active,function()return m.incognito().active end,nil)
   return ok,ok and 'Incognito activated'or reason
  end,automatic)
 end
 function m.setAuto(value)
  if value and state.license and not state.license.allowed('misc.incognito')then return false,'Access unavailable'end
  m.auto=value==true;m.nextTry=0
  if not m.auto and m.busy and m.label=='Incognito'and m.automatic then
   state.work.cancelPending('Incognito');if not state.work.lease or state.work.lease.owner~='misc'then m.busy=false end
  end
 end
 function m.buyCrates()
  -- Capture the displayed quote before enqueueing. Changes to the form cannot change a queued order.
  local quote,why=m.crateQuote(m.crateType,m.quantity);if not quote then m.status=why;return false end
  return m.queue('Buy crates',function(active)
   local pending=m.receipts.miscBuyCrates
   if pending then
    local ok,reason=m.transact('miscBuyCrates','purchaseLootbox',pending.args,active,nil,function(reply)return reply==true end)
    return ok,ok and 'Previous crate purchase confirmed'or reason
   end
   local current,reason=m.crateQuote(quote.name,quote.quantity)
   if not current or current.unit~=quote.unit then return false,reason or 'Crate price changed; review the new total'end
   if not m.receipts.miscBuyCrates then
    local balance=m.data('cash');if type(balance)~='number'or balance<quote.total then return false,'Not enough cash for this order'end
   end
   local before=m.crateCount(quote.name)
   if before==nil then return false,'Crate inventory unavailable'end
   m.status='Buying '..quote.quantity..' '..quote.label..' crates'
   local ok,detail=m.transact('miscBuyCrates','purchaseLootbox',table.pack(quote.name,quote.quantity),active,
    function()local n=m.crateCount(quote.name);return n~=nil and n>=before+quote.quantity end,function(reply)return reply==true end)
   return ok,ok and ('Purchase confirmed · '..quote.quantity..' '..quote.label..' crates')or detail
  end)
 end
 function m.useCrates()
  return m.queue('Open all crates',function(active)
   for key,record in pairs(m.receipts)do
    if key:sub(1,9)=='miscOpen:'then
     local ok,reason=m.transact(key,'openLootbox',record.args,active,nil,function(reply,rewards)return reply==true and type(rewards)=='table'and next(rewards)~=nil end)
     if ok then m.logRewards('Crates',reason)end
     return ok,ok and 'Previous rewards confirmed · press again for remaining crates'or reason
    end
   end
   local list=m.crateCatalog();if type(list)~='table'then return false,'Crate catalog unavailable'end
   local types={};for name in pairs(list)do types[#types+1]=name end;table.sort(types)
   local opened=0
   for _,name in ipairs(types)do
    local remaining=m.crateCount(name);if remaining==nil then return false,'Crate inventory unavailable'end
    -- Snapshot this type. Crates acquired while opening are left for the next click.
    while remaining>0 do
     if not active()then return false,'Canceled · '..opened..' crates opened'end
     local owned=m.crateCount(name);if owned==nil then return false,'Crate inventory unavailable'end
     local amount=math.min(100,remaining,owned);if amount<1 then break end
     m.status='Opening '..amount..' '..(list[name].displayName or name)..' crates'
     local ok,detail=m.transact('miscOpen:'..name,'openLootbox',table.pack(name,amount),active,
      function()local count=m.crateCount(name);return count~=nil and count<=owned-amount end,
      function(reply,rewards)return reply==true and type(rewards)=='table'and next(rewards)~=nil end)
     if not ok then return false,detail end
     m.logRewards(list[name].displayName or 'Crates',detail)
     opened=opened+amount;remaining=remaining-amount
     -- Observe consumption before the next batch, never reopen a stale inventory snapshot.
     if remaining>0 and not m.wait(active,10,function()local count=m.crateCount(name);return count~=nil and count<=owned-amount end)then return false,'Rewards confirmed; crate inventory is still syncing'end
    end
   end
   return true,opened>0 and ('Opened '..opened..' crates · rewards granted')or 'No crates to open'
  end)
 end
 function m.claimCodes()
  return m.queue('Claim all codes',function(active)
   local claimed,rejected,unknown=0,0,0
   for index,code in ipairs(m.codes)do
    if not active()then return false,'Canceled · '..claimed..' codes claimed'end
    m.status='Claiming codes · '..index..' / '..#m.codes
    local ok,detail=m.transact('miscCode:'..code,'claimIncentiveReward',table.pack('code',code:lower():sub(1,50)),active,nil,function(reply)return reply==true end)
    local reason=type(detail)=='string'and detail or nil
    if ok then claimed=claimed+1;m.codeResults[code]='Claimed'
    elseif m.receipts['miscCode:'..code]then unknown=unknown+1;m.codeResults[code]='Pending'
    else rejected=rejected+1;m.codeResults[code]=reason or 'Not available'end
    if reason and (reason:lower():find('cooldown',1,true)or reason:lower():find('too fast',1,true))then
     return false,'Code cooldown · wait a moment and try again'
    end
    if index<#m.codes and not m.wait(active,1.05)then return false,'Canceled · '..claimed..' codes claimed'end
   end
   m.codeStatus=claimed..' claimed · '..rejected..' already used or unavailable'..(unknown>0 and (' · '..unknown..' pending')or '')
   return true,m.codeStatus
  end)
 end
 function m.wheelState()
  local globals=liveModule('Globals');local config=globals and globals.PRIZE_WHEEL
  local last=m.data('lastPrizeWheel')
  if not config or type(config.RESET_TIME)~='number'or last~=nil and type(last)~='number'then return nil,'Wheel timer unavailable'end
  return last and math.max(0,config.RESET_TIME-(os.time()-last))or 0,last
 end
 function m.nearestWheel()
  local api=liveModule('ClientProps');local r=root();if not api or not r then return nil end
  local best,distance;local seen={}
  local function add(prop)
   if type(prop)~='table'or seen[prop]or prop.ClassName~='PrizeWheel'or not prop.model or not prop.model.Parent or not prop.model.PrimaryPart then return end
   seen[prop]=true;local point=prop.model.PrimaryPart.Position
   local prompt=prop.model.FindFirstChild and prop.model:FindFirstChild('PromptAttachment',true)
   if prompt and typeof(prompt.WorldPosition)=='Vector3'then point=prompt.WorldPosition end
   local d=(r.Position-point).Magnitude
   if not distance or d<distance then best={prop=prop,position=point};distance=d end
  end
  for _,prop in pairs(api.worldProps or {})do add(prop)end
  for _,prop in pairs(api.worldPropsById or {})do add(prop)end
  return best
 end
 function m.collectWheelDrops(checkpoint,active)
  local reward=checkpoint.reward
  if reward and reward.itemType=='Vehicle'then return true end
  local seen=checkpoint.seen or {};checkpoint.seen=seen
  local deadline=os.clock()+12;local lastPickup
  while active()and os.clock()<deadline do
   local pending=false;local discovered=false
   for id,model in pairs(af.groundModels(checkpoint.position,35))do
    local name,g=af.readLoot(model)
    if g and not seen[id]then
     local props=g.properties or {};local source=tostring(props.source or '')
     local currency=name=='Cash'or name=='CashBundle'
     local expected=reward and(currency and reward.itemType=='Cash'or name==reward.itemName)
     local near=objectWorldPosition and objectWorldPosition(model)or model.PrimaryPart and model.PrimaryPart.Position
     local belongs=source=='PrizeWheel'or source==''and not checkpoint.baseline[id]and expected and near and(near-checkpoint.position).Magnitude<=18
     if belongs then
      discovered=true
      local data=g.gizmoState or {};local taken=g.isCollected==true or data.disabled==true or data.isDestroyed==true or model:GetAttribute('isDestroyed')==true or type(data.collectedPlayers)=='table'and table.find(data.collectedPlayers,player.UserId)~=nil
      if taken then seen[id]=true;checkpoint.collected=true;lastPickup=os.clock()
      else
       pending=true
       if not g.collecting then
        local ready=true;if type(g.CanCollect)=='function'then local ok,value=pcall(g.CanCollect,g,player);ready=ok and value==true end
        if ready and type(g.AttemptCollect)=='function'then
         local point=bank.interactionPosition(g,model)or near
         if not point then return false,'Wheel reward position unavailable'end
         local moved,why=state.work.travel(point+Vector3.new(0,4,0),3,function()return not active()end);if not moved then return false,why end
         if not active()then return false,'Canceled'end
         if currency and props.currencyName==nil then local copy=table.clone(props);copy.currencyName='cash';g.properties=copy end
         local lease=state.work.lease;lease.interactionCritical=true
         local sent,why=state.work.nativeCall(8,g,g.AttemptCollect,g,player)
         lease.interactionCritical=false
         if not sent then return false,why end
         if g.isCollected or not model.Parent or g.gizmoState and(g.gizmoState.disabled or g.gizmoState.isDestroyed)then seen[id]=true;checkpoint.collected=true;lastPickup=os.clock()end
        end
       end
      end
     end
    end
   end
   if checkpoint.collected and not pending and(not lastPickup or os.clock()-lastPickup>=.6)then return true end
   m.status='Collecting daily wheel reward';task.wait(.2)
  end
  return false,active()and 'Spin confirmed; reward pickup pending. Press Spin to retry pickup.'or 'Canceled'
 end
 function m.spinWheel()
  return m.queue('Daily wheel',function(active)
   if m.wheelPickup then
    local collected,why=m.collectWheelDrops(m.wheelPickup,active);if collected then m.wheelPickup=nil end
    return collected,collected and 'Daily reward collected'or why
   end
   local pending=m.receipts.miscWheel
   if pending then
   local ok,reason=m.transact('miscWheel','propInteraction',pending.args,active,function()local stamp=m.data('lastPrizeWheel');return type(stamp)=='number'and stamp>=(pending.serverTime or math.huge)end,nil,true)
    if not ok then return false,reason end
    m.wheelPickup={position=m.wheelPosition,baseline={}}
    local collected,why=m.collectWheelDrops(m.wheelPickup,active);if collected then m.wheelPickup=nil end
    return collected,collected and 'Previous daily reward collected'or why
   end
   local left,before=m.wheelState();if left==nil then return false,before end
   if left>0 and not m.receipts.miscWheel then return false,'Next spin in '..math.ceil(left/60)..' min'end
   local wheel=m.nearestWheel()
   if not wheel and m.wheelPosition then
    local moved,why=state.work.travel(m.wheelPosition,5,function()return not active()end);if not moved then return false,why end
    m.wait(active,5,function()wheel=m.nearestWheel();return wheel~=nil end)
   end
   if not wheel then return false,'Daily wheel location has not loaded yet'end
   m.status='Traveling to daily wheel'
   local moved,why=state.work.travel(wheel.position,5,function()return not active()end);if not moved then return false,why end
   if not active()or not wheel.prop.model.Parent then return false,'Daily wheel unavailable'end
   local prompt=wheel.prop.model.FindFirstChild and wheel.prop.model:FindFirstChild('PromptAttachment',true)
   if prompt and typeof(prompt.WorldPosition)=='Vector3'then
    wheel.position=prompt.WorldPosition;m.wheelPosition=wheel.position
    if root()and(root().Position-wheel.position).Magnitude>6 then
     local approached,reason=state.work.travel(wheel.position,5,function()return not active()end);if not approached then return false,reason end
    end
   end
   local ready,remaining=pcall(wheel.prop._canSpin,wheel.prop)
   if not m.receipts.miscWheel and (not ready or not remaining or wheel.prop.model:GetAttribute('rewardIndex'))then return false,'Daily wheel is not ready'end
   local r=root();if not r or (r.Position-wheel.position).Magnitude>15 then return false,'Move closer to the daily wheel'end
   local baseline=af.groundModels(wheel.position,35)
   local initialReward=wheel.prop.model:GetAttribute('rewardIndex');local rewardIndex
   local function confirmed()
    local index=wheel.prop.model:GetAttribute('rewardIndex');if index~=nil and index~=initialReward then rewardIndex=index end
    local stamp=m.data('lastPrizeWheel');return type(stamp)=='number'and (before==nil or stamp>before)
   end
   local ok,reason=m.transact('miscWheel','propInteraction',table.pack(wheel.prop.objectId,'spin'),active,
    confirmed,nil,true)
   if ok and rewardIndex==nil then m.wait(active,2,function()rewardIndex=wheel.prop.model:GetAttribute('rewardIndex');return rewardIndex~=nil end)end
   if ok then
    local prizes=liveModule('PrizeWheelData');local reward=prizes and prizes[rewardIndex]
    m.log('Daily wheel',m.rewardText(reward)or 'Spin confirmed · reward details unavailable')
    m.wheelPickup={position=wheel.position,baseline=baseline,reward=reward}
    local collected,why=m.collectWheelDrops(m.wheelPickup,active)
    if not collected then return false,why end
    m.wheelPickup=nil
   end
   return ok,ok and 'Daily spin confirmed'or reason
  end)
 end
 function m.tick()
  if not state.closed and state.accessGranted and os.clock()>=(m.nextWheelProbe or 0)then m.nextWheelProbe=os.clock()+5;local wheel=m.nearestWheel();if wheel then m.wheelPosition=wheel.position end end
  if not m.auto or m.busy or state.closed or not state.accessGranted or os.clock()<m.nextTry or not characterAlive()then return end
  if player:GetAttribute('currentTeam')~='syndicate'then return end
  local effect=m.incognito();if effect.infinite then return end
  local _,distance=m.nearestNPC();if not distance then m.nextTry=os.clock()+15;return end
  local lead=15
  if not effect.active or effect.left and effect.left<=lead then m.goIncognito(true)end
 end
end
-- End Miscellaneous native actions.
-- Port uses the native Rod report and ShippingCrate interaction from the supplied export.
state.port={}
do
 local p=state.port
 if type(farmConfig.portType)=='function'then
  local choices={}
  for report,on in pairs(type(farmConfig.portAllowed)=='table'and farmConfig.portAllowed or {})do choices[farmConfig.portType(report)or report]=on end
  farmConfig.portAllowed=choices
 end
 local job=state.storeJobs.register('port',{label='Port Shipping Crates',location='Rod',radius=1500,mode='port',aliases={'shippingcrate','city port'}})
 job.portDone={}
 function p.clean(text)
  if type(text)~='string'then return nil end
  local clean=text:gsub('<[^>]->',''):gsub('%c',' '):gsub('%s+',' '):match('^%s*(.-)%s*$')
  return clean~=''and #clean<=400 and clean or nil
 end
 function p.admitted(report)
  if report=='No valuable crates'then return farmConfig.portPolicy=='Selected reports'and farmConfig.portAllowed[report]==true end
  return report~=nil and(farmConfig.portPolicy~='Selected reports'or farmConfig.portAllowed[report]==true or farmConfig.portType and farmConfig.portAllowed[farmConfig.portType(report)]==true)
 end
 function p.bound(position)
  if typeof(position)~='Vector3'then return false end
  for _,label in ipairs(state.routes.groups.port)do
   local delta=position-state.locations[label]
   if Vector3.new(delta.X,0,delta.Z).Magnitude<=150 and math.abs(delta.Y)<=120 then return true end
  end
  return false
 end
 function p.active(token)return state.storeJobs.active(job,token)end
 function p.stage(text)state.storeJobs.stage(job,text)end
 function p.manifest(token)
  local record=job.manifestReceipt
  local function consume(reply)
   if type(reply)~='table'or reply[1]~=true then return false,'Rod response is still pending'end
   local response=reply[3]
   local text=reply[2]==true and p.clean(type(response)=='table'and response.text or response)
   if reply[2]==false or text and text:lower():find('anything special on the manifest',1,true)then
    job.manifestReceipt=nil;job.manifest='No valuable crates';job.manifestAt=os.clock();job.manifestUsed=false
    local allowed=p.admitted(job.manifest)
    if not allowed then job.nextAttempt=os.clock()+farmConfig.portCheckMinutes*60 end
    p.stage(allowed and 'Checking ordinary Port crates'or 'Rod has no confirmed valuable shipment');return true,allowed
   end
   if not text then return false,'Rod reply was not recognized; another paid check was withheld'end
   job.manifestReceipt=nil;job.manifest=text;job.manifestAt=os.clock();job.manifestUsed=false
   if not farmConfig.portReports[text]then
    local count=0;for _ in pairs(farmConfig.portReports)do count+=1 end
    if count<32 then farmConfig.portReports[text]=true;farmConfig.persist()end
   end
   return true,p.admitted(text)
  end
  if record then
   local outcome=state.work.nativeOutcomes and state.work.nativeOutcomes[record.key]
   if outcome and outcome.result then return consume(outcome.result)end
   return false,'Waiting for the previous Rod response; no second payment sent'
  end
  local globals=liveModule('Globals');local data=liveModule('ClientData')
  local cost=globals and globals.CITY_PORT and tonumber(globals.CITY_PORT.CHECK_CARGO_COST)
  local read,cash=pcall(function()return data and data.Get('cash')end)
  if not cost or not read or type(cash)~='number'or cash<cost then return false,'Not enough cash or Rod price unavailable'end
  local reached,why=state.work.travel(job.anchor,5);if not reached then return false,why end
  local npc
  local loaded=state.operations.wait(function()return p.active(token)end,6,function()
   npc=state.resolveNPC('Rod',{x=job.anchor.X,y=job.anchor.Y,z=job.anchor.Z},120);return npc~=nil
  end)
  if not loaded or not npc or not npc.position then return false,'Rod has not loaded'end
  local part=root();if not part or not p.active(token)then return false,'Rod approach was interrupted'end
  local delta=part.Position-npc.position;local flat=Vector3.new(delta.X,0,delta.Z)
  local direction=flat.Magnitude>.01 and flat.Unit or Vector3.new(0,0,1)
  reached,why=state.work.travel(npc.position+direction*4,1);if not reached then return false,why end
  if not p.active(token)then return false,'Rod approach was interrupted'end
  if state.purchases.busy then return false,'Waiting for the current purchase'end
  local lease=state.work.lease
  local opened,why=state.shopInteraction.open(npc)
  if not opened then return false,why or 'Rod dialogue did not open'end
  local option
  for _,entry in ipairs(state.shopInteraction.options(npc))do
   local label=type(entry.text)=='string'and entry.text:gsub('<[^>]->',''):lower()or ''
   if label:find('any valuable crates today',1,true)and type(entry.callback)=='function'then option=entry;break end
  end
  local function closeDialogue()
   local closed,reason=state.quest.cleanupDialogue(lease);state.camera.release(lease);return closed,reason
  end
  if not option then closeDialogue();return false,'Rod’s shipment question is unavailable'end
  if not p.active(token)or state.purchases.busy then closeDialogue();return false,'Rod interaction was interrupted'end
  read,cash=pcall(data.Get,'cash')
  if not read or type(cash)~='number'or cash<cost then closeDialogue();return false,'Not enough cash to ask Rod'end
  local prior=lease.purchaseCritical
  record={key='portManifest:'..HttpService:GenerateGUID(false),at=os.clock()};job.manifestReceipt=record
  state.purchases.busy=true;lease.purchaseCritical=true;p.stage('Asking Rod about today’s crates')
  local result=table.pack(pcall(state.work.nativeCall,15,record.key,option.callback))
  state.purchases.busy=false;lease.purchaseCritical=prior
  local closed,closeWhy=closeDialogue()
  if not result[1]or not result[2]then
   local outcome=state.work.nativeOutcomes and state.work.nativeOutcomes[record.key]
   if not outcome or not outcome.started then job.manifestReceipt=nil end
   return false,tostring(not result[1]and result[2]or result[3]or 'Rod check is pending')
  end
  local checked,allowed=consume(table.pack(true,table.unpack(result,3,result.n)))
  if not closed then return false,closeWhy or 'Rod dialogue has not closed'end
  return checked,allowed
 end
 function p.scan()
  local folder=workspace:FindFirstChild('Local');folder=folder and folder:FindFirstChild('Gizmos')
  local api=liveModule('ClientGizmos');local result={available=folder~=nil and api~=nil and type(api.Get)=='function',targets={}}
  if not result.available then return result end
  for _,model in ipairs(folder:GetDescendants())do
   if model:IsA('Model')and model.PrimaryPart and p.bound(model.PrimaryPart.Position)then
    local id=model:GetAttribute('objectId');local ok,g=pcall(api.Get,id)
    if model:GetAttribute('gizmoType')=='ShippingCrate'and(not ok or not g or g.model~=model or g.ClassName~='ShippingCrate')then result.available=false end
    if ok and g and g.model==model and g.ClassName=='ShippingCrate'and id~=nil and job.portDone[id]~=g then
     local broken=g.broken==true or g.gizmoState and g.gizmoState.broken==true
     local hasLoot=true
     if broken then local pos=model.PrimaryPart.Position;local drops=p.drops({position=pos,baseline=af.groundModels(pos,40),known={},at=os.clock()});hasLoot=drops~=nil and #drops>0 end
     if hasLoot then result.targets[#result.targets+1]={id=id,model=model,gizmo=g,position=model.PrimaryPart.Position}end
    end
   end
  end
  return result
 end
 function p.drops(reveal)
  local result={}
  for id,model in pairs(af.groundModels(reveal.position,40))do
   local name,g=af.readLoot(model);local position=objectWorldPosition(model)
   if name and g and position then
    local props=g.properties or {};local source=tostring(props.source or ''):lower()
    local fresh=not reveal.baseline[id]and os.clock()-reveal.at<=15 and(position-reveal.position).Magnitude<=22
    if source=='shippingcrate'or source==''and fresh or reveal.known[id]==g then
     if source~='itemdrop'then reveal.known[id]=g;reveal.names=reveal.names or {};reveal.names[id]=name
      local data=g.gizmoState or {};local collected=g.isCollected==true or data.disabled==true or data.isDestroyed==true or model:GetAttribute('isDestroyed')==true or type(data.collectedPlayers)=='table'and table.find(data.collectedPlayers,player.UserId)~=nil
      local currency=name=='Cash'or name=='CashBundle'
      local allowed=currency and state.globalLoot.collectCash~=false or not currency and filterMatches(name)and state.storeJobs.canKeep(name)
      if allowed and not collected then
       local weight;local objects=liveModule('Objects')
       if not currency and objects and objects.GetDataProperty then local ok,n=pcall(objects.GetDataProperty,name,'weight');if ok then weight=tonumber(n)end end
       result[#result+1]={id=id,model=model,gizmo=g,position=position,name=name,currency=currency,weight=weight}
      end
     end
    end
   end
  end
  for id,g in pairs(reveal.known)do
   local api=liveModule('ClientGizmos')
   if api and type(api.Get)=='function'then
    local ok,current=pcall(api.Get,id)
    if ok and current and current.model and current.model:IsDescendantOf(workspace)then g=current;reveal.known[id]=current end
   end
   local data=g.gizmoState or {};local m=g.model
   local taken=g.isCollected==true or data.disabled==true or data.isDestroyed==true or type(data.collectedPlayers)=='table'and table.find(data.collectedPlayers,player.UserId)~=nil or m and m:GetAttribute('isDestroyed')==true
   local name=reveal.names and reveal.names[id];local currency=name=='Cash'or name=='CashBundle'
   local allowed=currency and state.globalLoot.collectCash~=false or not currency and name and filterMatches(name)and state.storeJobs.canKeep(name)
   if not allowed then reveal.known[id]=nil
   elseif not taken and(not m or not m:IsDescendantOf(workspace))then return nil,'Port loot unstreamed; keeping this crate pending'end
  end
  local r=root();if not r then return nil,'Character unavailable; keeping crate pending'end
  table.sort(result,function(a,b)
   local pa,pb=a.currency and -1 or state.globalLoot.priority(a.name),b.currency and -1 or state.globalLoot.priority(b.name)
   if pa~=pb then return pa<pb end;return(a.position-r.Position).Magnitude<(b.position-r.Position).Magnitude
  end)
  return result
 end
 function p.crate(entry,token)
  local g=entry.gizmo
  if not job.reveal then
   job.reveal={id=entry.id,gizmo=g,model=entry.model,position=entry.position,baseline=g.broken and {}or af.groundModels(entry.position,40),known={},at=os.clock()}
  end
  local reveal=job.reveal
  if reveal.gizmo~=g then return false,'A different crate is still pending'end
  local api=liveModule('ClientGizmos');local read,current=pcall(api.Get,entry.id)
  if not read or current~=g or not entry.model:IsDescendantOf(workspace)then
   local reached,why=state.work.travel(reveal.position+Vector3.new(0,5,0),5);if not reached then return false,why end
   local loaded=state.operations.wait(function()return p.active(token)end,6,function()
    local ok,value=pcall(api.Get,entry.id)
    if ok and value and value.ClassName=='ShippingCrate'and value.model and value.model:IsDescendantOf(workspace)then current=value;return true end
   end)
   if not loaded then return false,'Port crate has not streamed back in'end
   g=current;entry.gizmo=g;entry.model=g.model;reveal.gizmo=g;reveal.model=g.model
  end
  if not(g.broken or g.gizmoState and g.gizmoState.broken)then
   local reached,why=state.work.travel(entry.position+Vector3.new(0,4,0),6);if not reached then return false,why end
   if not p.active(token)then return false,'Canceled'end
   if type(g.Interact)~='function'then return false,'Native crate opening unavailable'end
   local wait=1-(os.clock()-(job.lastCrateAt or -math.huge));if wait>0 then task.wait(wait)end
   if not p.active(token)then return false,'Canceled'end
   job.lastCrateAt=os.clock();reveal.at=os.clock();local lease=state.work.lease;lease.interactionCritical=true
   p.stage('Opening shipping crate')
   local sent,why=state.work.nativeCall(5,g,g.Interact,g)
   local opened=sent and state.operations.wait(function()return p.active(token)end,5,function()return g.broken==true or g.gizmoState and g.gizmoState.broken==true end)
   lease.interactionCritical=false;if not opened then return false,why or 'Crate opening not confirmed'end
   job.didWork=true
  end
  local quiet=0;local deadline=os.clock()+90
  while p.active(token)and os.clock()<deadline do
   local safe,why=state.manual.safeBoundary(state.work.lease);if not safe then return false,why end
   local folder=workspace:FindFirstChild('Local');if not folder or not folder:FindFirstChild('Gizmos')then return false,'Port loot has not loaded'end
   local list,why=p.drops(reveal);if not list then return false,why end
   local item=list[1]
   if not item then
    quiet+=1;if quiet>=6 then job.portDone[entry.id]=g;job.reveal=nil;return true end;task.wait(.2)
   else
    quiet=0;p.stage('Collecting crate loot')
    local picked,why=state.storeJobs.pickup(job,item,token,{active=function()return p.active(token)end})
    if not picked or job.needsSell then return picked,why end
   end
  end
  return false,'Port loot collection interrupted'
 end
 function p.run()
  if not state.storeJobs.ready(job)or state.work.lease then return false end
  job.token+=1;local token=job.token;job.running=true
  local launched=state.work.launch('port',token,function()
   local ok,success,why=xpcall(function()
    if job.portRoute and os.clock()-(job.manifestAt or 0)>300 and(not job.reveal or not(job.reveal.gizmo.broken or job.reveal.gizmo.gizmoState and job.reveal.gizmo.gizmoState.broken))then job.portRoute=nil;job.reveal=nil end
    if not job.portRoute then
     local checked,allowed
     if job.manifest and not job.manifestUsed and os.clock()-(job.manifestAt or 0)<=300 then checked=true;allowed=p.admitted(job.manifest)else checked,allowed=p.manifest(token)end
     if not checked then return false,allowed end
     if not allowed then job.nextAttempt=os.clock()+farmConfig.portCheckMinutes*60;p.stage(job.manifest and 'Shipment excluded by your selection'or 'No confirmed valuable shipment');return true end
     job.portRoute=state.routes.new('port');job.portDone={};job.phase='working'
    end
    while p.active(token)do
     if not p.admitted(job.manifest)then job.portRoute=nil;job.reveal=nil;job.nextAttempt=os.clock()+farmConfig.portCheckMinutes*60;if state.work.farmLock=='port'then state.work.farmLock=nil end;p.stage('Shipment excluded by your selection');return true end
     if job.reveal then
      local reveal=job.reveal
      local done,why=p.crate({id=reveal.id,gizmo=reveal.gizmo,model=reveal.model,position=reveal.position},token)
      if not done or job.needsSell then return done,why end
     else
      local found,entry=state.routes.find(job.portRoute,p.scan,function()return p.active(token)end)
      if not found then return false,entry end
      if not entry then
       if job.didWork then job.cycles+=1 end
       job.didWork=false;job.portRoute=nil;job.manifestUsed=true;job.phase='idle';job.nextAttempt=os.clock()+farmConfig.portCheckMinutes*60
       p.stage('Port route complete');if state.work.farmLock=='port'then state.work.farmLock=nil end
       if bag.read()and bag.value>0 then state.storeJobs.sale(job,false)end
       return true
      end
      local done,why=p.crate(entry,token);if not done or job.needsSell then return done,why end
     end
    end
    return false,'Canceled'
   end,function(e)return tostring(e)end)
   job.running=false
   if not ok or not success then job.nextAttempt=math.max(job.nextAttempt,os.clock()+10);p.stage(tostring(ok and why or success))end
   if state.work.lease and state.work.lease.owner=='port'then state.work.lease.interactionCritical=false end
  end)
  if not launched then job.running=false end;return launched
 end
 local original=state.storeJobs.run
 state.storeJobs.run=function(target)if target and target.id=='port'then return p.run()end;return original(target)end
 if reloadState and reloadState.stores and reloadState.stores.port then
  for key,value in pairs(reloadState.stores.port)do job[key]=value end
  job.running=false;job.token=0;job.nextAttempt=0
 end
end



-- Cargo uses the same movement lease and native tool input as the stationary farms.
state.cargo={}
do
 local c=state.cargo
 local job=state.storeJobs.register('cargo',{label='Cargo Plane',location='cargo card 1',radius=100,mode='cargo'})
 function c.active(token)return state.storeJobs.active(job,token)end
 function c.stage(text)state.storeJobs.stage(job,text)end
 function c.find()
  local props=workspace:FindFirstChild('Props');local folder=props and props:FindFirstChild('CargoJet')
  local api=liveModule('ClientProps')
  if not folder or not api or type(api.GetFromModel)~='function'then return nil end
  for _,model in ipairs(folder:GetChildren())do
   if model:IsA('Model')and model:IsDescendantOf(workspace)then
    local ok,prop=pcall(api.GetFromModel,model)
    if ok and prop and prop.objectId~=nil and prop.model==model then return model,prop end
   end
  end
 end
 function c.cruising(model)
  return model and model:IsDescendantOf(workspace)and model:GetAttribute('isCircling')==true and
   model:GetAttribute('isLanding')==false and model:GetAttribute('isCrashing')==false and model:GetAttribute('isCrashed')==false
 end
 function c.vault(model)
  local health=model and model:GetAttribute('vaultHealth')
  if type(health)~='number'or health~=health or math.abs(health)==math.huge then return 'UNKNOWN'end
  return health<=0 and 'OPEN'or 'CLOSED'
 end
 function c.needsC4()
  local model=c.find()
  return c.cruising(model)and c.vault(model)=='CLOSED'and not(job.cargoCycle and job.cargoCycle.model==model and job.cargoCycle.throwIssued)
 end
 function c.count(name)
  local api=liveModule('ClientData');if not api or type(api.Get)~='function'then return nil end
  local ok,value=pcall(api.Get,'bag');if not ok or type(value)~='table'or type(value.contents)~='table'then return nil end
  local total=0;for _,item in pairs(value.contents)do if item==name then total+=1 end end;return total
 end
 function c.weight(name)
  local api=liveModule('Objects');if not api or type(api.GetDataProperty)~='function'then return nil end
  local ok,value=pcall(api.GetDataProperty,name,'weight')
  if ok and type(value)=='number'and value==value and value>=0 and value<math.huge then return value end
 end
 function c.part(model,path)
  local node=model;for _,name in ipairs(path)do node=node and node:FindFirstChild(name)end
  return node and(node:IsA('BasePart')and node or node:IsA('Model')and node.PrimaryPart)or nil
 end
 function c.scanCards()
  local entries={};local api=liveModule('ClientGizmos');local defs=liveModule('WorldSpawns')
  local folder=workspace:FindFirstChild('Local');folder=folder and folder:FindFirstChild('Gizmos')
  if not api or type(api.Get)~='function'or not folder then return {available=false,targets=entries}end
  for _,model in ipairs(folder:GetDescendants())do
   if model:IsA('Model')and model.PrimaryPart then
   local id=model:GetAttribute('objectId');local ok,g=pcall(api.Get,id)
   local definition=ok and g and g.ClassName=='WorldItemSpawn'and g.properties and defs and defs.WorldItems and defs.WorldItems[g.properties.tag]
   local method
   if definition and definition.toolState and definition.toolState.name=='Cargo Card'and g.used==false and
    g.gizmoState and g.gizmoState.used==false and type(g.Interact)=='function'then
    method=g.Interact
   elseif ok and g and g.ClassName=='WorldItem'and g.properties and g.properties.toolName=='Cargo Card'and
    type(g.CanCollect)=='function'and type(g.AttemptCollect)=='function'then
    local usable,allowed=pcall(g.CanCollect,g);if usable and allowed then method=g.AttemptCollect end
   end
   if method then
    local position=objectWorldPosition(model)
    if position then entries[#entries+1]={id=id,gizmo=g,model=model,position=position,method=method}end
   end
  end
   end
  return {available=true,targets=entries}
 end
 function c.card(token)
  local function usable()
   local id,item=jewelry.getEquipment('Cargo Card');local ammo=item and tonumber(item.ammo or item.toolState and item.toolState.ammo)
   return id~=nil and(ammo==nil or ammo>0)
  end
  if usable()then return true end
  c.stage('Finding Cargo Card')
  local route=state.routes.new('cargoCard')
  local found,entry=state.routes.find(route,c.scanCards,function()return c.active(token)end)
  if not found or not entry then return false,entry or 'Cargo Card not currently available'end
  local reached,why=state.work.travel(entry.position+Vector3.new(0,3,0),5);if not reached then return false,why end
  if not c.active(token)then return false,'Canceled'end
  local sent,why=state.work.nativeCall(5,entry.gizmo,entry.method,entry.gizmo)
  if not sent then return false,why end
  return state.operations.wait(function()return c.active(token)end,8,usable)
 end
 function c.track(model,prop,token)
  local lease=state.work.lease
  local tracker={lease=lease,model=model,prop=prop,token=token,priorLocal=lease.localRouteTravel}
  function tracker.active()
   if tracker.stopped or tracker.error or tracker.ended or state.work.lease~=lease or not c.active(token)or not c.cruising(model)then return false end
   local current,currentProp=c.find();return current==model and currentProp==prop
  end
  tracker.thread=task.spawn(function()
   local thread=coroutine.running();motion.callers[thread]=lease
   local ok,why=xpcall(function()
    while tracker.active()do
     if tracker.focus then
      local point=tracker.focus();local r=root()
      if not point or not r then error('Moving cargo anchor unavailable')end
      local moved,reason=motion.travel(r,point,state.speed,'cargo')
      if not moved then error(reason or 'Cargo movement stopped')end
     end
     RunService.Heartbeat:Wait()
    end
   end,function(err)return tostring(err)end)
   motion.callers[thread]=nil
   if not ok then tracker.error=why end
   tracker.ended=true
  end)
  function tracker.move(focus,tolerance,seconds)
   tracker.focus=focus
   local deadline=motion.activeClock()+(seconds or 120)
   repeat
    if not tracker.active()or tracker.error or tracker.ended then return false,tracker.error or 'Plane no longer available'end
    local point=focus();local r=root()
    if point and r and(r.Position-point).Magnitude<=(tolerance or 3)then
     lease.localRouteTravel=true;lease.cargoAttached=true;return true
    end
    RunService.Heartbeat:Wait()
   until motion.activeClock()>=deadline
   return false,'Could not reach moving cargo anchor'
  end
  function tracker.close()
   tracker.stopped=true
   if tracker.thread then motion.callers[tracker.thread]=nil;pcall(task.cancel,tracker.thread)end
   if state.work.lease==lease then
    lease.localRouteTravel=tracker.priorLocal;lease.cargoAttached=nil;lease.interactionCritical=false
    if root()then motion.hold(root())end
   end
  end
  return tracker
 end
 function c.confirmReceipt(receipt)
  if type(receipt)~='table'then return end
  local outcomes=state.work.nativeOutcomes;local current=outcomes and outcomes[receipt]
  if current~=receipt.ticket then return end
  if state.work.nativeUnknown then state.work.nativeUnknown[receipt]=nil end
  if outcomes then outcomes[receipt]=nil end
 end
 function c.send(tracker,action,receipt,...)
  if not tracker.active()then return false,'Cargo ownership changed'end
  if type(receipt)~='table'or receipt.issued then return false,'Cargo action already issued; awaiting confirmation'end
  local api=liveModule('Network');if not api or type(api.FireServer)~='function'then return false,'Native cargo network unavailable'end
  receipt.issued=true
  local sent,why=state.work.nativeCall(6,receipt,api.FireServer,'propInteraction',tracker.prop.objectId,action,...)
  receipt.ticket=state.work.nativeOutcomes and state.work.nativeOutcomes[receipt]
  receipt.delivered=receipt.ticket and receipt.ticket.started==true or sent==true
  return sent,why
 end
 function c.swipe(tracker,cycle)
  local model=tracker.model
  if model:GetAttribute('forcefieldEnabled')==false then c.confirmReceipt(cycle.swipeReceipt);return true end
  if model:GetAttribute('forcefieldEnabled')~=true then return false,'Forcefield state unavailable'end
  local function point()local part=c.part(model,{'Parts','Fuselage','ForceField','Keycard'});return part and part.Position+part.CFrame.LookVector*3 end
  c.stage('Swiping Cargo Card')
  local reached,why=tracker.move(point,2);if not reached then return false,why end
  if not state.tryEquipTool('Cargo Card',tracker.active)then return false,'Cargo Card equip not confirmed'end
  local tools=itemClient();local tool=tools and tools.GetLocalEquippedTool()
  local part=c.part(model,{'Parts','Fuselage','ForceField','Keycard'});local r=root()
  if not tracker.active()or not r or not part or(r.Position-part.Position).Magnitude>8 then return false,'Outside Cargo Card range'end
  if not tool or tool.name~='Cargo Card'or type(tool.GetId)~='function'then return false,'Equipped Cargo Card unavailable'end
  if cycle.swipeIssued then return false,'Cargo Card swipe pending; waiting for forcefield confirmation'end
  tracker.lease.interactionCritical=true;cycle.swipeIssued=true;cycle.swipeReceipt={}
  local sent,why=c.send(tracker,'swipeKeycard',cycle.swipeReceipt,tool:GetId())
  if not sent and not cycle.swipeReceipt.delivered then cycle.swipeIssued=false end
  local opened=state.operations.wait(tracker.active,10,function()return model:GetAttribute('forcefieldEnabled')==false end)
  tracker.lease.interactionCritical=false
  if opened then c.confirmReceipt(cycle.swipeReceipt)end
  return opened,opened and nil or why or(sent and 'Forcefield change not confirmed'or 'Card swipe not confirmed')
 end
 function c.breach(tracker,cycle)
  local model=tracker.model
  if c.vault(model)=='OPEN'then c.confirmReceipt(cycle.detonateReceipt);return true end
  if model:GetAttribute('forcefieldEnabled')~=false then return false,'Forcefield must be disabled before C4'end
  local door=model:FindFirstChild('Parts');door=door and door:FindFirstChild('PlaneVaultDoor')
  local part=door and door.PrimaryPart
  if not part or c.vault(model)~='CLOSED'then return false,'Cargo vault geometry or state unavailable'end
  -- Choose the closer side of the vault's thin horizontal axis, then retain that side in plane space.
  if not cycle.side then
   local axis=part.Size.X<part.Size.Z and part.CFrame.RightVector or part.CFrame.LookVector
   if(root().Position-part.Position):Dot(axis)<0 then axis=-axis end
   cycle.side=model:GetPivot():VectorToObjectSpace(axis)
  end
  local function direction()return model:GetPivot():VectorToWorldSpace(cycle.side)end
  local function point()return door.Parent and door.PrimaryPart and door.PrimaryPart.Position end
  local function planted()
   local record=bank.planted;local target=point()
   return record and record.door==door and record.model.Parent and record.model.PrimaryPart and target and
    (record.model.PrimaryPart.Position-target).Magnitude<=25 and bank.ownedStickies()[record.model]==true
  end
  if cycle.bomb and cycle.bomb.Parent and cycle.bomb.PrimaryPart and bank.ownedStickies()[cycle.bomb]then bank.planted={door=door,model=cycle.bomb,token=tracker.token}end
  c.stage('Placing one C4 at cargo vault')
  local reached,why=tracker.move(function()local p=point();return p and p+direction()*14 end,3)
  if not reached then return false,why end
  tracker.lease.interactionCritical=true
  if not planted()then
   if cycle.throwIssued then return false,'Cargo C4 already issued; placement unconfirmed, no second explosive spent'end
   local threw,why=bank.throwC4(tracker.token,door,{active=tracker.active,state=function()return c.vault(model)end,
    point=point,frame=function()return model:GetPivot()end,hasPlanted=planted,onObserved=function(bomb)cycle.bomb=bomb end,
    beforeThrow=function()if cycle.throwIssued then error('Cargo C4 already issued')end;cycle.throwIssued=true end})
   if not threw then return false,why end
   if c.vault(model)=='OPEN'then tracker.lease.interactionCritical=false;return true end
  end
  if not planted()then return false,'Owned cargo C4 not confirmed'end
  cycle.bomb=bank.planted.model
  c.stage('Moving clear of cargo C4')
  reached,why=tracker.move(function()local p=point();return p and p+direction()*85 end,3,40)
  if not reached then return false,why end
  if c.vault(model)=='OPEN'then tracker.lease.interactionCritical=false;return true end
  local r=root();local bomb=cycle.bomb
  if not tracker.active()or not planted()or not r or(r.Position-bomb.PrimaryPart.Position).Magnitude<60 then return false,'Current C4 retreat distance not safe'end
  if cycle.detonateIssued then return false,'Cargo detonation pending; no duplicate detonation sent'end
  local api=liveModule('ClientPlayers');local client=api and api.Get and api.Get()
  if not client or type(client.Detonate)~='function'then return false,'Native detonation unavailable'end
  cycle.detonateIssued=true;cycle.detonateReceipt={};c.stage('Detonating cargo C4')
  local sent,why=state.work.nativeCall(6,cycle.detonateReceipt,client.Detonate,client)
  cycle.detonateReceipt.ticket=state.work.nativeOutcomes and state.work.nativeOutcomes[cycle.detonateReceipt]
  local opened=state.operations.wait(tracker.active,12,function()return c.vault(model)=='OPEN'end)
  tracker.lease.interactionCritical=false
  if opened then c.confirmReceipt(cycle.detonateReceipt)end
  return opened,opened and nil or why or(sent and 'Cargo vault opening not confirmed'or 'Detonation not confirmed')
 end
 function c.lootList(model,cycle)
  if model:GetAttribute('forcefieldEnabled')~=false or c.vault(model)~='OPEN'then return nil,'Cargo vault not confirmed open'end
  local entries={}
  for _,folderName in ipairs({'FrontLoot','VaultLoot'})do
   local folder=model:FindFirstChild(folderName);if not folder then return nil,'Cargo loot folder not streamed'end
   for _,loot in ipairs(folder:GetChildren())do
    if loot:IsA('Model')then
     local id=loot:GetAttribute('lootId')
     if id==nil then return nil,'Cargo loot identity unavailable'end
     if not cycle.seen[id]and filterMatches(loot.Name)and state.storeJobs.canKeep(loot.Name)then
      if not loot.PrimaryPart then return nil,'Cargo loot anchor unavailable'end
      entries[#entries+1]={id=id,model=loot,name=loot.Name,action='takeLoot'}
     end
    end
   end
  end
  local holder=model:FindFirstChild('GoldBrickPallet');local pallet=holder and holder:FindFirstChild('GoldBrickPallet')
  if not pallet or pallet:GetAttribute('hasBricks')==nil then return nil,'Cargo gold pallet state unavailable'end
  if pallet:GetAttribute('hasBricks')==true and filterMatches('Gold Brick')then
   if not pallet.PrimaryPart then return nil,'Cargo pallet anchor unavailable'end
   entries[#entries+1]={model=pallet,name='Gold Brick',action='takeBrick'}
  end
  table.sort(entries,function(a,b)return state.globalLoot.priority(a.name)<state.globalLoot.priority(b.name)end)
  return entries
 end
 function c.observeBag()
  if c.bagListening then return true end
  local data=liveModule('ClientData');if not data or type(data.ListenToChange)~='function'then return false end
  local ok,cleanup=pcall(data.ListenToChange,'bag',function(_,_,initial)
   if initial or state.closed then return end
   local pending=job.cargoCycle and job.cargoCycle.pending
   if not pending or not pending.watched or pending.observed then return end
   local count=c.count(pending.name);if not count or count<=pending.before then return end
   local lease=state.work.lease
   if lease and lease.owner~='cargo'then pending.contended=true
   elseif not pending.contended then pending.observed=true end
  end)
  if not ok or type(cleanup)~='function'then return false end
  c.bagListening=true
  if state.connected then
   local connected=true
   table.insert(state.connected,{Disconnect=function()if connected then connected=false;cleanup();c.bagListening=false end end})
  end
  return true
 end
 function c.receipt(cycle)
  local pending=cycle.pending;if not pending then return true end
  if pending.watched then c.observeBag()end
  local count=c.count(pending.name)
  if pending.observed or not pending.watched and count and count>pending.before then
   if pending.id~=nil then cycle.seen[pending.id]=true end
   c.confirmReceipt(pending);job.collected+=1;job.didWork=true;cycle.pending=nil;return true
  end
  return false,'Cargo pickup pending; no duplicate pickup sent'
 end
 function c.collect(tracker,cycle,entry)
  if not c.receipt(cycle)then return false,'Previous cargo pickup has not been confirmed'end
  if not bag.read()then return false,'Bag inventory unavailable'end
  local weight=c.weight(entry.name);if not weight then return false,'Cargo item weight unavailable'end
  if bag.nearFull or bag.freeWeight<weight then return state.storeJobs.sale(job,false)end
  local function point()local part=entry.model.Parent and entry.model.PrimaryPart;return part and part.Position+Vector3.new(0,3,0)end
  c.stage('Collecting '..entry.name)
  local reached,why=tracker.move(point,2,60);if not reached then return false,why end
  local wait=1.05-(os.clock()-(cycle.lastLootAt or -math.huge));if wait>0 then task.wait(wait)end
  local r=root();local part=entry.model.Parent and entry.model.PrimaryPart
  if not tracker.active()or c.vault(tracker.model)~='OPEN'or tracker.model:GetAttribute('forcefieldEnabled')~=false or
   not r or not part or(r.Position-part.Position).Magnitude>(entry.action=='takeBrick'and 14 or 10)then return false,'Cargo loot is outside current native range'end
  local before=c.count(entry.name);if before==nil then return false,'Cargo inventory receipt unavailable'end
  local watched=c.observeBag();if not watched then return false,'Waiting for native bag replication observer'end
  cycle.pending={name=entry.name,id=entry.id,before=before,watched=true};cycle.lastLootAt=os.clock();tracker.lease.interactionCritical=true
  local sent,why
  if entry.action=='takeBrick'then sent,why=c.send(tracker,'takeBrick',cycle.pending)else sent,why=c.send(tracker,'takeLoot',cycle.pending,entry.id)end
  if not sent and not cycle.pending.delivered then cycle.pending=nil;tracker.lease.interactionCritical=false;return false,why end
  local observed=state.operations.wait(tracker.active,8,function()return c.receipt(cycle)end)
  tracker.lease.interactionCritical=false
  return observed,observed and nil or why or(sent and 'Cargo pickup not confirmed'or 'Cargo request not confirmed')
 end
 function c.awaiting(cycle,model)
  if cycle.pending and not c.receipt(cycle)then return 'Waiting for cargo pickup confirmation'end
  if cycle.swipeIssued and model:GetAttribute('forcefieldEnabled')==true then return 'Waiting for Cargo Card swipe confirmation'end
  if c.vault(model)~='OPEN'then
   if cycle.detonateIssued then return 'Waiting for cargo vault opening confirmation'end
   if cycle.throwIssued then
    local bomb=cycle.bomb;local part=c.part(model,{'Parts','PlaneVaultDoor'})
    if not bomb or not bomb.Parent or not bomb.PrimaryPart or not part or
     (bomb.PrimaryPart.Position-part.Position).Magnitude>25 or bank.ownedStickies()[bomb]~=true then return 'Waiting for cargo C4 placement confirmation'end
   end
  end
 end
 local oldReady=state.storeJobs.ready
 state.storeJobs.ready=function(target)
  if not target or target.id~='cargo'then return oldReady(target)end
  if not farmConfig.masterEnabled or not farmConfig.cargoSelected or job.running or state.closed or not characterAlive()or
   player:GetAttribute('currentTeam')=='police'or os.clock()<job.nextAttempt or state.license and not state.license.ownerAllowed('cargo')then return false end
  if job.needsSell then
   if bag.selling or state.sellRequested or not bag.read()then return false end
   if bag.value>0 then if os.clock()-(bag.lastFail or 0)>=60 then state.storeJobs.sale(job,false)end;return false end
   job.needsSell=false
  end
  local model,prop=c.find()
  if not c.cruising(model)then c.stage('Waiting for cargo plane');return false end
  if job.cargoCycle and job.cargoCycle.model==model and job.cargoCycle.id==prop.objectId then
   if job.cargoCycle.complete then return false end
   local waiting=c.awaiting(job.cargoCycle,model);if waiting then c.stage(waiting);return false end
  end
  if c.vault(model)=='UNKNOWN'or type(model:GetAttribute('forcefieldEnabled'))~='boolean'then c.stage('Waiting for cargo state');return false end
  job.anchor=model:GetPivot().Position;return true
 end
 function c.run()
  if not state.storeJobs.ready(job)or state.work.lease then return false end
  job.token+=1;local token=job.token;job.running=true
  local launched=state.work.launch('cargo',token,function()
   local tracker
   local ok,success,why=xpcall(function()
    local model,prop=c.find();if not c.cruising(model)then return false,'Plane no longer available'end
    local cycle=job.cargoCycle
    if not cycle or cycle.model~=model or cycle.id~=prop.objectId then
     cycle={model=model,id=prop.objectId,seen={}};job.cargoCycle=cycle
    end
    if not c.receipt(cycle)then return false,'Previous cargo pickup has not been confirmed'end
    if model:GetAttribute('forcefieldEnabled')==true then local got,reason=c.card(token);if not got then return false,reason end end
    if not c.active(token)or not c.cruising(model)then return false,'Plane changed while obtaining supplies'end
    tracker=c.track(model,prop,token)
    local swiped,reason=c.swipe(tracker,cycle);if not swiped then return false,reason end
    local opened,reason=c.breach(tracker,cycle);if not opened then return false,reason end
    while tracker.active()do
     local boundary,reason=state.manual.safeBoundary(tracker.lease);if not boundary then return false,reason end
     local list,reason=c.lootList(model,cycle);if not list then return false,reason end
     if #list==0 then
      cycle.complete=true;if job.didWork then job.cycles+=1 end;job.didWork=false
      c.stage('Cargo route complete');if state.work.farmLock=='cargo'then state.work.farmLock=nil end
      if bag.read()and bag.value>0 then state.storeJobs.sale(job,false)end
      return true
     end
     local picked,reason=c.collect(tracker,cycle,list[1]);if not picked or job.needsSell then return picked,reason end
    end
    return false,'Cargo route interrupted'
   end,function(err)return tostring(err)end)
   if tracker then tracker.close()end
   job.running=false;job.nextAttempt=os.clock()+10
   if not ok or not success then c.stage(tostring(ok and why or success))end
  end)
  if not launched then job.running=false end;return launched
 end
 local oldRun=state.storeJobs.run
 state.storeJobs.run=function(target)if target and target.id=='cargo'then return c.run()end;return oldRun(target)end
 if reloadState and reloadState.stores and reloadState.stores.cargo then
  for key,value in pairs(reloadState.stores.cargo)do job[key]=value end
  job.running=false;job.token=0;job.nextAttempt=0
 end
end

