 -- Original artwork is packaged with the client; no image host or startup request is needed.
 t.art={entries=setmetatable({},{__mode='k'}),status='idle'}
 function t.art.decode(encoded)
  local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
  local values={};for i=1,#alphabet do values[string.byte(alphabet,i)]=i-1 end
  local output,buffer={},{};local count=0
  for i=1,#encoded,4 do
   local a,b,c,d=string.byte(encoded,i,i+3)
   local x,y=values[a],values[b];if not x or not y then return nil end
   buffer[#buffer+1]=string.char(x*4+math.floor(y/16))
   if c~=61 then local z=values[c];if not z then return nil end;buffer[#buffer+1]=string.char((y%16)*16+math.floor(z/4))
    if d~=61 then local w=values[d];if not w then return nil end;buffer[#buffer+1]=string.char((z%4)*64+w)end
   end
   count+=4
   if count>=65536 then
    output[#output+1]=table.concat(buffer);buffer={};count=0
    if state.closed or state.hubTheme~='Femboy'then return nil end
    task.wait()
   end
  end
  output[#output+1]=table.concat(buffer);return table.concat(output)
 end
 function t.art.ensure()
  if state.license and not state.license.allowed('theme.femboy')then return end
  if t.art.asset or t.art.loading or t.art.status=='unsupported'then return end
  local ok,env=pcall(function()return getgenv()end)
  local import=ok and type(env)=='table'and(env.getcustomasset or env.getsynasset)or nil
  import=import or getcustomasset or getsynasset
  if type(import)~='function'or type(writefile)~='function'or type(state.themeArtPayload)~='function'then t.art.status='unsupported';return end
  t.art.loading=true;t.art.status='loading'
  task.spawn(function()
   local loaded,asset=pcall(function()
    local bytes=t.art.decode(state.themeArtPayload());if not bytes then return nil end
