  end)
 end
 function t.art.layout(view,position,size,touch,headerHeight)
  local out={};local left=position.X-22;local right=view.X-position.X-size.X-22
  local maxWidth=math.min(184,math.min(330,size.Y*.58,view.Y-24)*600/1024)
  local desktop=not touch and size.X>=680
  local pair=desktop and math.min(maxWidth,left,right)or 0
  local function add(name,width,isRight)
   if width<80 then return end
   local height=width*1024/600;local x=isRight and position.X+size.X+10 or position.X-width-10
   if x<12 or x+width>view.X-12 then return end
   out[name]={x=x,y=math.clamp(position.Y+size.Y-height-12,12,math.max(12,view.Y-height-12)),w=width,h=height}
  end
  if pair>=80 then add('left',pair,false);add('right',pair,true)
  elseif desktop then add('left',math.min(maxWidth,left),false);add('right',math.min(maxWidth,right),true)end
  if not out.left and not out.right then
   local scale=math.max(.1,(headerHeight or 59)/59);local x=196*scale
   local controlsStart=size.X-(size.X<480 and 178 or size.X<680 and 220 or 356)*scale
   local width=math.min(34*scale,controlsStart-x-12*scale,(headerHeight or 59)-16*scale)
   if width>=24*scale then out.compact={x=x/scale,y=8,w=width/scale,h=width/scale}end
  end
  return out
 end
 function t.art.attach(window,hub,header)
  if t.art.entries[window]then return t.art.entries[window]end
  local layer=Instance.new('Frame');layer.Name='FemboyArtwork';layer.BackgroundTransparency=1
  layer.BorderSizePixel=0;layer.Active=false;layer.Size=UDim2.fromScale(1,1);layer.ZIndex=0;layer.Parent=window.Parent
  local function portrait(parent,name,offset,size)
   local clip=Instance.new('Frame');clip.Name=name;clip.BackgroundTransparency=1;clip.BorderSizePixel=0
   clip.Active=false;clip.ClipsDescendants=true;clip.ZIndex=0;clip.Parent=parent
   local image=Instance.new('ImageLabel');image.Name='Portrait';image.BackgroundTransparency=1;image.BorderSizePixel=0
   image.Active=false;image.Selectable=false;image.ImageRectOffset=Vector2.new(0,0);image.ImageRectSize=Vector2.new(0,0)
   image.ScaleType=Enum.ScaleType.Stretch;image.ZIndex=clip.ZIndex
   image.Size=UDim2.fromScale(1536/size.X,1024/size.Y);image.Position=UDim2.fromScale(-offset.X/size.X,-offset.Y/size.Y);image.Parent=clip
   return clip
  end
  local left=portrait(layer,'LilacPortrait',Vector2.new(0,0),Vector2.new(600,1024))
  local right=portrait(layer,'RosePortrait',Vector2.new(936,0),Vector2.new(600,1024))
  local compact=portrait(header,'FemboyHeaderPortrait',Vector2.new(1100,0),Vector2.new(360,360));compact.ZIndex=header.ZIndex
  local entry={layer=layer,left=left,right=right,compact=compact,connections={}};t.art.entries[window]=entry
  function entry.update()
   if not window.Parent then return end
   local active=state.hubTheme=='Femboy'and(not state.license or state.license.allowed('theme.femboy'))and window.Visible~=false and (window.GroupTransparency or 0)<.99
   local asset=t.art.asset
   layer.Visible=false;left.Visible=false;right.Visible=false;compact.Visible=false
   if not active then return end
   if not asset then t.art.ensure();return end
   local view=workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1000,700)
   local layout=t.art.layout(view,window.AbsolutePosition,window.AbsoluteSize,UserInputService.TouchEnabled,header.AbsoluteSize.Y)
   for name,rect in pairs(layout)do
    local image=entry[name];local portrait=image:FindFirstChild('Portrait');portrait.Image=asset;image.Position=UDim2.fromOffset(rect.x,rect.y);image.Size=UDim2.fromOffset(rect.w,rect.h)
    portrait.ImageTransparency=name=='compact'and 0 or math.clamp(window.GroupTransparency or 0,0,1);portrait.ZIndex=image.ZIndex;image.Visible=true
   end
   layer.Visible=left.Visible or right.Visible
  end
  for _,property in ipairs({'AbsolutePosition','AbsoluteSize','Visible','GroupTransparency'})do
   entry.connections[#entry.connections+1]=window:GetPropertyChangedSignal(property):Connect(entry.update)
  end
  local camera=workspace.CurrentCamera
  if camera then entry.cameraConnection=camera:GetPropertyChangedSignal('ViewportSize'):Connect(entry.update)end
  entry.connections[#entry.connections+1]=workspace:GetPropertyChangedSignal('CurrentCamera'):Connect(function()
   if entry.cameraConnection then entry.cameraConnection:Disconnect()end
   local current=workspace.CurrentCamera
   if current then entry.cameraConnection=current:GetPropertyChangedSignal('ViewportSize'):Connect(entry.update)end
   entry.update()
  end)
  entry.connections[#entry.connections+1]=window.Destroying:Connect(function()
   for _,connection in ipairs(entry.connections)do connection:Disconnect()end
   if entry.cameraConnection then entry.cameraConnection:Disconnect()end
   layer:Destroy();t.art.entries[window]=nil
  end)
  entry.update();return entry
 end

