 function t.detail(surface)
  local grain=surface:FindFirstChild('ThemeTexture')
  if not grain then
   grain=Instance.new('Frame');grain.Name='ThemeTexture';grain.BackgroundTransparency=1;grain.BorderSizePixel=0
   grain.Size=UDim2.fromScale(1,1);grain.ClipsDescendants=true;grain.Active=false;grain.Parent=surface
   for index=0,9 do
    local line=Instance.new('Frame');line.Name='Filament';line.BackgroundTransparency=.94;line.BorderSizePixel=0
    line.Size=UDim2.new(0,1,2,0);line.Position=UDim2.new(index/8-.12,0,-.5,0);line.Rotation=25;line.Active=false;line.Parent=grain
   end
  end
  grain.Visible=state.hubTheme~='Carbon'and state.hubTheme~='Obsidian';grain.ZIndex=surface.ZIndex
  local grid=surface:FindFirstChild('ObsidianGrid')
  if not grid and state.hubTheme=='Obsidian'then
   grid=Instance.new('Frame');grid.Name='ObsidianGrid';grid.Size=UDim2.fromScale(1,1);grid.BackgroundTransparency=1;grid.BorderSizePixel=0;grid.Active=false;grid.ClipsDescendants=true;grid.Parent=surface
   for i=1,12 do
    for _,vertical in ipairs({true,false})do
     local line=Instance.new('Frame');line.Name='GridLine';line.BorderSizePixel=0;line.Active=false;line.BackgroundTransparency=.94
     line.Position=vertical and UDim2.fromScale(i/13,0)or UDim2.fromScale(0,i/13)
     line.Size=vertical and UDim2.new(0,1,1,0)or UDim2.new(1,0,0,1);line.Parent=grid
    end
   end
   for i=1,4 do
    local trace=Instance.new('Frame');trace.Name='CircuitTrace';trace.BorderSizePixel=0;trace.Active=false;trace.BackgroundTransparency=.88
    trace.Position=UDim2.fromScale(.68+i*.025,.72+i*.045);trace.Size=UDim2.new(.12,0,0,1);trace.Parent=grid
   end
  end
  if grid then grid.Visible=state.hubTheme=='Obsidian';grid.ZIndex=surface.ZIndex
   for _,child in ipairs(grid:GetChildren())do child.ZIndex=surface.ZIndex;child.BackgroundColor3=child.Name=='CircuitTrace'and C.red or C.line end
  end
  for _,child in ipairs(grain:GetChildren())do child.ZIndex=surface.ZIndex;child.BackgroundColor3=C.line end
 end
 function t.decorate(surface)
  t.surfaces[surface]=true
  local weave=surface:FindFirstChild('CarbonWeave')
  if not weave and state.hubTheme=='Carbon'then
