  refresh();return refresh,openAt,menu
end
local uiAmmoAt,uiAmmoCache=0,{}
function state.utilitySummary(names,width,height,measure)
 if #names==0 then return 'No utilities owned',18 end
 measure=measure or function(text)
  local ok,size=pcall(function()return game:GetService('TextService'):GetTextSize(text,11,Enum.Font.GothamMedium,Vector2.new(width,2000))end)
  return ok and size.Y or math.ceil(#text/math.max(8,math.floor(width/6)))*15
 end
 for count=#names,0,-1 do
  local shown={};for i=1,count do shown[#shown+1]=names[i]end
  local text=table.concat(shown,' · ')
  if count<#names then text=text..(count>0 and ' · 'or '')..'+'..(#names-count)..' more'end
  local used=measure(text);if used<=height then return text,used end
 end
 return '+'..#names..' more',18
end
