function state.combatRemaining()
 local time=liveModule('TimeUtil');local globals=liveModule('Globals')
 local cooldown=globals and tonumber(globals.COMBAT_COOLDOWN)
 if not time or type(time.GetServerTime)~='function'or not cooldown then return nil end
 local ok,now=pcall(time.GetServerTime);if not ok or type(now)~='number'then return nil end
 local damaged=tonumber(player:GetAttribute('lastDamaged'))or -math.huge
 local hostile=tonumber(player:GetAttribute('lastHostileAction'))or -math.huge
 return math.clamp(math.ceil(cooldown-(now-math.max(damaged,hostile))),0,cooldown)
end
state.activityTravel={traveling='Traveling',descending='Descending',cruising='Traveling',clearing_ceiling='Leaving interior',ascending='Ascending',cancelling='Canceling'}
function state.activityView(lease)
 lease=lease or state.work.lease
 if not lease then
  if jewelry.passiveBuying then return 'Jewelry Supplies',jewelry.supplyStatus or 'Checking supplies'end
  if state.ammo.passiveRunning then return 'Ammo Refill',state.ammo.status end
  return 'Idle','No active task'
 end
 local owner=lease.owner
 if owner=='bank' then return bank.isTutorial and 'Bank Tutorial' or 'Bank Farm',bank.isTutorial and bank.autoStatus or bankFarm.status end
 if owner=='quest' then return 'Ghost Quest',state.quest.display().status end
 if owner=='jewelry' then return jewelry.supplyOnly and 'Jewelry Supplies' or 'Jewelry Farm',jewelry.routeStatus end
 if owner=='airdrop' then return 'Airdrop Farm',af.status end
 if owner=='seller' then return 'Selling',bag.status end
 if owner=='ammo' then return 'Ammo Refill',state.ammo.status end
 if owner=='shop' then return 'Gun Shop',state.shopState.status end
 if owner=='market'then return 'Supply Market',state.market.status end
 if owner=='combatShop' then return 'Weapon Purchase',combat.spasStatus or 'Purchasing weapon' end
 if owner=='freeGun' then return 'Free Weapon',state.freeGuns.status end
 if owner=='team' then return 'Team Change',state.teams.status end
 if owner=='misc'then return 'Miscellaneous',state.misc.status end
 if owner=='manual' then return 'Manual Fly',state.manual.status end
 if state.storeJobs and state.storeJobs.jobs[owner]then local job=state.storeJobs.jobs[owner];return job.label,job.status end
 if owner=='military'then return 'Military',militaryScan.routeStatus end
 if owner=='pear'then return 'Pear Store',pearStore.routeStatus end
 if owner=='pearRecon' then return 'Pear Store',pearStore.routeStatus end
 if owner=='evidenceRecon' then return 'Evidence Room',evidenceRoom.routeStatus end
 if owner=='militaryRecon' then return 'Military Crate',militaryScan.routeStatus end
 return 'Task',state.navigationStatus or 'Running'
end
function state.activityGeometry(stageHeight,hasNext,hasTimer,hasControls)
 local layout={stageY=25};local y=25+math.clamp(stageHeight,18,64)+4
 layout.nextY=y;if hasNext then y=y+24 end
 layout.timerY=y;if hasTimer then y=y+24 end
 layout.buttonsY=y+2;if hasControls then y=y+32 end
 layout.height=52+y
