 function v.buildUI(page,sync)
  local host=controlGroup(page,'CombatWorkspace');host.Name='CombatWorkspace'
  local summary=hint(host,'');summary.TextWrapped=true
  local nav=mk('Frame',host,{Name='CombatSections',Size=UDim2.new(1,0,0,170),BackgroundTransparency=1});order(nav)
  local grid=mk('UIGridLayout',nav,{CellSize=UDim2.new(1/3,-7,0,38),CellPadding=UDim2.fromOffset(7,6),SortOrder=Enum.SortOrder.LayoutOrder})
  local content=mk('Frame',host,{Name='CombatContent',Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1});order(content);stack(content,8)
  local panels={};local buttons={}
  local aliases={Hitboxes='HBE',Projectiles='Gun Modifiers',Tracers='Gun Modifiers',Experiments='Gun Modifiers',Keybinds='Advanced',['Gun Shop & Ammo']='Weapon Management'}
  local selected=aliases[v.selectedSection] or v.selectedSection or 'Silent Aim'
  local names={'Silent Aim','ESP','HBE','Gun Modifiers','Whitelist','Loopbring','Weapon Management','Filters','Advanced','Configurations'}
  local function choose(name)
   closeMenu();if v.picker then v.picker:Destroy();v.picker=nil end
   selected=name;v.selectedSection=name
   for n,p in pairs(panels)do p.Visible=n==name;accent(buttons[n],n==name)end
  end
  for i,name in ipairs(names)do
   local p=mk('Frame',content,{Name=name,Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundColor3=C.card,BackgroundTransparency=0,Visible=false});pad(p,10,12,10,12);stack(p,7);rounded(p,8);stroke(p);panels[name]=p
   local label=name=='Configurations'and 'Presets'or name=='Weapon Management'and 'Equipment'or name
   local b=btn(nav,label,function()choose(name)end,100,38);b.LayoutOrder=i;buttons[name]=b
   local feature=({HBE='combat.hbe',Loopbring='combat.loopbring',['Gun Modifiers']='combat.gun_modifiers'})[name]
   if feature and state.license then
    state.license.tag(p,feature)
    if not state.license.unreleased[feature]then state.license.tag(b,feature)end
   end
   if name=='HBE'or name=='Loopbring'then
    state.themes.testingLabel(b,label)
   end
  end
  local function group(parent,title,opened)
   local clean=title:gsub(' · TESTING','')
   local body,outer=foldedCard(parent,clean)
   if title:find(' · TESTING',1,true)then
    local header=outer:FindFirstChild('SectionHeader')
    local caption=header:FindFirstChildOfClass('TextLabel');if caption then state.themes.testingLabel(caption,clean)end
   end
   return body
  end
  -- Main Combat modes use full switches; all their subordinate yes/no
