 end
 function m.guns()
  local list={};local items=m.read('gameItems')
  for id,item in pairs(items and items.Tool or {})do
   local def=type(item)=='table'and m.definition(item.name)
   if def and def.itemType=='Gun'then list[#list+1]={id=id,name=item.name}end
  end
  table.sort(list,function(a,b)return a.name==b.name and tostring(a.id)<tostring(b.id)or a.name<b.name end);return list
 end
 function m.catalog()
  local list={};local shops=liveModule('GameShops');if type(shops)~='table'then return list end
  for shop,categories in pairs(shops)do if type(shop)=='string'and type(categories)=='table'then
   local function add(category,items)
    if type(items)~='table'then return end
    local meta={};if type(shops.GetCategoryData)=='function'then local ok,value=pcall(shops.GetCategoryData,shop,category);if ok and type(value)=='table'then meta=value end end
    for name,offer in pairs(items)do if type(name)=='string'and type(offer)=='table'and offer.cost~=nil then
     local def=m.definition(name);local attachment=shop=='Attachments'or meta.itemType=='Attachment'
     local tool=meta.itemType=='Tool'or meta.isTool or def and(def.itemType=='Gun'or def.itemType=='AmmoTool'or def.itemType=='Throwable'or def.itemType=='Tool')
     if attachment or tool then list[#list+1]={key=shop..'/'..category..'/'..name,shop=shop,category=category,name=name,offer=offer,meta=meta,attachment=attachment,
      tab=attachment and 'Attachments'or def and def.itemType=='Gun'and 'Weapons'or 'Tools',packet={shopName=shop,categoryName=category,itemName=name,itemType=attachment and 'Attachment'or 'Tool'}}end
    end end
   end
   if categories.data then add(shop,categories.data)else
    local flat=false;for _,offer in pairs(categories)do if type(offer)=='table'and offer.cost~=nil then flat=true;break end end
    if flat then add(shop,categories)else for category,items in pairs(categories)do if type(category)=='string'then add(category,items)end end end
   end
  end end
  local seen={};for _,entry in ipairs(list)do seen[entry.key]=true end
  local lists=liveModule('AttachmentLists')
  for _,names in pairs(type(lists)=='table'and lists or {})do if type(names)=='table'then for _,name in ipairs(names)do
   local def=m.definition(name);local category=def and def.slot;local key=category and('Attachments/'..category..'/'..name)
   if key and not seen[key]and def.cost~=nil and not def.disabled then
    seen[key]=true;list[#list+1]={key=key,shop='Attachments',category=category,name=name,offer=def,meta={itemType='Attachment'},attachment=true,tab='Attachments',packet={shopName='Attachments',categoryName=category,itemName=name,itemType='Attachment'}}
   end
  end end end
  table.sort(list,function(a,b)return a.name==b.name and a.key<b.key or a.name<b.name end);return list
 end
 function m.weaponChoices()
  local guns=m.guns();local totals,seen={},{};local result={}
  for _,gun in ipairs(guns)do totals[gun.name]=(totals[gun.name]or 0)+1 end
  for _,gun in ipairs(guns)do
   seen[gun.name]=(seen[gun.name]or 0)+1
   result[#result+1]={gun=gun,label=gun.name..(totals[gun.name]>1 and(' · '..seen[gun.name]..'/'..totals[gun.name])or '')}
  end
