  return 'Choose owned weapon'
 end
 function m.inspect(entry,gun)
  local util=liveModule('GameShopUtil');local offer=entry.offer;local id=jewelry.getEquipment(entry.name)
  local result={owned=id~=nil,id=id,contract=false,equipped=false,locked=offer.isLocked==true or entry.meta.isLocked==true,price=tonumber(offer.cost),currency=offer.currencyName or entry.meta.currencyName or 'cash'}
  if util and type(util.DoesOwnContract)=='function'then local ok,value=pcall(util.DoesOwnContract,player,entry.name);result.contract=ok and value==true end
  local inventory=m.read('gameItems')
  for _,owned in pairs(inventory and inventory.Contract or {})do if type(owned)=='table'and owned.name==entry.name then result.contract=true;break end end
  result.needsContract=(entry.meta.hasContract==true or offer.contractCost~=nil)and not result.contract and not result.owned
  if entry.attachment then
   result.owned=false;result.id=nil
   if not gun then result.locked=true;result.reason='Choose an owned weapon';return result end
   local valid=false;for _,owned in ipairs(m.guns())do if owned.id==gun.id and owned.name==gun.name then valid=true;break end end
   if not valid then result.locked=true;result.reason='Weapon is no longer owned';return result end
   local def=m.definition(gun.name);local slots=def and def.attachmentCompatability
   local lists=liveModule('AttachmentLists');local group=slots and slots[entry.category]
   local slot=lists and group and lists[group]
   result.compatible=type(slot)=='table'and table.find(slot,entry.name)~=nil
   if not result.compatible then result.locked=true;result.reason='Not available for this weapon';return result end
   local shops=m.read('gameShops');local saved=shops and shops[gun.id];local category=saved and saved[entry.category]
   result.owned=type(category)=='table'and category[entry.name]~=nil and category[entry.name]~=false or false
   local items=m.read('gameItems')
   for itemId,item in pairs(items and items.Attachment or {})do if type(item)=='table'and item.name==entry.name then result.owned=true;result.id=itemId;break end end
   local tool=items and items.Tool and items.Tool[gun.id]
   result.equipped=tool and type(tool.attachments)=='table'and tool.attachments[entry.category]==entry.name or false
   result.owned=result.owned or result.equipped
   if util and type(util.GetCost)=='function'then local ok,price=pcall(util.GetCost,offer,gun.name);if ok then result.price=tonumber(price)end end
  end
  local npc=offer.careerNPC or entry.meta.careerNPC
  if npc and not result.owned and not result.contract then
   if not util or type(util.GetCareerState)~='function'then result.locked=true;result.reason='Career status unavailable'
   else local ok,career=pcall(util.GetCareerState,player,npc,(entry.meta.hasContract or offer.contractCost)and 'Contract'or entry.packet.itemType,entry.name)
    if not ok or type(career)~='table'then result.locked=true;result.reason='Career status unavailable'
    elseif career.isLocked then result.locked=true;result.reason=career.lockedFlagText or 'Career requirement not met'end
   end
  end
  if offer.disabled or entry.meta.disabled then result.locked=true;result.reason='Currently unavailable'end
  if result.currency~='cash'then result.locked=true;result.reason='Uses '..tostring(result.currency)..' · use the game shop'end
  if not result.price or result.price<0 or result.price~=result.price or result.price==math.huge then result.locked=true;result.reason=result.reason or 'Price unavailable'end
  if result.locked and not result.reason then result.reason='Currently unavailable'end
  return result
 end
 function m.destination(entry)
