 function m.purchase(entry,contract,gun,operation)
  if state.license and not state.license.allowed('shop.custom_market')then return false,'Access unavailable'end
  if m.busy and not(state.work.lease and state.work.lease.owner=='market')then
   local pending=state.work.pending and state.work.pending.name==m.requestName
   for _,job in ipairs(state.work.actionQueue or {})do pending=pending or job.name==m.requestName end
   if not pending then m.busy=false end
  end
  if m.busy then return false,'Another shop action is queued'end
  local action=operation or(contract and 'contract'or 'buy')
  if not({buy=true,contract=true,equip=true,unequip=true})[action]then return false,'Unknown shop action'end
  local function latest()
   for _,current in ipairs(m.catalog())do if current.key==entry.key then return current end end
  end
  entry=latest();if not entry then m.status='Offer is no longer listed';return false,m.status end
  local function allowed(current,row)
   if row.locked then return false,row.reason end
   if action=='contract'then
    local price=tonumber(current.offer.contractCost)
    if row.contract or not price or price<0 or price~=price or price==math.huge then return false,'Contract unavailable or already unlocked'end
   elseif action=='buy'then
    if row.owned then return false,'Already owned'end
    if row.needsContract then return false,'Unlock the contract first'end
   elseif not current.attachment or not row.owned then return false,'Attachment is not owned'
   elseif (action=='equip')==row.equipped then return false,action=='equip'and 'Already equipped'or 'Already unequipped'end
