  local queued,why=state.work.request(m.requestName,function()
   m.token=(m.token or 0)+1;local token=m.token
   local launched=state.work.launch('market',token,function()
    local function snapshot()
     local row=m.inspect(entry,gun)
     if action=='contract'then return row.contract end
     if action=='equip'then return row.equipped end
     if action=='unequip'then return row.compatible==true and not row.equipped end
     return row.owned
    end
