     active=function()return not state.closed and state.work.owns('market',token)end,
     complete=snapshot,snapshot=snapshot,changed=function(before)return snapshot()~=before end,progress=function(before)return not before and snapshot()end,
     status=function(value)m.status=value;if m.renderDetail then m.renderDetail()end end,
     destination=function()return m.destination(entry)end,
     onApproach=function()
      if entry.name=='Buzzsaw'or entry.name=='Vault Cracker'then return jewelry.openSupplyShop(entry.name,nil,{active=function()return state.work.owns('market',token)end})end
      return true
     end,
     finish=function()jewelry.closeSupplyShop(state.work.lease)end,
     prepare=function()
      local current=latest();if not current then return nil,nil,nil,'Offer is no longer listed'end
      entry=current;local row=m.inspect(current,gun);local ready,why=allowed(current,row)
      if not ready then return nil,nil,nil,why end
      local packet=table.clone(current.packet)
      if action=='contract'then packet.itemType='Contract';return 'purchaseContract',table.pack('Contract',packet),tonumber(current.offer.contractCost)end
      if current.attachment then
       packet.saveKey=gun.id;packet.parentItemId=gun.id;packet.itemId=row.id
       if action=='equip'or action=='unequip'then return action=='equip'and 'equipShopItem'or 'unequipShopItem',table.pack('Attachment',packet),0 end
       return 'purchaseShopItem',table.pack('Attachment',packet,true),row.price
      end
