      return 'purchaseTool',table.pack(packet),row.price
     end})
    if ok and(action=='buy'or action=='contract')and m.refreshNative then m.refreshNative(entry,gun,action=='contract')end
    m.status=ok and('Confirmed · '..entry.name)or tostring(why);m.busy=false
