  refresh=function()
   if not list.Parent then return end
   if m.gun then local found=false;for _,gun in ipairs(m.guns())do if gun.id==m.gun.id and gun.name==m.gun.name then found=true;break end end;if not found then m.gun=nil;m.selected=nil end end
   clear(list,'marketList');local oldScope=ui.scope;ui.scope='marketList';list:SetAttribute('RedlineOrder',0)
   for tab,b in pairs(tabs)do b.BackgroundColor3=tab==m.tab and colors.selected or colors.panel;b.TextColor3=tab==m.tab and colors.accent or colors.ink end
   weapon.Text=m.weaponLabel(m.gun);weapon.Visible=m.tab=='Attachments'
   store.Position=m.tab=='Attachments'and UDim2.new(.57,4,0,0)or UDim2.new();store.Size=m.tab=='Attachments'and UDim2.new(.43,-4,1,0)or UDim2.new(1,0,1,0);store.Text=m.store or 'All stores'
   local count=0;local search=m.query:lower()
   for _,entry in ipairs(entries)do if entry.tab==m.tab and(not m.store or m.store=='All stores'or entry.shop==m.store)and(search==''or(entry.name..' '..(entry.offer.displayName or '')..' '..entry.shop..' '..entry.category):lower():find(search,1,true))then
    local row=m.inspect(entry,m.gun)
    if not entry.attachment or row.compatible then
     count+=1
     local status=row.reason or(row.equipped and 'Equipped'or row.owned and 'Owned'or row.needsContract and 'Contract required'or money(row.price))
      local selected=m.selected and m.selected.key==entry.key
      local b=order(button(list,'',UDim2.new(),UDim2.new(1,-2,0,66),function()m.selected=entry;refresh()end))
      b.BackgroundColor3=selected and colors.selected or C.raised
      local edge=b:FindFirstChildOfClass('UIStroke');if edge then edge.Color=selected and colors.accent or colors.edge end
      local name=label(b,entry.offer.displayName or entry.name,12,7,100,22,12,selected and colors.accent or colors.ink)
      name.Size=UDim2.new(1,-24,0,22);name.TextWrapped=false;name.TextTruncate=Enum.TextTruncate.AtEnd
      local location=label(b,entry.shop,12,32,100,24,10,colors.muted);location.Size=UDim2.new(.48,-12,0,24);location.TextWrapped=false;location.TextTruncate=Enum.TextTruncate.AtEnd
      local badge=label(b,status,0,32,100,24,10,selected and colors.accent or colors.muted)
      badge.Position=UDim2.new(.48,0,0,32);badge.Size=UDim2.new(.52,-12,0,24);badge.TextXAlignment=Enum.TextXAlignment.Right;badge.TextWrapped=false;badge.TextTruncate=Enum.TextTruncate.AtEnd
    end
   end end
   if count==0 then local text=order(label(list,m.tab=='Attachments'and not m.gun and 'Choose an owned weapon above'or 'No matching items',0,0,240,52,12,colors.muted));text.Size=UDim2.new(1,0,0,52)end
   ui.scope=oldScope;details()
  end
   m.renderDetail=details;m.refresh=refresh
   m.paint=function()
    if not shell.Parent then return end
    -- Static controls carry palette semantics; selected rows are rebuilt below.
    for _,object in ipairs(shell:GetDescendants())do
     for _,property in ipairs({'BackgroundColor3','TextColor3','Color','ScrollBarImageColor3'})do
      local semantic=object:GetAttribute('Theme_'..property)
      if semantic and C[semantic]then pcall(function()object[property]=C[semantic]end)end
     end
    end
    shell.BackgroundColor3=colors.base;wash.Color=ColorSequence.new(C.nav,C.base)
    rail.BackgroundColor3=colors.accent;query.PlaceholderColor3=colors.muted
    refresh()
   end
  for i,tab in ipairs({'Weapons','Tools','Attachments'})do tabs[tab]=button(shell,tab,UDim2.new((i-1)/3,18-(i-1)*6,0,92),UDim2.new(1/3,-20,0,26),function()closeMenu();m.tab=tab;m.store='All stores';m.selected=nil;refresh()end)end
  m.menus={}
  local _,_,weaponMenu=dropdown(weapon,function()local names={};for _,choice in ipairs(m.weaponChoices())do names[#names+1]=choice.label end;return names end,function()return weapon.Text end,function(name)
   for _,choice in ipairs(m.weaponChoices())do if name==choice.label then m.gun=choice.gun;m.selected=nil;refresh();break end end
  end,false,'Owned weapon')
  m.menus[#m.menus+1]=weaponMenu
  local _,_,storeMenu=dropdown(store,function()
   local names={'All stores'};local seen={};for _,entry in ipairs(entries)do if entry.tab==m.tab and not seen[entry.shop]then seen[entry.shop]=true;names[#names+1]=entry.shop end end;table.sort(names);return names
  end,function()return m.store or 'All stores'end,function(name)m.store=name;m.selected=nil;refresh()end,false,'Stores')
  m.menus[#m.menus+1]=storeMenu
  local function reflow()
   if not shell.Parent then return end
   local view=workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(900,700)
   width,height=math.max(240,math.min(820,view.X-24)),math.max(180,math.min(590,view.Y-24));narrow=width<600
   shell.Size=UDim2.fromOffset(width,height);title.Size=UDim2.fromOffset(width-120,30);title.TextSize=width<400 and 12 or 16
   local position=m.position or Vector2.new((view.X-width)*.5,(view.Y-height)*.5)
   m.position=Vector2.new(math.clamp(position.X,8,math.max(8,view.X-width-8)),math.clamp(position.Y,8,math.max(8,view.Y-height-8)))
   shell.Position=UDim2.fromOffset(m.position.X,m.position.Y)
   local available=math.max(40,height-184);local listHeight=narrow and math.floor(available*.36)or available
   list.Position=UDim2.fromOffset(18,166);list.Size=narrow and UDim2.new(1,-36,0,listHeight)or UDim2.new(.46,-24,0,listHeight)
   detail.Position=narrow and UDim2.fromOffset(18,176+listHeight)or UDim2.new(.46,6,0,166)
   detail.Size=narrow and UDim2.new(1,-36,0,math.max(30,available-listHeight-10))or UDim2.new(.54,-24,0,available)
   details()
  end
  m.reflow=reflow
  local pressed,start,origin
  connect(drag.InputBegan:Connect(function(event)
   if pressed or(event.UserInputType~=Enum.UserInputType.MouseButton1 and event.UserInputType~=Enum.UserInputType.Touch)then return end
   closeMenu();pressed=event;start=event.Position;origin=m.position
  end))
  connect(UserInputService.InputChanged:Connect(function(event)
   if not pressed or(event~=pressed and not(pressed.UserInputType==Enum.UserInputType.MouseButton1 and event.UserInputType==Enum.UserInputType.MouseMovement))then return end
   local delta=event.Position-start;m.position=Vector2.new(origin.X+delta.X,origin.Y+delta.Y);reflow()
  end))
  connect(UserInputService.InputEnded:Connect(function(event)if event==pressed then pressed=nil end end))
  connect(query:GetPropertyChangedSignal('Text'):Connect(function()m.query=query.Text;refresh()end))
  local nextRead=0;local lastView;local stamp=''
  connect(RunService.Heartbeat:Connect(function()
   if not shell.Parent or os.clock()<nextRead then return end;nextRead=os.clock()+.5
   local view=workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
   if view and(not lastView or view.X~=lastView.X or view.Y~=lastView.Y)then lastView=view;closeMenu();reflow()end
   local parts={tostring(m.busy),m.status,tostring(m.read('cash'))}
   for _,gun in ipairs(m.guns())do parts[#parts+1]=tostring(gun.id)..':'..gun.name end
   for _,entry in ipairs(entries)do local row=m.inspect(entry,m.gun);parts[#parts+1]=entry.key..':'..tostring(row.owned)..':'..tostring(row.equipped)..':'..tostring(row.contract)..':'..tostring(row.locked)..':'..tostring(row.price)end
   local nextStamp=table.concat(parts,'|')
   if nextStamp~=stamp and not ui.menu and not pressed then stamp=nextStamp;refresh()end
  end))
  reflow();refresh();ui.scope=prior
 end
end

