-- does not acquire movement leases, start tasks, or infer unavailable game data.
function state.keybindRows()
 local rows={}
 local function add(label,key,enabled)if enabled~=false and type(key)=='string'and key~=''then rows[#rows+1]={label=label,key=key}end end
 add('Fly',state.keybinds.fly,state.keybinds.flyEnabled);add('Noclip',state.keybinds.noclip,state.keybinds.noclipEnabled)
 add('Minimize / restore',state.keybinds.minimize,state.keybinds.minimize~='')
 local labels={['aim.enabled']='Silent Aim',['esp.enabled']='ESP',['hbe.enabled']='HBE'}
 local v=state.combat and state.combat.v30
 for id,key in pairs(v and v.settings.bindings or {})do add(labels[id]or id,key)end
 table.sort(rows,function(a,b)if a.key~=b.key then return a.key<b.key end;return a.label<b.label end)
 return rows
end
function state.launcherOptions()
 local w=state.windowSettings
 local function clean(value,fallback,limit)
  if type(value)~='string'then return fallback end
  value=value:gsub('%c',' '):gsub('^%s+',''):gsub('%s+$','')
  local valid,count=pcall(utf8.len,value);if not valid or not count then return fallback end
  if count>limit then value=value:sub(1,utf8.offset(value,limit+1)-1)end
  return value~=''and value or fallback
 end
 return {title='REDLINE',detail='Open workspace',
  style=(w.launcherStyle=='Compact'or w.launcherStyle=='Emblem')and w.launcherStyle or 'Standard',
  scale=math.clamp(tonumber(w.launcherScale)or 1,.75,1.25)}
end
