  local screen=mk('ScreenGui',player:WaitForChild('PlayerGui'),{Name='REDLINEv30UI',ResetOnSpawn=false,IgnoreGuiInset=true,ZIndexBehavior=Enum.ZIndexBehavior.Sibling,DisplayOrder=80})
  state.gui=screen
  if state.commands then task.defer(function()state.commands.decorate(screen)end)end
  connect(UserInputService.InputBegan:Connect(function(event)if event.KeyCode==Enum.KeyCode.Escape then closeMenu()end end))
  local group=mk('CanvasGroup',screen,{Name='Window',AnchorPoint=Vector2.new(.5,.5),Position=state.windowPosition or (tonumber(state.windowSettings.x)and tonumber(state.windowSettings.y)and UDim2.fromOffset(state.windowSettings.x,state.windowSettings.y))or UDim2.fromScale(.5,.5),Size=UDim2.fromOffset(860,600),BackgroundTransparency=1,GroupTransparency=0})
  local scale=mk('UIScale',group,{Scale=1})
  local root=rounded(mk('Frame',group,{Name='Hub',Size=UDim2.fromScale(1,1),BackgroundColor3=C.base,BorderSizePixel=0,ClipsDescendants=true}),15)
  stroke(root,C.line);state.chrome.attach(root)
  if firstBoot then startup(screen,group)end
  widgetRefs.header=mk('Frame',root,{Name='Header',Size=UDim2.new(1,0,0,59),BackgroundTransparency=1,Active=true})
   state.themes.decorate(root)
   state.themes.art.attach(group,root,widgetRefs.header)
  mk('Frame',widgetRefs.header,{Position=UDim2.new(0,0,1,-1),Size=UDim2.new(1,0,0,1),BackgroundColor3=C.line,BorderSizePixel=0})
