          if isMini then x=math.clamp(x,4,math.max(4,view.X-target.AbsoluteSize.X-4));y=math.clamp(y,4,math.max(4,view.Y-target.AbsoluteSize.Y-4));widgetRefs.miniDragged=true;widgetRefs.miniDragUntil=os.clock()+.25 end
          target.Position=UDim2.fromOffset(x,y)
