      if active==event then active=nil;if isMini and moved then widgetRefs.miniDragUntil=os.clock()+.25 elseif isMini then restore()elseif moved then state.windowSettings.x=target.Position.X.Offset;state.windowSettings.y=target.Position.Y.Offset;saveSettings()end end
