  widgetRefs.notice=noticeView(1).panel
  widgetRefs.fitNotice=function()
   local camera=workspace.CurrentCamera;local width=math.min(360,(camera and camera.ViewportSize.X or 1000)-24)
   state.notifications.effectiveLimit=math.min(5,math.max(1,math.floor(((camera and camera.ViewportSize.Y or 800)-24)/164)))
   local ordered={}
   for slot=1,5 do local view=noticeViews[slot];if view and view.panel.Visible then ordered[#ordered+1]=view end end
   table.sort(ordered,function(a,b)return (a.record and a.record.id or 0)>(b.record and b.record.id or 0)end)
   local y=12
   for _,view in ipairs(ordered)do
    if view and view.panel.Visible then
     local height=math.clamp(math.ceil(#view.message.Text/48)*15,24,75)
     local ok,size=pcall(function()return game:GetService('TextService'):GetTextSize(view.message.Text,11,Enum.Font.GothamMedium,Vector2.new(width-28,500))end)
     if ok and size then height=math.clamp(size.Y+3,24,75)end
     view.message.Size=UDim2.new(1,-28,0,height)
     view.action.Position=UDim2.new(1,-122,0,42+height)
     local total=height+(view.action.Visible and 82 or 45)
