  state.activityRefresh=function()
    local now=os.clock()
    if state.closed or not widgetRefs.taskHUD.panel.Parent then return end
    widgetRefs.refreshBindings()
    local taskLease=state.work.lease
    local hudTitle,hudStage='Idle','No active automation'
    if taskLease and taskLease.owner~='manual' then
      local owner=tostring(taskLease.owner or 'Automation')
      hudTitle,hudStage=state.activityView(taskLease)
      if state.activityTravel[taskLease.travelState] then hudStage=hudStage..' · '..state.activityTravel[taskLease.travelState] end
    elseif state.work.pending then hudTitle='Queued';hudStage=tostring(state.work.pending.name)
    elseif state.setup.active then hudTitle='Skeleton Key Farm';hudStage=tostring(state.setup.status)
    elseif state.running then hudTitle=state.paused and 'Ghost Quest · Paused' or 'Ghost Quest';hudStage=state.quest.display().status
    elseif state.manual.enabled then hudTitle='Manual Fly';hudStage=state.manual.status
    elseif farmConfig.anySelected() then hudTitle=farmConfig.masterEnabled and 'Farms · Idle' or 'Farms · Paused';hudStage=farmConfig.masterEnabled and 'Waiting for selected activities' or 'Auto Farm off · selections saved' end
    -- Recovery is a separate, time-sensitive state: show it above the farm
    -- stage instead of letting an old pickup/travel message hide it.
    if taskLease and taskLease.rubberbandRecovery then
      local recovery=taskLease.rubberbandRecovery
      if recovery.kind=='pause' then
        hudStage='Movement recovery · Flight and noclip OFF (2s pause)'
      elseif recovery.kind=='ascent' then
        hudStage='Movement recovery · '..tostring(state.navigationStatus or 'Ascending to recovery altitude')
      end
    end
    -- Show temporary work without hiding the parent robbery's status.
    -- The five-second sell countdown is visible even while a farm still owns movement.
    local auxiliary={}
    if bag.autoSellDeadline and bag.autoSellEnabled and bag.nearFull and not bag.selling then
      local remaining=math.max(0,math.ceil(bag.autoSellDeadline-now))
      if remaining>0 then table.insert(auxiliary,'Bag sale in '..remaining..'s')
      end
    end
    if state.ammo and state.ammo.running and (not taskLease or taskLease.owner~='ammo') then
      table.insert(auxiliary,'Ammo · '..tostring(state.ammo.status or 'Purchasing'))
    end
    if state.shop and state.shop.running and (not taskLease or taskLease.owner~='shop') then
      table.insert(auxiliary,'Shop · '..tostring(state.shopState and state.shopState.status or 'Purchasing'))
    end
    if jewelry.passiveBuying then table.insert(auxiliary,'Supplies · '..tostring(jewelry.supplyStatus or 'Checking'))end
    local combatLeft=state.combatRemaining()
    if combatLeft and combatLeft>0 then table.insert(auxiliary,'Combat · '..combatLeft..'s left')end
    local v=combat.v30.settings;local modes={}
    for _,mode in ipairs({{v.aim.enabled,'Silent Aim'},{v.esp.enabled,'ESP'},{v.hbe.enabled,'HBE'},{v.legacy.loopbring,'Loopbring'},{v.experimental.instantBullets,'Instant Bullets'},{v.experimental.noSpread,'No Spread'},{v.experimental.noRecoil,'No Recoil'},{v.projectile.tracers,'Tracers'},{v.weaponSwitch.enabled,'Quick Switch'}})do if mode[1]then modes[#modes+1]=mode[2]end end
    if #modes>0 then table.insert(auxiliary,'Combat · '..table.concat(modes,', '))end
    if #auxiliary>0 then
      hudStage=tostring(hudStage)..'\n'..table.concat(auxiliary,' · ')
    end
    widgetRefs.taskHUD.status.Text=hudTitle
    widgetRefs.taskHUD.stage.Text=tostring(hudStage)
    local queued=state.work.pending and ('Queued · '..tostring(state.work.pending.name)) or state.work.resumeQueue[1] and ('Next · '..state.work.resumeQueue[1].name) or state.sellRequested and not bag.selling and 'Queued · Bag sale' or ''
    local queueCount=(state.work.pending and 1 or 0)+#state.work.actionQueue+#state.work.resumeQueue
    if queued~=''and queueCount>1 then queued=queued..' · +'..(queueCount-1)end
    widgetRefs.taskHUD.next.Text=queued;widgetRefs.taskHUD.next.Visible=queued~=''
    local showTimer=taskLease and (taskLease.owner=='jewelry' and jewelry.lastVault and (jewelry.lastVault.drilling or jewelry.lastVault.opened) or taskLease.owner=='bank' and bankFarm.autoMode)
    widgetRefs.taskHUD.timer.Visible=not not showTimer
    widgetRefs.taskHUD.timer.Text=showTimer and (taskLease.owner=='jewelry' and jewelry.timerSummary() or bankFarm.clockText()) or ''
    local canPause=state.running and(not taskLease or taskLease.owner=='quest')
    widgetRefs.taskHUD.pause.Text=state.paused and 'Resume quest' or 'Pause quest'
    local farmOwner=taskLease and taskLease.owner
    widgetRefs.taskHUD.skip.Visible=farmConfig.masterEnabled and farmConfig.canSkip(farmOwner)
    widgetRefs.taskHUD.pause.Visible=canPause
    widgetRefs.taskHUD.stop.Visible=taskLease~=nil or state.work.pending~=nil or state.running or state.setup.active or farmConfig.masterEnabled
    widgetRefs.taskHUD.stop.Text='Cancel'
    local stageHeight=widgetRefs.taskHUD.stageHeight or 26
    if widgetRefs.taskHUD.lastStage~=tostring(hudStage)then
    local measured,bounds=pcall(function()return game:GetService('TextService'):GetTextSize(tostring(hudStage),12,widgetRefs.taskHUD.stage.Font,Vector2.new(298,1000))end)
    if measured and bounds then stageHeight=math.clamp(math.ceil(bounds.Y)+4,18,64)end
    widgetRefs.taskHUD.stageHeight=stageHeight;widgetRefs.taskHUD.lastStage=tostring(hudStage)
