 function c.parse(text)
  if type(text)~='string'or #text>300 then return nil end
  local verb,target,tail=text:match('^/?([%a]+)%s+(%S+)%s*(.-)%s*$')
  if not verb then return nil end;verb=verb:lower();verb=({unlock='enable',lock='disable',unrlban='unban'})[verb]or verb
  local allowed={reset=1,expose=1,bring=1,kick=2,jail=2,unjail=2,disable=2,enable=2,ban=3,unban=3,rlban=3}
  if not allowed[verb]then return nil end
