  if verb=='disable'then duration,reason=tail:match('^(%S+)%s*(.-)$')else reason=tail end
  return {command=verb,target=target,duration=duration,reason=reason or ''}
 end
 function c.send(text,write)
  local payload=c.parse(text);if not payload then return false end
  if payload.command=='rlban'or payload.command=='unban'then write('REDLINE bans and unbans are owner Key Manager only.');return true end
  if payload.command=='ban'and payload.target:lower()=='all'then write('/ban accepts one player only.');return true end
  if(payload.command=='ban'or payload.command=='rlban')and not state.auth.accountSupported('command_names_v2')then write('Update the server to 2.2.5 before using /ban or /RLban.');return true end
  local target=payload.target:lower();local user=state.auth.user or {}
  if target=='me'or target==player.Name:lower()or target==tostring(user.username or ''):lower()or target=='#'..tostring(user.id)then write('Self-targeting is not allowed.');return true end
  if not state.auth.accountSupported('commands')then write('Update the authentication server to use commands.');return true end
  payload.request_id=HttpService:GenerateGUID(false)
