   write(result and result.message or tostring(err or 'Command failed'))
  end)
  return true
 end
 function c.publicTarget(query,senderId)
  local target=query:lower();local user=state.auth.user or {}
  if user.role=='owner'or senderId==player.UserId then return false end
  if target=='all'then return player.UserId~=senderId end
  if target=='me'then return player.UserId==senderId end
  if target:sub(1,1)=='#'then return target=='#'..tostring(user.id)end
  local matches={};local roster=Players.GetPlayers and Players:GetPlayers()or {player}
  -- Exact Roblox usernames take precedence over prefixes and account aliases.
  for _,candidate in ipairs(roster)do
   if candidate.Name:lower()==target then return candidate.UserId==player.UserId end
  end
  for _,candidate in ipairs(roster)do
   if candidate.Name:lower():sub(1,#target)==target then matches[#matches+1]=candidate end
  end
  if #matches>1 then return false,'Short name matches multiple players; use the full username'end
  if #matches==1 then return matches[1].UserId==player.UserId end
  return target==tostring(user.username or ''):lower()
 end
