  local source=message.TextSource;local uid=source and tonumber(source.UserId)
  if not uid or not Players:GetPlayerByUserId(uid)or type(message.Text)~='string'or message.Text:sub(1,1)~='/'then return end
  local payload=c.parse(message.Text);if not payload then return end
  if payload.command=='rlban'or payload.command=='unban'then note('WARN','REDLINE bans and unbans are owner Key Manager only.');return end
  if payload.command=='ban'then note('WARN','An authenticated owner is required.');return end
  if payload.command=='ban'and payload.target:lower()=='all'then note('WARN','/ban accepts one player only.');return end
  if(payload.command=='ban'or payload.command=='rlban')and not state.auth.accountSupported('command_names_v2')then note('WARN','Update the server to 2.2.5 before using /ban or /RLban.');return end
  local matches,why=c.publicTarget(payload.target,uid)
  if not matches then if why then note('WARN',why)end;return end
  local id=tostring(message.MessageId or ''):gsub('[^%w_-]','')
  if #id<16 or #id>80 or c.chatSeen[id]then return end
  c.chatSeen[id]=os.clock();local count=0
  for key,stamp in pairs(c.chatSeen)do count+=1;if os.clock()-stamp>300 then c.chatSeen[key]=nil end end
  if count>500 then return end
  payload.sender_user_id=uid;payload.request_id=id;payload.target_scope=payload.target:lower()=='all'and 'all'or 'single';payload.target=nil
  task.spawn(function()
   local result,err=state.auth.request('POST','/api/commands/public-self',payload)
   if not result then note('WARN','Public command rejected: '..tostring(err))end
  end)
 end
 function c.start()
  if c.started or not state.auth.accountSupported('commands')then return end
  c.started=true;c.blocked=true;state.accessGranted=false
  local connected,why=pcall(function()
   table.insert(state.connected,game:GetService('TextChatService').MessageReceived:Connect(c.publicMessage))
  end)
  c.chatAvailable=connected
  if not connected then note('WARN','Public command chat listener unavailable: '..tostring(why))end
  local nextDraw=0
  table.insert(state.connected,RunService.Heartbeat:Connect(function()
   if state.closed then return end
   c.freeze()
   if os.clock()>=nextDraw then nextDraw=os.clock()+.25;c.decorate(state.gui)end
  end))
  task.spawn(function()
   while not state.closed and not state.auth.stopped and state.auth.token do
    local response,err,status,detail=state.auth.request('POST','/api/commands/poll',{})
    if state.closed then return end
    if detail and detail.code=='account_banned'then c.banned(detail.reason,true);return end
    if status==401 or status==403 then state.auth.invalidate('Command session revoked or expired');return end
    if response and type(response.controls)=='table'then
     c.setControls(response.controls,response.server_time)
     for _,entry in ipairs(response.commands or {})do c.execute(entry)end
    else
     local problem=tostring(err or 'Command service returned no access state'):gsub('%c',' '):sub(1,160)
     if c.pollError~=problem then note('WARN','Command access check: '..problem)end
     c.pollError=problem;c.decorate(state.gui)
    end
    for _=1,3 do if state.closed then return end;task.wait(1)end
   end
  end)
 end
 function c.stop()
  c.started=false;c.generation+=1;c.endBye();c.releaseJail()
 end
end

local REDLINE_DEPLOYED_AUTH_ORIGIN = "https://redlineauth.pythonanywhere.com"
state.auth={url=REDLINE_DEPLOYED_AUTH_ORIGIN,
 enabled=false,token=nil,user=nil,protected={},ownerListReady=false,verified=false,stopped=false,
 remembered=false,rememberRequested=false,rememberDays=7,sessionDeadline=nil,
 rememberFile='REDLINE_AuthRemember_'..tostring(player.UserId)..'_'..tostring(game.PlaceId)..'.json'}
do
 local auth=state.auth
 auth.enabled=auth.url~=''
 auth.endpointValid=auth.url:match('^https://[%w%.%-]+$')~=nil or auth.url:match('^https://[%w%.%-]+:%d+$')~=nil


 -- The executor's local file is NOT encrypted. Save only the server-issued
 -- bearer session token, never a password, access key or private API secret.
 -- A remembered session is never trusted until /api/me confirms it.
 local REMEMBER_SECONDS=7*24*60*60
 local rememberStore=redlineRememberStore(HttpService,auth.url,player,auth.rememberFile,getgenv and getgenv()or _G)
 function auth.clearRemember()auth.remembered=false;rememberStore.clear()end
 function auth.rememberSave(result)
  if not auth.rememberRequested or not auth.token then auth.remembered=false;return false end
  local ttl=tonumber(result and result.session_expires_in)
  local deadline=math.min(auth.sessionDeadline or math.huge,os.time()+(ttl and math.max(0,ttl)or REMEMBER_SECONDS))
  local retained,persistent=rememberStore.save(auth.token,auth.user and auth.user.id,deadline)
  auth.remembered=retained;auth.rememberPersistent=persistent
  if retained then auth.sessionDeadline=deadline end
  return retained
 end
 function auth.rememberRead()return rememberStore.read()end
 function auth.accessExpired(user)
  if type(user)~='table' then return true,'Invalid account response' end
  if user.enabled==false then return true,'Account disabled' end
  if user.must_change_password==true then return true,'Password change required' end
  local stamp=user.access_expires_at
  if stamp==nil or stamp=='' then return false end
  local seconds=tonumber(stamp)
  if not seconds and type(stamp)=='string'then
   local ok,date=pcall(DateTime.fromIsoDate,stamp)
   if ok and date then seconds=date.UnixTimestamp end
  end
  -- Unparseable dates are not authorization evidence; server /api/me
  -- remains authoritative and must enforce timed-key expiration.
  if seconds and seconds<=os.time() then return true,'Timed access key expired',seconds end
  return false,nil,seconds
 end
 function auth.request(method,path,body,bearer)
  if not auth.enabled or not auth.endpointValid then return nil,'Authentication server is not configured for this device' end
  local fn=transport()
  if not fn then return nil,'Executor HTTP request unavailable' end
  local headers={['Content-Type']='application/json'}
  local token=bearer~=false and(bearer or auth.token)or nil
  if token then headers.Authorization='Bearer '..token end
  local opts={Url=auth.url..path,Method=method,Headers=headers}
  if body then opts.Body=type(body)=='table'and next(body)==nil and '{}'or HttpService:JSONEncode(body)end
  auth.pending=auth.pending or {};local requestKey=method..' '..path
  if auth.pending[requestKey]then return nil,'Previous request is still pending; duplicate request withheld'end
  local pending={};auth.pending[requestKey]=pending
  local returned=false;local ok,response
  task.spawn(function()ok,response=pcall(fn,opts);returned=true;if auth.pending[requestKey]==pending then auth.pending[requestKey]=nil end end)
  local deadline=os.clock()+15
  while not returned and not state.closed and os.clock()<deadline do task.wait(.05)end
  if not returned then return nil,'Authentication request timed out; verify account/session state before retrying'end
  if not ok or type(response)~='table' then return nil,'Could not reach the authentication server' end
