 function auth.closeDialogs()
  for _,name in ipairs({'recoveryGui','renewalGui'})do local dialog=auth[name];if dialog and dialog.Parent then dialog:Destroy()end;auth[name]=nil end
 end
 function auth.keyValid(value)
  if type(value)~='string'then return false end
  local clean=value:match('^%s*(.-)%s*$')or ''
