   if not auth.token then return end
   auth.clearRemember();local token=auth.token
   task.spawn(function()auth.request('POST','/api/logout',{},token)end)
   auth.invalidate('Logged out')
  end,100)
  local redeem=card(parent,'Redeem key')
  hint(redeem,'Extend access on this account.')
  local key=auth.secretField(redeem,'Redeem key','REDLINE key')
  local resultText=hint(redeem,'');resultText.TextColor3=C.pink
  local busy=false;local button
  button=action(line(redeem,'Apply to this account'),'Redeem',function()
   if busy then return end
   if not auth.accountSupported('account_redeem')then resultText.Text='Update the authentication server to redeem keys.';return end
   if key.Text==''then resultText.Text='Enter an access key.';return end
   busy=true;button.Active=false;resultText.Text='Redeeming…';local token=auth.token;local code=key.Text
   task.spawn(function()
