     local accepted,why=auth.acceptUser(result)
     if not accepted then resultText.Text=tostring(why);return end
     key.Text='';auth.ownerListReady=false;task.spawn(auth.updateOwners)
     if auth.rememberRequested then auth.rememberSave(result)end
