 function auth.resetStartup()
  local v=combat.v30
  local bindings,keyMode=v.copy(v.settings.bindings),v.settings.keyMode
  v.settings=v.copy(v.defaults);v.settings.bindings=bindings;v.settings.keyMode=keyMode;v.syncLegacy()
