 function auth.bindStorage()
  local id=auth.user and tonumber(auth.user.id)
  if not id or id<=0 or id%1~=0 then auth.invalidate('Invalid REDLINE account identity');return true end
  if state.accountId==id then return false end
  if reloadState and reloadState.accountId then auth.invalidate('Account identity changed; sign in again');return true end
  -- This handoff is generated only from the live-authenticated response in this boot.
  -- No gameplay, preset startup, or command service starts in the unbound generation.
  local saved={token=auth.token,expires_at=auth.sessionDeadline,remembered=auth.remembered,rememberRequested=auth.rememberRequested,
   handoff={token=auth.token,at=os.clock(),health=auth.health,response={user=auth.user,session_expires_in=math.max(0,(auth.sessionDeadline or os.time())-os.time())}}}
  local nextBoot={accountId=id,auth=saved}
  local ok,why=pcall(state.close,true,true)
  if not ok then note('ERROR','Account initialization cleanup failed: '..tostring(why));return true end
  task.defer(function()
   local started,err=pcall(redlineBoot,nextBoot)
