   handoff.health and handoff.response and handoff.response.user and tonumber(handoff.response.user.id)==state.accountId then
   local startup={saved=saved,health=handoff.health,me=handoff.response,healthDone=true,meDone=true,started=os.clock()}
   auth.startupSaved=startup;return startup
  end
