 function auth.acceptUser(response)
  local candidate=response and response.user
  if type(candidate)~='table'then return false,'Account response incomplete'end
  if auth.verified and auth.user and auth.user.id~=candidate.id then return false,'Account changed; sign in again'end
  local previous=auth.user and auth.user.license;local incoming=candidate.license
  if auth.verified and type(previous)=='table'and type(incoming)=='table'and
   tonumber(previous.revision)and tonumber(incoming.revision)and incoming.revision<previous.revision then
   return true,'Older license response ignored'
  end
