 -- Maintenance disconnect is global to REDLINE, independent of in-game command levels and staff immunity.
 function auth.maintenanceCounter(value)
  return type(value)=='number'and value==value and value>=0 and value<9007199254740992 and value%1==0 and value or nil
 end
 function auth.seedMaintenance(user)
  if auth.maintenanceGeneration~=nil then return end
  local license=type(user)=='table'and user.license
  auth.maintenanceGeneration=auth.maintenanceCounter(type(license)=='table'and license.pause_generation or nil)
 end
 function auth.maintenanceKick()
  if auth.maintenanceTriggered or state.closed or auth.stopped or not auth.verified or not state.accessGranted then return false end
  auth.maintenanceTriggered=true
  -- Maintenance is not revocation or Logout. Keep the remembered session record for a later server revalidation.
  auth.stopped=true;auth.token=nil;auth.verified=false;auth.ownerListReady=false;state.accessGranted=false
  state.sellRequested=false
  if state.teams then state.teams.token=state.teams.token+1;state.teams.requested=nil end
  if state.autoFarmConfig then state.autoFarmConfig.masterEnabled=false;state.autoFarmConfig.pendingDisable=false end
  bag.autoSellEnabled=false
  local cleaned=false
  if state.close then cleaned=pcall(state.close,true)end
  if not cleaned then
   -- A failed teardown must not suppress the mandatory disconnect.
   for _,cleanup in ipairs({function()if bankFarm.autoMode or bankFarm.running then bankFarm.stop()end end,
    function()if af.enabled or af.running then afStop()end end,function()bank.stop()end,
    function()stop()end,function()endCombat()end,function()if state.manual then state.manual.set(false)end end,
    function()stopMotion(true)end,function()state.collision.owners={};restoreCollision()end})do pcall(cleanup)end
   state.closed=true
  end
  state.closed=true
  local kicked=pcall(function()player:Kick('REDLINE is currently down for maintenance. Please check Discord Status for updates.')end)
  if not kicked then pcall(note,'WARN','Maintenance disconnect could not complete; local REDLINE access is disabled')end
  return true
 end
 function auth.observeMaintenance(data)
  if type(data)~='table'or data.ok~=true or type(data.paused)~='boolean'then return false end
  if data.paused then return auth.maintenanceKick()end
  local generation=auth.maintenanceCounter(data.pause_generation)
  if generation~=nil then
