 function auth.startMaintenanceMonitoring()
  if not auth.enabled or not auth.verified or not auth.token or not state.accessGranted or auth.maintenanceMonitorStarted then return end
  auth.seedMaintenance(auth.user);auth.maintenanceMonitorStarted=true
  task.spawn(function()
   while not state.closed and not auth.stopped and auth.token do
    local token=auth.token
    -- A separate monitor is not delayed by the normal presence/owner-list refresh work.
    local data=auth.request('GET','/api/access/status',nil,false)
    if state.closed or auth.stopped or auth.token~=token then break end
    if auth.observeMaintenance(data)then break end
    task.wait(5)
   end
