 function auth.startMonitoring()
  if not auth.enabled or not auth.token or auth.monitorStarted then return end
  auth.startMaintenanceMonitoring()
  auth.monitorStarted=true
  task.spawn(function()
   local lastOwners,lastMe,failedMe=auth.lastOwnersAt or 0,auth.lastVerifiedMe,0
   local nextPresence=0;local retryAt=0
   while not state.closed and not auth.stopped and auth.token do
    local clock,wall=os.clock(),os.time()
    if clock>=retryAt and auth.refreshDue(lastMe,clock,wall)then
     local token=auth.token
     local who,err,status,detail=auth.request('GET','/api/me')
     if state.closed or auth.stopped or auth.token~=token then break end
     lastMe=os.clock()
     if detail and detail.code=='access_paused'then auth.maintenanceKick();break end
     if detail and detail.code=='account_banned'and state.commands then state.commands.banned(detail.reason,true);break end
     if status==401 or status==403 then auth.invalidate('Your login was revoked or expired');break end
     if who and who.user then
      local accepted,reason=auth.acceptUser(who)
      if not accepted then auth.invalidate(reason);break end
      failedMe=0;retryAt=0
      if auth.rememberRequested then auth.rememberSave(who)end
     else
      failedMe+=1;auth.ownerListReady=false
      if failedMe>=3 then auth.invalidate('Authentication service unreachable after repeated session checks');break end
      note('WARN','Authentication session check unavailable ('..failedMe..'/3); retrying soon')
      retryAt=os.clock()+15;lastMe=nil
     end
    end
    -- Expired cached metadata never becomes offline authorization. A live response above
    -- may extend access; otherwise policy gates stop affected work while verification retries.
    if state.license then state.license.enforce()end
    clock=os.clock()
    if clock-lastOwners>=90 or not auth.ownerListReady and clock-lastOwners>=15 then lastOwners=clock;auth.updateOwners()end
    if clock>=nextPresence then
     nextPresence=clock+30
     local _,err,status,detail=auth.request('POST','/api/presence/heartbeat',{
      job_id=tostring(game.JobId or ''),place_id=game.PlaceId,roblox_user_id=player.UserId,roblox_username=player.Name})
     if detail and detail.code=='access_paused'then auth.maintenanceKick();break end
     if detail and detail.code=='account_banned'and state.commands then state.commands.banned(detail.reason,true);break end
     if status==401 or status==403 then auth.invalidate('Session no longer authorized');break end
