 function auth.presenceMembers(data,now)
  local found={};local uncertain=0
  if not auth.isStaff()or type(data)~='table'then return found,uncertain end
  local entries=data.presence or data.users or data.items
  if type(entries)~='table'then return found,uncertain end
  local scopedJob=data.job_id or data.jobId;local scopedPlace=data.place_id or data.placeId
  for _,entry in pairs(entries)do if type(entry)=='table'then
   local uid=tonumber(entry.reported_roblox_user_id or entry.roblox_user_id or entry.robloxUserId)
   if not uid then
    local name=entry.reported_roblox_username or entry.roblox_username or entry.robloxUsername
    local member=type(name)=='string'and Players:FindFirstChild(name)
    if member then uid=member.UserId end
   end
   local job=entry.job_id or entry.jobId or scopedJob
   local place=tonumber(entry.place_id or entry.placeId or scopedPlace)
   local stamp=entry.last_seen_at or entry.last_seen or entry.lastSeen or entry.updated_at or entry.last_heartbeat_at or entry.last_heartbeat or entry.heartbeat_at
   local seen=tonumber(stamp)
   if not seen and type(stamp)=='string'then local ok,date=pcall(DateTime.fromIsoDate,stamp);if ok and date then seen=date.UnixTimestamp end end
   local activity=entry.active==true or entry.online==true or seen and seen<=now+15 and now-seen<=90
   if seen and (seen>now+15 or now-seen>90)then activity=false end
   if not job or not place or not activity then uncertain=uncertain+1 end
   if uid and uid>0 and uid%1==0 and job==tostring(game.JobId or '')and place==game.PlaceId and activity and entry.active~=false and entry.online~=false then
    local role=tostring(entry.role or entry.account_role or ''):lower()
    if role~='owner'and(auth.user.role~='admin'or role=='normal')then found[uid]=true end
   end
  end end
  local localOnly={}
  for _,member in ipairs(Players:GetPlayers())do if found[member.UserId]then localOnly[member.UserId]=true end end
  return localOnly,uncertain
 end
 function auth.presenceRows(data,now,scope)
  local rows={};if not auth.isStaff()or type(data)~='table'then return rows end
  local entries=data.presence or data.users or data.items;if type(entries)~='table'then return rows end
  local localMembers={};for _,member in ipairs(Players:GetPlayers())do localMembers[member.UserId]=member end
  local seen={}
  for _,entry in pairs(entries)do if type(entry)=='table'then
   local uid=tonumber(entry.reported_roblox_user_id or entry.roblox_user_id or entry.robloxUserId)
   local name=entry.reported_roblox_username or entry.roblox_username or entry.robloxUsername
   if not uid and type(name)=='string'then local member=Players:FindFirstChild(name);uid=member and member.UserId end
   local stamp=entry.last_seen_at or entry.last_seen or entry.lastSeen or entry.updated_at or entry.last_heartbeat_at or entry.last_heartbeat or entry.heartbeat_at
   local at=tonumber(stamp);if not at and type(stamp)=='string'then local ok,date=pcall(DateTime.fromIsoDate,stamp);if ok and date then at=date.UnixTimestamp end end
   local active=at and at<=now+15 and now-at<=90 or not at and(entry.active==true or entry.online==true)
   if at and (at>now+15 or now-at>90)then active=false end
   local job=entry.job_id or entry.jobId or data.job_id or data.jobId
   local place=tonumber(entry.place_id or entry.placeId or data.place_id or data.placeId)
   local member=uid and localMembers[uid]
   local admitted=scope=='Global'and job~=nil and place~=nil or scope~='Global'and member and job==tostring(game.JobId or '')and place==game.PlaceId
   if uid and uid>0 and uid%1==0 and not seen[uid]and active and admitted and entry.active~=false and entry.online~=false then
    local role=tostring(entry.role or entry.account_role or ''):lower()
    if role=='owner'or (auth.user.role=='admin'and role~='normal')then continue end
    seen[uid]=true
    rows[#rows+1]={uid=uid,name=member and member.Name or type(name)=='string'and name or ('User '..uid),display=member and member.DisplayName or entry.display_name or name or ('User '..uid),role=role,admin=role=='admin'or role=='owner',job=tostring(job)}
   end
  end end
  table.sort(rows,function(a,b)return a.name:lower()<b.name:lower()end);return rows
 end
 function auth.renderConsole(parent)
