  local scope='Local';local scopeRow=line(controls,'Scope');local scopeButton=action(scopeRow,'Local',function()end,130)
  local users=card(staff,'Users');users.LayoutOrder=3;local roster=scroll(users,150);roster.Name='ActiveREDLINERoster'
  local admins=card(staff,'Admins');admins.LayoutOrder=4;local adminRoster=scroll(admins,120);adminRoster.Name='ActiveREDLINEAdmins'
  local terminal=card(staff,'Command console');terminal.LayoutOrder=1;local output=scroll(terminal,156);output.Name='ConsoleOutput'
