  end
  local function discard()
   snapshot=nil;clearRows(roster);clearRows(adminRoster);staff.Visible=false;users.Visible=false;admins.Visible=false
   if auth.consoleGeneration==generation then auth.consoleGeneration=generation+1;auth.consoleRendered=false;auth.rosterLastReported=nil end
   staff:Destroy()
  end
  auth.clearStaffView=discard
  refresh=function(force)
   if not alive()or inFlight or not force and os.clock()<nextAllowed then return end
   if scope=='Local'and tostring(game.JobId or '')==''then render(true);return end
   inFlight=true;nextAllowed=os.clock()+15;requestSerial+=1;local serial=requestSerial;local session=auth.token;local requestedScope=scope
   task.spawn(function()
    local path='/api/admin/presence'
