   elseif verb=='status'then local taskLease=state.work and state.work.lease;write('Task: '..tostring(taskLease and taskLease.owner or 'Idle')..' · Scope: '..scope)
   elseif verb=='refresh'then refresh();write('Refreshing player reports')
