-- REDLINE v30.7: configurable three/eight-second compact animated introduction.
-- Pre-auth animation only: never skip account verification or start gameplay early.
local function redlineEntrySplash(nextScreen)
  local C={base=Color3.fromRGB(18,21,27),nav=Color3.fromRGB(26,30,37),card=Color3.fromRGB(29,32,41),raised=Color3.fromRGB(39,43,55),line=Color3.fromRGB(67,67,80),red=Color3.fromRGB(158,64,84),soft=Color3.fromRGB(65,39,53),white=Color3.fromRGB(240,242,245),muted=Color3.fromRGB(169,178,190),dim=Color3.fromRGB(164,171,183),green=Color3.fromRGB(101,185,141),pink=Color3.fromRGB(190,92,109),amber=Color3.fromRGB(209,178,120)}
  if reloadState then nextScreen();return end
  local pg=player:WaitForChild('PlayerGui')
  local entry=mk('ScreenGui',pg,{Name='REDLINEEntry',DisplayOrder=179,IgnoreGuiInset=true,ResetOnSpawn=false,ZIndexBehavior=Enum.ZIndexBehavior.Sibling})
  state.entryGui=entry
  local bg=mk('Frame',entry,{Size=UDim2.fromScale(1,1),BackgroundColor3=C.base,BackgroundTransparency=.67,BorderSizePixel=0,Active=true})
  local window=rounded(mk('CanvasGroup',bg,{Name='EightSecondIntro',AnchorPoint=Vector2.new(.5,.5),Position=UDim2.new(.5,0,.5,14),Size=UDim2.fromOffset(354,232),BackgroundColor3=C.card,BorderSizePixel=0,GroupTransparency=1,ClipsDescendants=true}),12)
  local outline=stroke(window,C.line)
  local screenScale=mk('UIScale',window,{Scale=.9})
  local camera=workspace.CurrentCamera
  local function fit()
    camera=workspace.CurrentCamera
    local view=camera and camera.ViewportSize or Vector2.new(820,700)
    screenScale.Scale=math.min(.98,math.max(.48,math.min((view.X-26)/354,(view.Y-26)/232)))
  end
  fit()
  local emblem=rounded(mk('Frame',window,{Position=UDim2.fromOffset(22,23),Size=UDim2.fromOffset(39,39),BackgroundColor3=C.soft,BorderSizePixel=0}),7)
  local diamond=mk('TextLabel',emblem,{Size=UDim2.fromScale(1,1),Text='R',Font=Enum.Font.GothamBold,TextSize=17,BackgroundTransparency=1,TextColor3=C.white})
  mk('TextLabel',window,{Position=UDim2.fromOffset(74,19),Size=UDim2.fromOffset(207,30),BackgroundTransparency=1,Text='REDLINE',TextXAlignment=Enum.TextXAlignment.Left,TextColor3=C.white,TextSize=21,Font=Enum.Font.GothamBold})
  mk('TextLabel',window,{Position=UDim2.fromOffset(75,45),Size=UDim2.fromOffset(204,18),BackgroundTransparency=1,Text='BY '..REDLINE_CREATOR,TextXAlignment=Enum.TextXAlignment.Left,TextColor3=C.muted,TextSize=9,Font=Enum.Font.GothamMedium})
  local liveDot=rounded(mk('Frame',window,{Position=UDim2.fromOffset(283,38),Size=UDim2.fromOffset(8,8),BackgroundColor3=C.pink,BorderSizePixel=0}),20)
  local loaderExit=rounded(mk('TextButton',window,{Name='ExitLoader',Position=UDim2.fromOffset(308,23),Size=UDim2.fromOffset(27,27),Text='',BackgroundColor3=C.raised,BorderSizePixel=0,AutoButtonColor=true}),6)
  local loaderExitIcon=drawIcon(loaderExit,'close',C.white,17);loaderExitIcon.AnchorPoint=Vector2.new(.5,.5);loaderExitIcon.Position=UDim2.fromScale(.5,.5)
  loaderExit.Activated:Connect(function()confirmRedlineUnload(entry,function()if state.close then state.close(true)end end)end)
  mk('Frame',window,{Position=UDim2.fromOffset(20,77),Size=UDim2.fromOffset(314,1),BackgroundColor3=C.line,BorderSizePixel=0})
  local label=mk('TextLabel',window,{Position=UDim2.fromOffset(22,94),Size=UDim2.fromOffset(312,25),BackgroundTransparency=1,Text='Starting REDLINE',TextXAlignment=Enum.TextXAlignment.Left,TextColor3=C.white,TextSize=12,Font=Enum.Font.GothamBold})
  local desc=mk('TextLabel',window,{Position=UDim2.fromOffset(22,120),Size=UDim2.fromOffset(300,19),BackgroundTransparency=1,Text='Preparing interface',TextXAlignment=Enum.TextXAlignment.Left,TextColor3=C.muted,TextSize=11,Font=Enum.Font.GothamMedium})
  local track=rounded(mk('Frame',window,{Position=UDim2.fromOffset(22,159),Size=UDim2.fromOffset(310,5),BackgroundColor3=C.line,BorderSizePixel=0,ClipsDescendants=true}),4)
  local bar=rounded(mk('Frame',track,{Size=UDim2.fromScale(0,1),BackgroundColor3=C.red,BorderSizePixel=0}),4)
  local segments={}
  for i=1,7 do
    segments[i]=rounded(mk('Frame',window,{Position=UDim2.fromOffset(22+(i-1)*19,184),Size=UDim2.fromOffset(12,3),BackgroundColor3=C.line,BorderSizePixel=0}),2)
  end
  local percent=mk('TextLabel',window,{Position=UDim2.fromOffset(276,177),Size=UDim2.fromOffset(56,18),BackgroundTransparency=1,Text='00%',TextXAlignment=Enum.TextXAlignment.Right,TextColor3=C.pink,TextSize=11,Font=Enum.Font.GothamBold})
  mk('TextLabel',window,{Position=UDim2.fromOffset(22,208),Size=UDim2.fromOffset(310,14),BackgroundTransparency=1,Text='v'..REDLINE_VERSION,TextXAlignment=Enum.TextXAlignment.Left,TextColor3=C.dim,TextSize=9,Font=Enum.Font.GothamMedium})
  local duration=state.auth.savedIntroDuration()
  state.diagnostics.mark('entry_intro_duration',tostring(duration)..'s; auth still required')
  local phases={{0,'Starting REDLINE'},{1.1,'Loading theme'},{2.4,'Preparing controls'},{3.6,'Preparing navigation'},{5,'Preparing sign-in'},{6.4,'Almost ready'},{7.4,'Ready'}}
  local started=os.clock()
  local fadeIn=TweenService:Create(window,TweenInfo.new(duration*.0575,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{GroupTransparency=0,Position=UDim2.fromScale(.5,.5)})
  fadeIn:Play()
  task.spawn(function()
    local lastPhase=0;local lastSize;local pauseStart=nil;local pausedTime=0
    while not state.closed and entry.Parent do
      local confirmationOpen=entry:FindFirstChild('REDLINEUnloadConfirmation')~=nil
      if confirmationOpen then pauseStart=pauseStart or os.clock() elseif pauseStart then pausedTime=pausedTime+(os.clock()-pauseStart);pauseStart=nil end
      local elapsed=math.min(duration,os.clock()-started-pausedTime-(pauseStart and (os.clock()-pauseStart) or 0))
      local ratio=math.clamp(elapsed/duration,0,1)
      local phaseClock=ratio*8 -- Scale the original seven visual stages into the selected duration.
      for i=#phases,1,-1 do if phaseClock>=phases[i][1]then
        if lastPhase~=i then lastPhase=i;desc.Text=phases[i][2];desc.TextTransparency=.3 end
        break
      end end
      local ease=1-(1-ratio)^1.1
      bar.Size=UDim2.fromScale(ease,1)
      percent.Text=('%02d%%'):format(math.floor(ratio*100+.5))
      diamond.TextTransparency=.08+.24*(.5+.5*math.sin(elapsed*3.8))
      liveDot.BackgroundTransparency=.14+.49*(.5+.5*math.sin(elapsed*4.8))
      desc.TextTransparency=math.max(0,desc.TextTransparency-.065)
      for i,item in ipairs(segments)do item.BackgroundColor3=ratio>=(i/7) and C.red or C.line end
      if camera~=workspace.CurrentCamera or not lastSize or (workspace.CurrentCamera and (workspace.CurrentCamera.ViewportSize-lastSize).Magnitude>1)then
        fit();lastSize=workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
      end
      local saved=state.auth.startupSaved
      local verifying=saved and not(saved.healthDone and saved.meDone)and os.clock()-saved.started<18
      if elapsed>=duration and verifying then label.Text='Signing in';desc.Text='Checking remembered session';window.GroupTransparency=0 end
      if ratio>=.95625 and not verifying then window.GroupTransparency=math.clamp((ratio-.95625)/.04375,0,1)end
      if elapsed>=duration and not verifying and not confirmationOpen then
        if entry.Parent then entry:Destroy()end
        if not state.closed then nextScreen()end
        return
      end
      task.wait(1/30)
    end
    if entry.Parent then entry:Destroy()end
  end)
end

if state.auth.enabled then state.auth.prepareSavedStartup()end
-- Show Login after the selected introduction; live authorization is still required.
-- Build the REDLINE workspace only after a server-authorized session.
redlineEntrySplash(function()state.auth.show(function()
-- REDLINE UI initialization guard
local uiOK,uiError=pcall(buildWorkspace,false)
if not uiOK then
  warning('Interface initialization failed: '..tostring(uiError))
  if state.close then state.close(true)end
  clearUI()
  local errorGui=mk('ScreenGui',player:WaitForChild('PlayerGui'),{Name='REDLINEInitializationError',ResetOnSpawn=false,DisplayOrder=200})
  local panel=rounded(mk('Frame',errorGui,{AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),Size=UDim2.new(.85,0,0,150),BackgroundColor3=C.card,BorderSizePixel=0}),10)
  mk('UISizeConstraint',panel,{MaxSize=Vector2.new(520,150)});pad(panel,16,16,16,16);stack(panel,8)
  txt(panel,'REDLINE · interface could not initialize',24,15,C.pink,true)
  local detail=txt(panel,tostring(uiError),65,12,C.muted);detail.TextWrapped=true;detail.TextTruncate=Enum.TextTruncate.None
  local dismiss=mk('TextButton',panel,{Size=UDim2.fromOffset(80,26),Text='Close',TextColor3=C.white,BackgroundColor3=C.red,BorderSizePixel=0})
  dismiss.Activated:Connect(function()errorGui:Destroy()end)
  state.close=function()if errorGui.Parent then errorGui:Destroy()end end
  _G.REDLINEHubV28=state
end
end)end)
end

end
redlineBoot()
